        <label><small>계좌번호</small><input id="branchBankAccountNumber" type="text" maxlength="32" inputmode="numeric" autocomplete="off" value="${escapeHtml(bankAccount.account_number || "")}" placeholder="숫자와 하이픈만 입력" /></label>
