(function () {
  const storageKey = "tennis-note-supabase-config";
  const authStorageKey = "tennis-note-supabase-session";
  const authPersistenceKey = "tennis-note-auth-persistence";
  const authContinuityDiagnosticStages = new Set([
    "PERSISTENCE_LOCAL", "PERSISTENCE_SESSION", "SESSION_LOCAL", "SESSION_SESSION",
    "REFRESH_SUCCESS", "REFRESH_REJECTED", "REFRESH_TRANSIENT",
    "REFRESH_NO_TOKEN", "REFRESH_NOT_READY",
  ]);
  let authContinuityDiagnosticCount = 0;
  const oauthCodeVerifierKey = "tennis-note-oauth-code-verifier";
  const oauthAttemptKey = "tennis-note-oauth-attempt";
  const oauthCallbackFingerprintKey = "tennis-note-oauth-callback-fingerprint";
  const nativeUrlFingerprintKey = "tennis-note-native-url-fingerprint";
  const oauthAttemptMaxAgeMs = 15 * 60 * 1000;
  const offlineDatabaseName = "tennis-note-offline-cache";
  const offlineDatabaseVersion = 1;
  const offlineResponseStore = "responses";
  const offlineCacheMaxAgeMs = 7 * 24 * 60 * 60 * 1000;
  const resumableUploadChunkBytes = 6 * 1024 * 1024;
  const resumableUploadThresholdBytes = 6 * 1024 * 1024;
  const resumableUploadStatePrefix = "tennis-note-resumable-upload-v1:";
  const placeholderMarkers = ["your_", "_here", "publishable_key"];
  let sessionRefreshPromise = null;
  let currentProfilePromise = null;
  let pendingOAuthCredentialCapture = Promise.resolve(null);
  let offlineDatabasePromise = null;
  let nativeOAuthInFlightProvider = "";
  let nativeOAuthCallbackInFlight = false;
  let nativeOAuthCancelTimer = null;
  let nativeOAuthLoadTimer = null;
  let nativeOAuthInitialPageLoaded = false;
  let nativeOAuthLoadTimedOut = false;
  let nativeOAuthAttemptStartedAt = 0;
  const nativeOAuthObservations = [];
  let oauthCodeExchangePromise = null;

  function nativeOAuthHost(url) {
    try {
      const parsed = new URL(String(url || ""));
      return parsed.hostname || parsed.protocol.replace(/:$/, "");
    } catch (error) {
      return "";
    }
  }

  function recordNativeOAuthObservation(stage, options = {}) {
    const allowedStages = new Set([
      "authorize_started", "browser_opened", "browser_initial_page_loaded",
      "browser_initial_load_timeout", "browser_finished", "app_foreground",
      "app_url_open", "callback_started", "callback_succeeded", "callback_failed",
    ]);
    if (!allowedStages.has(stage)) return;
    const elapsedMs = nativeOAuthAttemptStartedAt
      ? Math.max(0, Math.min(Date.now() - nativeOAuthAttemptStartedAt, 10 * 60 * 1000))
      : 0;
    nativeOAuthObservations.push({
      stage,
      provider: providerKey(options.provider || nativeOAuthInFlightProvider || storedProvider() || ""),
      host: nativeOAuthHost(options.url),
      elapsedMs,
    });
    if (nativeOAuthObservations.length > 32) nativeOAuthObservations.splice(0, nativeOAuthObservations.length - 32);
    window.dispatchEvent(new CustomEvent("tennisnote:native-oauth-observation", {
      detail: { ...nativeOAuthObservations[nativeOAuthObservations.length - 1] },
    }));
  }

  function clearNativeOAuthLoadTimer() {
    if (nativeOAuthLoadTimer === null) return;
    window.clearTimeout(nativeOAuthLoadTimer);
    nativeOAuthLoadTimer = null;
  }

  function startNativeOAuthObservation(provider, authorizeUrl) {
    clearNativeOAuthLoadTimer();
    nativeOAuthAttemptStartedAt = Date.now();
    nativeOAuthInitialPageLoaded = false;
    nativeOAuthLoadTimedOut = false;
    recordNativeOAuthObservation("authorize_started", { provider, url: authorizeUrl });
    nativeOAuthLoadTimer = window.setTimeout(() => {
      nativeOAuthLoadTimer = null;
      if (!nativeOAuthInFlightProvider || nativeOAuthCallbackInFlight || nativeOAuthInitialPageLoaded) return;
      nativeOAuthLoadTimedOut = true;
      recordNativeOAuthObservation("browser_initial_load_timeout", { provider });
    }, 15_000);
  }

  function emitClientError(stage, error, context = {}) {
    const value = error || new Error(stage || "client_error");
    window.dispatchEvent(new CustomEvent("tennisnote:client-error", {
      detail: {
        category: "auth",
        stage: String(stage || "unknown"),
        code: String(value?.code || value?.payload?.code || value?.message || "unknown_error"),
        message: String(value?.message || value || "unknown_error"),
        status: Number(value?.status || 0),
        provider: providerKey(context.provider || storedProvider() || ""),
        native: isNativeApp(),
      },
    }));
  }

  function parseStoredConfig() {
    try {
      return JSON.parse(localStorage.getItem(storageKey) || "{}");
    } catch (error) {
      localStorage.removeItem(storageKey);
      return {};
    }
  }

  function compactConfig(source) {
    const supabase = source?.supabase || source || {};
    const authProviderOverrides =
      supabase.authProviderOverrides ||
      supabase.providerOverrides ||
      source?.authProviderOverrides ||
      source?.providerOverrides ||
      {};
    return {
      supabaseUrl: supabase.supabaseUrl || supabase.url || "",
      supabasePublishableKey: supabase.supabasePublishableKey || supabase.publishableKey || supabase.anonKey || "",
      authProviderOverrides,
      environment: supabase.environment || source?.environment || "",
      projectFingerprint: supabase.projectFingerprint || source?.projectFingerprint || "",
      singleSheetImportMode: supabase.singleSheetImportMode || source?.singleSheetImportMode || "off",
      singleSheetImportReverseEnabled: supabase.singleSheetImportReverseEnabled === true || source?.singleSheetImportReverseEnabled === true,
      nativeOAuthCallbackUrl: supabase.nativeOAuthCallbackUrl || source?.nativeOAuthCallbackUrl || "",
    };
  }

  function loadConfig() {
    const fileConfig = compactConfig(window.TENNISNOTE_CONFIG);
    const storedConfig = compactConfig(parseStoredConfig());
    return {
      supabaseUrl: isReadyValue(storedConfig.supabaseUrl) ? storedConfig.supabaseUrl : fileConfig.supabaseUrl,
      supabasePublishableKey: isReadyValue(storedConfig.supabasePublishableKey)
        ? storedConfig.supabasePublishableKey
        : fileConfig.supabasePublishableKey,
      authProviderOverrides: {
        ...(storedConfig.authProviderOverrides || {}),
        ...(fileConfig.authProviderOverrides || {}),
      },
      environment: fileConfig.environment,
      projectFingerprint: fileConfig.projectFingerprint,
      singleSheetImportMode: fileConfig.singleSheetImportMode,
      singleSheetImportReverseEnabled: fileConfig.singleSheetImportReverseEnabled,
      nativeOAuthCallbackUrl: fileConfig.nativeOAuthCallbackUrl,
    };
  }

  function isReadyValue(value) {
    if (!value || typeof value !== "string") return false;
    const cleanValue = value.trim().toLowerCase();
    if (!cleanValue) return false;
    return !placeholderMarkers.some((marker) => cleanValue.includes(marker));
  }

  function readiness() {
    const config = loadConfig();
    const ready = isReadyValue(config.supabaseUrl) && isReadyValue(config.supabasePublishableKey);
    return {
      ready,
      hasUrl: isReadyValue(config.supabaseUrl),
      hasPublishableKey: isReadyValue(config.supabasePublishableKey),
      mode: ready ? "supabase" : "demo",
    };
  }

  function apiUrl(path) {
    const config = loadConfig();
    return `${config.supabaseUrl.replace(/\/$/, "")}/rest/v1/${path.replace(/^\//, "")}`;
  }

  function authUrl(path) {
    const config = loadConfig();
    return `${config.supabaseUrl.replace(/\/$/, "")}/auth/v1/${path.replace(/^\//, "")}`;
  }

  function functionUrl(functionName) {
    const config = loadConfig();
    return `${config.supabaseUrl.replace(/\/$/, "")}/functions/v1/${functionName.replace(/^\//, "")}`;
  }

  function storageObjectUrl(bucketName, objectPath) {
    const config = loadConfig();
    const encodedPath = `${objectPath || ""}`.split("/").map(encodeURIComponent).join("/");
    return `${config.supabaseUrl.replace(/\/$/, "")}/storage/v1/object/${encodeURIComponent(bucketName)}/${encodedPath}`;
  }

  function storageResumableUrl() {
    const config = loadConfig();
    const url = new URL(config.supabaseUrl.replace(/\/$/, ""));
    if (url.hostname.endsWith(".supabase.co")) {
      url.hostname = url.hostname.replace(/\.supabase\.co$/, ".storage.supabase.co");
    }
    url.pathname = "/storage/v1/upload/resumable";
    url.search = "";
    url.hash = "";
    return url.toString();
  }

  function storageMetadataValue(value) {
    const bytes = new TextEncoder().encode(String(value || ""));
    let binary = "";
    for (const byte of bytes) binary += String.fromCharCode(byte);
    return btoa(binary);
  }

  function resumableUploadStateKey(bucketName, objectPath, file) {
    return `${resumableUploadStatePrefix}${bucketName}:${objectPath}:${file.size}:${file.lastModified || 0}`;
  }

  function readResumableUploadUrl(key) {
    try { return localStorage.getItem(key) || ""; } catch { return ""; }
  }

  function writeResumableUploadUrl(key, value) {
    try {
      if (value) localStorage.setItem(key, value);
      else localStorage.removeItem(key);
    } catch { /* 재개 정보 저장 실패가 실제 업로드를 막지 않는다. */ }
  }

  async function resumableRequest(url, options, allowRefresh = true) {
    let response = await fetch(url, options);
    if (response.status === 401 && allowRefresh) {
      const session = await refreshSession().catch(() => null);
      if (session?.access_token) {
        response = await fetch(url, {
          ...options,
          headers: { ...storageAuthHeaders(options.headers || {}, session), Authorization: `Bearer ${session.access_token}` },
        });
      }
    }
    return response;
  }

  async function resumableUploadOffset(uploadUrl) {
    const session = await ensureSession();
    const response = await resumableRequest(uploadUrl, {
      method: "HEAD",
      headers: storageAuthHeaders({ "Tus-Resumable": "1.0.0" }, session),
    });
    if (response.status === 404 || response.status === 410) return null;
    if (!response.ok) throw new Error(`Storage resumable status failed: ${response.status}`);
    const offset = Number(response.headers.get("Upload-Offset"));
    return Number.isFinite(offset) && offset >= 0 ? offset : 0;
  }

  async function createResumableUpload(bucketName, objectPath, file) {
    const session = await ensureSession();
    const response = await resumableRequest(storageResumableUrl(), {
      method: "POST",
      headers: storageAuthHeaders({
        "Tus-Resumable": "1.0.0",
        "Upload-Length": String(file.size),
        "Upload-Metadata": [
          `bucketName ${storageMetadataValue(bucketName)}`,
          `objectName ${storageMetadataValue(objectPath)}`,
          `contentType ${storageMetadataValue(file.type || "application/octet-stream")}`,
          `cacheControl ${storageMetadataValue("3600")}`,
        ].join(","),
        "x-upsert": "false",
      }, session),
    });
    if (!response.ok) throw new Error(await response.text() || `Storage resumable create failed: ${response.status}`);
    const location = response.headers.get("Location");
    if (!location) throw new Error("Storage resumable location missing.");
    return new URL(location, storageResumableUrl()).toString();
  }

  async function uploadObjectResumable(bucketName, objectPath, file, options = {}) {
    if (!isOnline()) throw offlineError();
    const stateKey = resumableUploadStateKey(bucketName, objectPath, file);
    let uploadUrl = readResumableUploadUrl(stateKey);
    let offset = uploadUrl ? await resumableUploadOffset(uploadUrl).catch(() => null) : null;
    if (offset === null) {
      writeResumableUploadUrl(stateKey, "");
      uploadUrl = await createResumableUpload(bucketName, objectPath, file);
      writeResumableUploadUrl(stateKey, uploadUrl);
      offset = 0;
    }
    options.onProgress?.(offset, file.size);
    while (offset < file.size) {
      const end = Math.min(offset + resumableUploadChunkBytes, file.size);
      const chunk = file.slice(offset, end);
      let response = null;
      let lastError = null;
      let offsetResynced = false;
      for (let attempt = 0; attempt < 3; attempt += 1) {
        try {
          const session = await ensureSession();
          response = await resumableRequest(uploadUrl, {
            method: "PATCH",
            headers: storageAuthHeaders({
              "Tus-Resumable": "1.0.0",
              "Upload-Offset": String(offset),
              "Content-Type": "application/offset+octet-stream",
            }, session),
            body: chunk,
          });
          if (response.ok) break;
          if (response.status === 409) {
            const serverOffset = await resumableUploadOffset(uploadUrl);
            if (serverOffset !== null) { offset = serverOffset; response = null; offsetResynced = true; break; }
          }
          lastError = new Error(await response.text() || `Storage resumable upload failed: ${response.status}`);
        } catch (error) { lastError = error; }
        if (attempt < 2) await new Promise((resolve) => window.setTimeout(resolve, 1000 * (2 ** attempt)));
      }
      if (offsetResynced) continue;
      if (!response?.ok) throw lastError || new Error("Storage resumable upload incomplete.");
      const nextOffset = Number(response.headers.get("Upload-Offset"));
      offset = Number.isFinite(nextOffset) && nextOffset > offset ? nextOffset : end;
      options.onProgress?.(offset, file.size);
    }
    writeResumableUploadUrl(stateKey, "");
    return { path: objectPath, resumable: true };
  }

  function getSession() {
    for (const storage of authSessionStores()) {
      try {
        const session = JSON.parse(storage.getItem(authStorageKey) || "null");
        if (!session?.access_token) continue;
        writeStoredSession(session);
        return session;
      } catch (error) {
        try {
          storage.removeItem(authStorageKey);
        } catch (storageError) {
          // Continue to the fallback store when this storage area is unavailable.
        }
      }
    }
    return null;
  }

  function sessionSubject(session = getSession()) {
    const directId = session?.user?.id || "";
    if (directId) return directId;
    const token = `${session?.access_token || ""}`;
    const payloadPart = token.split(".")[1] || "";
    if (!payloadPart) return "";
    try {
      const normalized = payloadPart.replace(/-/g, "+").replace(/_/g, "/");
      const padded = normalized.padEnd(Math.ceil(normalized.length / 4) * 4, "=");
      return JSON.parse(window.atob(padded))?.sub || "";
    } catch (error) {
      return "";
    }
  }

  function isOnline() {
    return navigator.onLine !== false;
  }

  function offlineError(code = "offline_online_required") {
    const error = new Error(code);
    error.code = code;
    error.offline = true;
    return error;
  }

  function isOfflineError(error) {
    return Boolean(error?.offline)
      || ["offline_online_required", "offline_cache_miss"].includes(error?.code || error?.message);
  }

  function openOfflineDatabase() {
    if (!("indexedDB" in window)) return Promise.resolve(null);
    if (!offlineDatabasePromise) {
      offlineDatabasePromise = new Promise((resolve) => {
        let request;
        try {
          request = window.indexedDB.open(offlineDatabaseName, offlineDatabaseVersion);
        } catch (error) {
          resolve(null);
          return;
        }
        request.onupgradeneeded = () => {
          const database = request.result;
          if (!database.objectStoreNames.contains(offlineResponseStore)) {
            const store = database.createObjectStore(offlineResponseStore, { keyPath: "key" });
            store.createIndex("identity", "identity", { unique: false });
            store.createIndex("savedAt", "savedAt", { unique: false });
          }
        };
        request.onsuccess = () => {
          const database = request.result;
          database.onversionchange = () => {
            database.close();
            offlineDatabasePromise = null;
          };
          resolve(database);
        };
        request.onerror = () => resolve(null);
        request.onblocked = () => resolve(null);
      });
    }
    return offlineDatabasePromise;
  }

  function resetOfflineDatabase(database) {
    try {
      database?.close();
    } catch (error) {
      // The connection may already be closing.
    }
    offlineDatabasePromise = null;
  }

  async function runOfflineTransaction(mode, handler) {
    for (let attempt = 0; attempt < 2; attempt += 1) {
      const database = await openOfflineDatabase();
      if (!database) return null;
      try {
        const transaction = database.transaction(offlineResponseStore, mode);
        return await handler(transaction);
      } catch (error) {
        resetOfflineDatabase(database);
      }
    }
    return null;
  }

  function offlineResponseKey(path, session = getSession()) {
    const identity = sessionSubject(session);
    return identity ? `${identity}:${path}` : "";
  }

  async function readOfflineResponse(path, session = getSession()) {
    const key = offlineResponseKey(path, session);
    if (!key) return null;
    return runOfflineTransaction("readonly", (transaction) => new Promise((resolve) => {
      const request = transaction.objectStore(offlineResponseStore).get(key);
      request.onsuccess = () => {
        const record = request.result;
        if (!record || Date.now() - Number(record.savedAt || 0) > offlineCacheMaxAgeMs) {
          resolve(null);
          return;
        }
        resolve(record.payload);
      };
      request.onerror = () => resolve(null);
      transaction.onabort = () => resolve(null);
    }));
  }

  async function writeOfflineResponse(path, payload, session = getSession()) {
    const identity = sessionSubject(session);
    const key = offlineResponseKey(path, session);
    if (!key) return false;
    return (await runOfflineTransaction("readwrite", (transaction) => new Promise((resolve) => {
      transaction.objectStore(offlineResponseStore).put({
        key,
        identity,
        savedAt: Date.now(),
        payload,
      });
      transaction.oncomplete = () => resolve(true);
      transaction.onerror = () => resolve(false);
      transaction.onabort = () => resolve(false);
    }))) === true;
  }

  async function clearOfflineResponses(identity = sessionSubject()) {
    if (!identity) return false;
    return (await runOfflineTransaction("readwrite", (transaction) => new Promise((resolve) => {
      const index = transaction.objectStore(offlineResponseStore).index("identity");
      const request = index.openKeyCursor(window.IDBKeyRange.only(identity));
      request.onsuccess = () => {
        const cursor = request.result;
        if (!cursor) return;
        transaction.objectStore(offlineResponseStore).delete(cursor.primaryKey);
        cursor.continue();
      };
      transaction.oncomplete = () => resolve(true);
      transaction.onerror = () => resolve(false);
      transaction.onabort = () => resolve(false);
    }))) === true;
  }

  function sessionPersistence() {
    return window.localStorage.getItem(authPersistenceKey) === "session" ? "session" : "local";
  }

  function recordAuthContinuityDiagnostic(stage, present = true) {
    const plugin = window.Capacitor?.Plugins?.AuthDiagnostics;
    if (!plugin?.record || !authContinuityDiagnosticStages.has(stage) || authContinuityDiagnosticCount >= 32) return;
    authContinuityDiagnosticCount += 1;
    try {
      Promise.resolve(plugin.record({ stage, present: present === true, status: 0 })).catch(() => {});
    } catch (error) {
      // Internal QA observation must never alter authentication.
    }
  }

  function storageHas(storage, key) {
    try {
      return Boolean(storage.getItem(key));
    } catch (error) {
      return false;
    }
  }

  function recordAuthSessionStartup() {
    const persistence = sessionPersistence();
    recordAuthContinuityDiagnostic("PERSISTENCE_LOCAL", persistence === "local");
    recordAuthContinuityDiagnostic("PERSISTENCE_SESSION", persistence === "session");
    recordAuthContinuityDiagnostic("SESSION_LOCAL", storageHas(window.localStorage, authStorageKey));
    recordAuthContinuityDiagnostic("SESSION_SESSION", storageHas(window.sessionStorage, authStorageKey));
  }

  function authSessionStores() {
    return sessionPersistence() === "session"
      ? [window.sessionStorage]
      : [window.localStorage, window.sessionStorage];
  }

  function setSessionPersistence(remember) {
    const current = getSession();
    window.localStorage.setItem(authPersistenceKey, remember ? "local" : "session");
    if (remember) {
      if (current?.access_token) window.localStorage.setItem(authStorageKey, JSON.stringify(current));
      return "local";
    }
    if (current?.access_token) window.sessionStorage.setItem(authStorageKey, JSON.stringify(current));
    window.localStorage.removeItem(authStorageKey);
    window.localStorage.removeItem(`${authStorageKey}-provider`);
    return "session";
  }

  function ensureNativePersistentAuthSession() {
    if (!isNativeApp()) return sessionPersistence();
    return setSessionPersistence(true);
  }

  function writeStoredSession(session) {
    const serialized = JSON.stringify(session);
    authSessionStores().forEach((storage) => {
      try {
        storage.setItem(authStorageKey, serialized);
      } catch (error) {
        // One available storage area is enough to keep the signed-in session.
      }
    });
    if (sessionPersistence() === "session") {
      try {
        window.localStorage.removeItem(authStorageKey);
      } catch (error) {
        // The active tab session remains available.
      }
    }
  }

  function removeStoredSession() {
    window.dispatchEvent(new Event("tennisnote:auth-session-cleared"));
    authSessionStores().forEach((storage) => {
      try {
        storage.removeItem(authStorageKey);
      } catch (error) {
        // Keep clearing the other storage area.
      }
    });
  }

  function storedProvider() {
    for (const storage of authSessionStores()) {
      try {
        const provider = storage.getItem(`${authStorageKey}-provider`);
        if (provider) return provider;
      } catch (error) {
        // Continue to the fallback store.
      }
    }
    return "";
  }

  function saveProvider(provider) {
    authSessionStores().forEach((storage) => {
      try {
        storage.setItem(`${authStorageKey}-provider`, provider);
      } catch (error) {
        // One available storage area is enough.
      }
    });
  }

  function saveSession(session) {
    if (!session?.access_token) return null;
    const rawExpiresAt = Number(session.expires_at || 0);
    const normalized = {
      access_token: session.access_token,
      refresh_token: session.refresh_token || "",
      token_type: session.token_type || "bearer",
      expires_at: rawExpiresAt
        ? (rawExpiresAt < 1_000_000_000_000 ? rawExpiresAt * 1000 : rawExpiresAt)
        : (session.expires_in ? Date.now() + Number(session.expires_in) * 1000 : 0),
      provider: session.provider || storedProvider() || "Supabase",
    };
    writeStoredSession(normalized);
    return normalized;
  }

  function sessionNeedsRefresh(session) {
    if (!session?.access_token) return false;
    const expiresAt = Number(session.expires_at || 0);
    return Boolean(expiresAt && Date.now() >= expiresAt - 60_000);
  }

  function wait(milliseconds) {
    return new Promise((resolve) => window.setTimeout(resolve, milliseconds));
  }

  function oauthStorageValue() {
    let attempt = null;
    for (const storage of authSessionStores()) {
      try {
        attempt = JSON.parse(storage.getItem(oauthAttemptKey) || "null");
        if (attempt) break;
      } catch (error) {
        try { storage.removeItem(oauthAttemptKey); } catch (storageError) { /* best effort */ }
      }
    }
    if (attempt && Date.now() - Number(attempt.startedAt || 0) > oauthAttemptMaxAgeMs) {
      clearOAuthStorageValue();
      return "";
    }
    for (const storage of authSessionStores()) {
      try {
        const value = storage.getItem(oauthCodeVerifierKey);
        if (value) return value;
      } catch (error) {
        // Continue with the fallback storage area.
      }
    }
    return "";
  }

  function clearOAuthStorageValue() {
    authSessionStores().forEach((storage) => {
      try { storage.removeItem(oauthCodeVerifierKey); } catch (error) { /* best effort */ }
      try { storage.removeItem(oauthAttemptKey); } catch (error) { /* best effort */ }
    });
  }

  function oauthCodeFingerprint(code) {
    let hash = 2166136261;
    const value = String(code || "");
    for (let index = 0; index < value.length; index += 1) {
      hash ^= value.charCodeAt(index);
      hash = Math.imul(hash, 16777619);
    }
    return `${(hash >>> 0).toString(36)}:${value.length}`;
  }

  function handledOAuthCode(code) {
    try {
      const saved = JSON.parse(window.sessionStorage.getItem(oauthCallbackFingerprintKey) || "null");
      return saved?.fingerprint === oauthCodeFingerprint(code)
        && Date.now() - Number(saved?.handledAt || 0) < oauthAttemptMaxAgeMs;
    } catch (error) {
      return false;
    }
  }

  function rememberOAuthCode(code) {
    try {
      window.sessionStorage.setItem(oauthCallbackFingerprintKey, JSON.stringify({
        fingerprint: oauthCodeFingerprint(code),
        handledAt: Date.now(),
      }));
    } catch (error) {
      // The saved session still prevents a second login when session storage is unavailable.
    }
  }

  function base64Url(bytes) {
    let binary = "";
    bytes.forEach((byte) => { binary += String.fromCharCode(byte); });
    return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
  }

  async function createOAuthPkcePair(provider = "") {
    const bytes = new Uint8Array(48);
    window.crypto?.getRandomValues?.(bytes);
    const verifier = base64Url(bytes);
    if (!verifier || !window.crypto?.subtle) throw new Error("oauth_pkce_unavailable");
    const digest = await window.crypto.subtle.digest("SHA-256", new TextEncoder().encode(verifier));
    const challenge = base64Url(new Uint8Array(digest));
    authSessionStores().forEach((storage) => {
      try { storage.setItem(oauthCodeVerifierKey, verifier); } catch (error) { /* fallback storage may still work */ }
      try {
        storage.setItem(oauthAttemptKey, JSON.stringify({
          provider: providerKey(provider),
          startedAt: Date.now(),
        }));
      } catch (error) { /* fallback storage may still work */ }
    });
    return { challenge };
  }

  async function exchangeOAuthCode(code) {
    if (handledOAuthCode(code) && getSession()?.access_token) return getSession();
    if (oauthCodeExchangePromise) return oauthCodeExchangePromise;
    oauthCodeExchangePromise = performOAuthCodeExchange(code).finally(() => {
      oauthCodeExchangePromise = null;
    });
    return oauthCodeExchangePromise;
  }

  async function performOAuthCodeExchange(code) {
    const verifier = oauthStorageValue();
    if (!code || !verifier) {
      const error = new Error("oauth_code_verifier_missing");
      emitClientError("oauth_code_exchange", error);
      throw error;
    }
    const config = loadConfig();
    const response = await fetch(authUrl("token?grant_type=pkce"), {
      method: "POST",
      headers: { apikey: config.supabasePublishableKey, "Content-Type": "application/json" },
      body: JSON.stringify({ auth_code: code, code_verifier: verifier }),
    });
    if (!response.ok) {
      const error = Object.assign(new Error("oauth_code_exchange_failed"), { status: response.status });
      emitClientError("oauth_code_exchange", error);
      throw error;
    }
    const payload = await response.json();
    clearOAuthStorageValue();
    const session = saveSession({ ...payload, provider: storedProvider() || "Supabase" });
    rememberOAuthCode(code);
    return session;
  }

  function transientNetworkError(error) {
    const message = String(error?.message || error || "").toLowerCase();
    return error instanceof TypeError
      || message.includes("failed to fetch")
      || message.includes("networkerror")
      || message.includes("load failed");
  }

  function isTransientConnectionError(error) {
    const message = String(error?.code || error?.message || error || "").toLowerCase();
    return isOfflineError(error)
      || transientNetworkError(error)
      || Number(error?.status || 0) >= 500
      || [
        "session_refresh_temporarily_unavailable",
        "server_request_timeout",
        "request_timeout",
      ].some((code) => message.includes(code));
  }

  async function performRefreshSession() {
    const session = getSession();
    if (!session?.refresh_token) {
      recordAuthContinuityDiagnostic("REFRESH_NO_TOKEN");
      return null;
    }
    if (!readiness().ready) {
      recordAuthContinuityDiagnostic("REFRESH_NOT_READY");
      return null;
    }
    const config = loadConfig();
    let response = null;
    for (let attempt = 0; attempt < 2; attempt += 1) {
      try {
        response = await fetch(authUrl("token?grant_type=refresh_token"), {
          method: "POST",
          headers: {
            apikey: config.supabasePublishableKey,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ refresh_token: session.refresh_token }),
        });
        if (response.ok || response.status < 500) break;
      } catch (error) {
        if (!transientNetworkError(error) || attempt === 1) {
          recordAuthContinuityDiagnostic("REFRESH_TRANSIENT");
          throw error;
        }
      }
      await wait(500 * (attempt + 1));
    }
    if (!response) {
      recordAuthContinuityDiagnostic("REFRESH_TRANSIENT");
      const error = new Error("session_refresh_temporarily_unavailable");
      emitClientError("session_refresh", error);
      throw error;
    }
    if (!response.ok) {
      if (response.status === 400 || response.status === 401) {
        recordAuthContinuityDiagnostic("REFRESH_REJECTED");
        removeStoredSession();
        return null;
      }
      recordAuthContinuityDiagnostic("REFRESH_TRANSIENT");
      const error = new Error("session_refresh_temporarily_unavailable");
      emitClientError("session_refresh", error);
      throw error;
    }
    recordAuthContinuityDiagnostic("REFRESH_SUCCESS");
    const payload = await response.json();
    return saveSession({ ...payload, provider: session.provider });
  }

  function refreshSession() {
    if (!sessionRefreshPromise) {
      sessionRefreshPromise = performRefreshSession().finally(() => {
        sessionRefreshPromise = null;
      });
    }
    return sessionRefreshPromise;
  }

  async function ensureSession() {
    const session = getSession();
    if (!session?.access_token || !sessionNeedsRefresh(session)) return session;
    if (!isOnline()) return session;
    return refreshSession();
  }

  function oauthCallbackFailure(params) {
    const error = params?.get?.("error") || "";
    const code = params?.get?.("error_code") || error || "oauth_redirect_failed";
    const description = params?.get?.("error_description") || "";
    return { error, code, description };
  }

  function oauthCallbackWasAlreadyConsumed(failure = {}) {
    return failure.code === "flow_state_already_used"
      || /state\s+has\s+already\s+been\s+used/iu.test(failure.description || "");
  }

  function oauthReplaySessionMatchesAttempt(session) {
    const attemptedProvider = storedProvider();
    const sessionProvider = session?.provider || "";
    return Boolean(
      attemptedProvider
      && sessionProvider
      && providerKey(attemptedProvider) === providerKey(sessionProvider),
    );
  }

  function clearOAuthCallbackLocation() {
    const url = new URL(window.location.href);
    ["code", "error", "error_code", "error_description"].forEach((key) => url.searchParams.delete(key));
    window.history.replaceState({}, document.title, `${url.pathname}${url.search}${url.hash}`);
  }

  function oauthCallbackError(failure = {}) {
    return Object.assign(new Error(failure.error || "oauth_redirect_failed"), {
      code: failure.code || failure.error || "oauth_redirect_failed",
      description: failure.description || "",
    });
  }

  async function consumeOAuthRedirect() {
    const query = new URLSearchParams(window.location.search || "");
    if (query.get("error")) {
      const failure = oauthCallbackFailure(query);
      const session = getSession();
      clearOAuthCallbackLocation();
      if (
        session?.access_token
        && oauthReplaySessionMatchesAttempt(session)
        && oauthCallbackWasAlreadyConsumed(failure)
      ) return session;
      clearOAuthStorageValue();
      const error = oauthCallbackError(failure);
      emitClientError("oauth_callback", error);
      throw error;
    }
    if (query.get("code")) {
      const session = await exchangeOAuthCode(query.get("code"));
      clearOAuthCallbackLocation();
      return session;
    }
    if (!window.location.hash || !window.location.hash.includes("access_token=")) return getSession();
    const session = saveOAuthSession(window.location.hash);
    window.history.replaceState({}, document.title, `${window.location.pathname}${window.location.search}`);
    return session;
  }

  function saveOAuthSession(hash) {
    if (!hash || !hash.includes("access_token=")) return null;
    const params = new URLSearchParams(hash.replace(/^#/, ""));
    const session = saveSession({
      access_token: params.get("access_token"),
      refresh_token: params.get("refresh_token"),
      token_type: params.get("token_type"),
      expires_in: params.get("expires_in"),
    });
    scheduleOAuthProviderCredentialCapture(params, session);
    return session;
  }

  function scheduleOAuthProviderCredentialCapture(params, session) {
    const providerToken = params?.get?.("provider_token") || "";
    const providerRefreshToken = params?.get?.("provider_refresh_token") || "";
    if (providerKey(session?.provider) !== "apple" || (!providerToken && !providerRefreshToken)) {
      pendingOAuthCredentialCapture = Promise.resolve(null);
      return pendingOAuthCredentialCapture;
    }
    pendingOAuthCredentialCapture = invokeFunction("tennisnote-account-deletion", {
      body: {
        action: "capture_apple_token",
        providerToken,
        providerRefreshToken,
      },
    }).catch(() => null);
    return pendingOAuthCredentialCapture;
  }

  function flushOAuthProviderCredentialCapture() {
    return pendingOAuthCredentialCapture;
  }

  function emitOAuthResult(detail) {
    const event = new CustomEvent("tennisnote:oauth-result", {
      detail,
      cancelable: Boolean(detail?.ok),
    });
    window.dispatchEvent(event);
    return event.defaultPrevented;
  }

  function clearNativeOAuthCancelTimer() {
    if (nativeOAuthCancelTimer === null) return;
    window.clearTimeout(nativeOAuthCancelTimer);
    nativeOAuthCancelTimer = null;
  }

  function scheduleNativeOAuthCancellation() {
    if (!nativeOAuthInFlightProvider || nativeOAuthCallbackInFlight) return;
    const provider = nativeOAuthInFlightProvider;
    clearNativeOAuthCancelTimer();
    nativeOAuthCancelTimer = window.setTimeout(() => {
      nativeOAuthCancelTimer = null;
      if (
        nativeOAuthCallbackInFlight
        || nativeOAuthInFlightProvider !== provider
        || getSession()?.access_token
      ) return;
      nativeOAuthInFlightProvider = "";
      clearOAuthStorageValue();
      const loadIncomplete = nativeOAuthLoadTimedOut || !nativeOAuthInitialPageLoaded;
      emitOAuthResult({
        ok: false,
        provider,
        cancelled: !loadIncomplete,
        errorCode: loadIncomplete ? "native_oauth_browser_load_incomplete" : "native_oauth_cancelled",
        retryable: true,
      });
    }, 800);
  }

  function isNativeApp() {
    const capacitor = window.Capacitor;
    return Boolean(capacitor && (capacitor.isNativePlatform?.() || capacitor.getPlatform?.() !== "web"));
  }

  function nativeOAuthBridgeRedirect() {
    const target = window.location.pathname.includes("coach") ? "coach" : "member";
    const config = loadConfig();
    const environment = `${config.environment || ""}`.trim().toLowerCase();
    const configuredUrl = `${config.nativeOAuthCallbackUrl || ""}`.trim();
    const expectedOrigins = {
      development: "https://tennisnote-app-dev.pages.dev",
      production: "https://tennisnote-app.pages.dev",
    };
    const fail = (code) => {
      const error = new Error(code);
      error.code = code;
      throw error;
    };
    if (!configuredUrl || !expectedOrigins[environment]) {
      fail("native_oauth_callback_unconfigured");
    }
    let callback;
    try {
      callback = new URL(configuredUrl);
    } catch (error) {
      fail("native_oauth_callback_invalid");
    }
    if (
      callback.protocol !== "https:"
      || callback.origin !== expectedOrigins[environment]
      || callback.pathname !== "/native-oauth-callback.html"
      || callback.username
      || callback.password
      || callback.search
      || callback.hash
    ) {
      fail("native_oauth_callback_environment_mismatch");
    }
    callback.searchParams.set("target", target);
    return callback.toString();
  }

  function emailAuthRedirect(options = {}) {
    if (typeof options === "string" && options) return options;
    if (options?.redirectTo) return options.redirectTo;
    return isNativeApp()
      ? nativeOAuthBridgeRedirect()
      : `${window.location.origin}${window.location.pathname}${window.location.search}`;
  }

  function nativeUrlFingerprint(url) {
    let hash = 2166136261;
    for (let index = 0; index < url.length; index += 1) {
      hash ^= url.charCodeAt(index);
      hash = Math.imul(hash, 16777619);
    }
    return `${(hash >>> 0).toString(36)}:${url.length}`;
  }

  function recentlyHandledNativeUrl(url) {
    try {
      const saved = JSON.parse(window.sessionStorage.getItem(nativeUrlFingerprintKey) || "null");
      return saved?.fingerprint === nativeUrlFingerprint(url) && Date.now() - Number(saved?.handledAt || 0) < 60_000;
    } catch (error) {
      try {
        window.sessionStorage.removeItem(nativeUrlFingerprintKey);
      } catch (storageError) {
        // Treat unavailable session storage as having no previous callback.
      }
      return false;
    }
  }

  function rememberNativeUrl(url) {
    try {
      window.sessionStorage.setItem(nativeUrlFingerprintKey, JSON.stringify({
        fingerprint: nativeUrlFingerprint(url),
        handledAt: Date.now(),
      }));
    } catch (error) {
      // URL handling still works when session storage is unavailable.
    }
  }

  function forgetNativeUrl() {
    try {
      window.sessionStorage.removeItem(nativeUrlFingerprintKey);
    } catch (error) {
      // There is no stored marker to clear when session storage is unavailable.
    }
  }

  async function handleNativeOAuthUrl(url) {
    if (!url || !url.startsWith("com.tennisclubhouse.tennisnote://oauth/")) return false;
    ensureNativePersistentAuthSession();
    clearNativeOAuthCancelTimer();
    clearNativeOAuthLoadTimer();
    nativeOAuthCallbackInFlight = true;
    const provider = nativeOAuthInFlightProvider || storedProvider() || "간편";
    recordNativeOAuthObservation("callback_started", { provider, url });
    try {
      const parsed = new URL(url);
      const failure = oauthCallbackFailure(parsed.searchParams);
      if (failure.error) {
        const existingSession = getSession();
        if (
          existingSession?.access_token
          && oauthReplaySessionMatchesAttempt(existingSession)
          && oauthCallbackWasAlreadyConsumed(failure)
        ) {
          nativeOAuthInFlightProvider = "";
          await window.Capacitor?.Plugins?.Browser?.close?.().catch?.(() => {});
          recordNativeOAuthObservation("callback_succeeded", { provider, url });
          emitOAuthResult({ ok: true, provider, replayed: true });
          return true;
        }
        clearOAuthStorageValue();
        nativeOAuthInFlightProvider = "";
        await window.Capacitor?.Plugins?.Browser?.close?.().catch?.(() => {});
        recordNativeOAuthObservation("callback_failed", { provider, url });
        const callbackError = oauthCallbackError(failure);
        const normalizedError = failure.error.toLowerCase();
        emitOAuthResult({
          ok: false,
          provider,
          cancelled: ["access_denied", "user_cancelled", "canceled", "cancelled"].includes(normalizedError),
          errorCode: callbackError.code,
        });
        if (!["access_denied", "user_cancelled", "canceled", "cancelled"].includes(normalizedError)) {
          emitClientError("native_oauth_callback", callbackError, { provider });
        }
        return true;
      }
      const code = parsed.searchParams.get("code");
      const callbackType = new URLSearchParams(parsed.hash.replace(/^#/, "")).get("type") || "";
      const session = code
        ? await exchangeOAuthCode(code)
        : saveOAuthSession(parsed.hash);
      if (!session) return false;
      await flushOAuthProviderCredentialCapture();
      nativeOAuthInFlightProvider = "";
      await window.Capacitor?.Plugins?.Browser?.close?.().catch?.(() => {});
      recordNativeOAuthObservation("callback_succeeded", { provider, url });
      const handledWithoutReload = emitOAuthResult({ ok: true, provider, callbackType });
      if (!handledWithoutReload) window.location.reload();
      return true;
    } catch (error) {
      nativeOAuthInFlightProvider = "";
      clearOAuthStorageValue();
      await window.Capacitor?.Plugins?.Browser?.close?.().catch?.(() => {});
      recordNativeOAuthObservation("callback_failed", { provider, url });
      emitOAuthResult({ ok: false, provider, cancelled: false });
      emitClientError("native_oauth_callback", error, { provider });
      return true;
    } finally {
      nativeOAuthCallbackInFlight = false;
    }
  }

  function handleNativePaymentUrl(url) {
    if (!url || !url.startsWith("com.tennisclubhouse.tennisnote://")) return false;
    try {
      const parsed = new URL(url);
      const paymentId = parsed.searchParams.get("paymentId") || "";
      if (!/^[A-Za-z0-9_-]{1,200}$/.test(paymentId)) return false;
      const target = new URL(window.location.href);
      ["paymentId", "code", "message", "pgCode", "pgMessage"].forEach((key) => {
        if (parsed.searchParams.has(key)) target.searchParams.set(key, parsed.searchParams.get(key) || "");
      });
      window.location.assign(target.toString());
      return true;
    } catch (error) {
      return false;
    }
  }

  async function handleNativeAppUrl(url) {
    if (!url || recentlyHandledNativeUrl(url)) return Boolean(url);
    recordNativeOAuthObservation("app_url_open", { url });
    rememberNativeUrl(url);
    const handled = await handleNativeOAuthUrl(url) || handleNativePaymentUrl(url);
    if (!handled) forgetNativeUrl();
    return handled;
  }

  function installNativeOAuthListener() {
    const appPlugin = window.Capacitor?.Plugins?.App;
    if (!isNativeApp() || !appPlugin?.addListener) return;
    appPlugin.addListener("appUrlOpen", ({ url }) => void handleNativeAppUrl(url));
    appPlugin.addListener("appStateChange", ({ isActive }) => {
      if (isActive && nativeOAuthInFlightProvider) {
        recordNativeOAuthObservation("app_foreground", { provider: nativeOAuthInFlightProvider });
      }
    });
    appPlugin.getLaunchUrl?.().then((result) => handleNativeAppUrl(result?.url)).catch(() => {});
    window.Capacitor?.Plugins?.Browser?.addListener?.("browserPageLoaded", () => {
      clearNativeOAuthLoadTimer();
      nativeOAuthInitialPageLoaded = true;
      nativeOAuthLoadTimedOut = false;
      recordNativeOAuthObservation("browser_initial_page_loaded");
    });
    window.Capacitor?.Plugins?.Browser?.addListener?.("browserFinished", () => {
      clearNativeOAuthLoadTimer();
      recordNativeOAuthObservation("browser_finished");
      scheduleNativeOAuthCancellation();
    });
  }

  function authHeaders(extraHeaders = {}, sessionOverride = undefined) {
    const config = loadConfig();
    const session = sessionOverride === undefined ? getSession() : sessionOverride;
    return {
      apikey: config.supabasePublishableKey,
      Authorization: `Bearer ${session?.access_token || config.supabasePublishableKey}`,
      "Content-Type": "application/json",
      ...extraHeaders,
    };
  }

  function storageAuthHeaders(extraHeaders = {}, sessionOverride = undefined) {
    const headers = authHeaders(extraHeaders, sessionOverride);
    const hasExplicitContentType = Object.keys(extraHeaders)
      .some((name) => String(name).toLowerCase() === "content-type");
    if (!hasExplicitContentType) delete headers["Content-Type"];
    return headers;
  }

  function responseErrorPayload(rawText = "") {
    const normalizedText = String(rawText || "").trim();
    if (!normalizedText) return {};
    try {
      const parsed = JSON.parse(normalizedText);
      return parsed && typeof parsed === "object" ? parsed : { message: normalizedText };
    } catch (error) {
      return { message: normalizedText };
    }
  }

  function responseRequestError(response, rawText = "", fallback = "Supabase request failed") {
    const payload = responseErrorPayload(rawText);
    const message = payload.message
      || payload.error_description
      || (typeof payload.error === "string" ? payload.error : "")
      || `${fallback}: ${response?.status || 0}`;
    const error = new Error(message);
    error.status = Number(response?.status || 0);
    error.code = String(payload.code || payload.error_code || "server_request_failed");
    error.payload = payload;
    return error;
  }

  function authorizationFailureNeedsRefresh(error) {
    const status = Number(error?.status || 0);
    const code = String(error?.code || error?.payload?.code || "").toLowerCase();
    const detail = `${code} ${error?.message || ""} ${error?.payload?.message || ""}`.toLowerCase();
    if (status === 401) return true;
    if (["pgrst301", "jwt_expired", "invalid_jwt"].includes(code)) return true;
    return status === 403
      && code === "42501"
      && detail.includes("permission denied for function");
  }

  function expiredRequestSessionError(cause = null) {
    const error = new Error("admin_session_expired");
    error.code = "admin_session_expired";
    error.status = 401;
    error.cause = cause;
    return error;
  }

  async function refreshRejectedRequestSession(error, requestSession, retryAttempted = false) {
    if (retryAttempted || !authorizationFailureNeedsRefresh(error)) return null;
    const latestSession = getSession();
    if (
      latestSession?.access_token
      && latestSession.access_token !== requestSession?.access_token
    ) return latestSession;
    if (!latestSession?.refresh_token) {
      removeStoredSession();
      throw expiredRequestSessionError(error);
    }
    if (!isOnline()) throw expiredRequestSessionError(error);
    const refreshed = await refreshSession();
    if (!refreshed?.access_token) throw expiredRequestSessionError(error);
    return refreshed;
  }

  function transportRequestError(error) {
    if (error?.code === "offline" || error?.code === "offline_cache_miss") return error;
    const transportError = new Error("server_connection_failed");
    transportError.code = "server_connection_failed";
    transportError.status = 0;
    transportError.cause = error;
    return transportError;
  }

  async function request(path, options = {}) {
    if (!readiness().ready) {
      throw new Error("Supabase publishable config is missing. Demo data is still active.");
    }

    const method = `${options.method || "GET"}`.toUpperCase();
    if (!isOnline() && method !== "GET") throw offlineError();
    const session = options.requireCurrentSession === true ? getSession() : await ensureSession();
    if (options.requireCurrentSession === true && !session?.access_token) throw expiredRequestSessionError();
    if (options.requireFresh === true && !isOnline()) throw offlineError("fresh_read_required");
    if (!isOnline() && method === "GET") {
      const cached = await readOfflineResponse(path, session);
      if (cached !== null) return cached;
      throw offlineError("offline_cache_miss");
    }
    let response;
    const controller = new AbortController();
    const timeoutMs = Math.max(
      5_000,
      Number(options.timeoutMs || (method === "GET" ? 45_000 : 30_000)),
    );
    const timeoutId = window.setTimeout(() => controller.abort("request_timeout"), timeoutMs);
    try {
      response = await fetch(apiUrl(path), {
        method,
        ...(options.requireFresh === true ? { cache: "no-store" } : {}),
        headers: {
          ...authHeaders({}, session),
          Prefer: options.prefer || "return=representation",
          ...(options.headers || {}),
        },
        body: options.body ? JSON.stringify(options.body) : undefined,
        signal: controller.signal,
      });
    } catch (error) {
      if (error?.name === "AbortError") {
        const timeoutError = new Error("server_request_timeout");
        timeoutError.code = "server_request_timeout";
        throw timeoutError;
      }
      if (method === "GET" && options.requireFresh !== true && transientNetworkError(error)) {
        const cached = await readOfflineResponse(path, session);
        if (cached !== null) return cached;
        throw offlineError("offline_cache_miss");
      }
      if (transientNetworkError(error)) throw transportRequestError(error);
      throw error;
    } finally {
      window.clearTimeout(timeoutId);
    }

    if (!response.ok) {
      const rawText = await response.text().catch(() => "");
      const requestError = responseRequestError(response, rawText);
      const refreshed = options.retryAuth === false ? null : await refreshRejectedRequestSession(
        requestError,
        session,
        options._authRetryAttempted === true,
      );
      if (refreshed) {
        return request(path, { ...options, _authRetryAttempted: true });
      }
      throw requestError;
    }

    if (response.status === 204) return null;
    let payload;
    try {
      payload = await response.json();
    } catch (error) {
      const responseError = new Error("server_response_invalid");
      responseError.code = "server_response_invalid";
      responseError.status = response.status;
      throw responseError;
    }
    if (method === "GET") void writeOfflineResponse(path, payload, session);
    return payload;
  }

  async function invokeFunction(functionName, options = {}) {
    if (!readiness().ready) {
      throw new Error("Supabase publishable config is missing. Demo data is still active.");
    }

    if (!isOnline()) throw offlineError();
    const session = await ensureSession();
    const response = await fetch(functionUrl(functionName), {
      method: options.method || "POST",
      headers: {
        ...authHeaders({}, session),
        ...(options.headers || {}),
      },
      body: options.body ? JSON.stringify(options.body) : undefined,
    });
    const payload = await response.json().catch(() => ({}));

    if (!response.ok) {
      const error = new Error(payload.message || payload.code || `Supabase function failed: ${response.status}`);
      error.status = response.status;
      error.code = String(payload.code || payload.error_code || "server_request_failed");
      error.payload = payload;
      const refreshed = await refreshRejectedRequestSession(
        error,
        session,
        options._authRetryAttempted === true,
      );
      if (refreshed) {
        return invokeFunction(functionName, { ...options, _authRetryAttempted: true });
      }
      throw error;
    }

    return payload;
  }

  async function countRows(tableName, options = {}) {
    if (!readiness().ready) {
      throw new Error("Supabase publishable config is missing. Demo data is still active.");
    }

    const query = new URLSearchParams();
    query.set("select", options.select || "id");
    query.set("limit", "1");

    const session = await ensureSession();
    const response = await fetch(apiUrl(`${tableName}?${query.toString()}`), {
      method: "GET",
      headers: {
        ...authHeaders({}, session),
        Prefer: "count=exact",
      },
    });

    if (!response.ok) {
      const rawText = await response.text().catch(() => "");
      throw responseRequestError(response, rawText, "Supabase count failed");
    }

    const range = response.headers.get("content-range") || "";
    const match = range.match(/\/(\d+)$/);
    return match ? Number(match[1]) : 0;
  }

  function selectRows(tableName, options = {}) {
    const query = new URLSearchParams();
    query.set("select", options.select || "*");
    if (options.limit) query.set("limit", String(options.limit));
    if (options.offset) query.set("offset", String(options.offset));
    if (options.order) query.set("order", String(options.order));
    Object.entries(options.filters || {}).forEach(([key, value]) => {
      if (value && typeof value === "object" && !Array.isArray(value)) {
        Object.entries(value).forEach(([operator, operand]) => {
          if (!["eq", "neq", "gt", "gte", "lt", "lte", "in", "is"].includes(operator)) return;
          const encodedOperand = operator === "in" && Array.isArray(operand)
            ? `(${operand.join(",")})`
            : operand;
          query.append(key, `${operator}.${encodedOperand}`);
        });
        return;
      }
      query.set(key, `eq.${value}`);
    });
    return request(`${tableName}?${query.toString()}`, { prefer: "return=representation",
      requireFresh: options.requireFresh === true, requireCurrentSession: options.requireCurrentSession,
      retryAuth: options.retryAuth });
  }

  async function selectAllRows(tableName, options = {}) {
    const pageSize = Math.min(Math.max(Number(options.pageSize) || 500, 1), 1000);
    const maxRows = Math.max(Number(options.maxRows) || 10000, pageSize);
    const rows = [];
    for (let offset = 0; offset < maxRows; offset += pageSize) {
      const page = await selectRows(tableName, {
        ...options,
        limit: pageSize,
        offset,
      });
      rows.push(...(Array.isArray(page) ? page : []));
      if (!Array.isArray(page) || page.length < pageSize) break;
    }
    return rows;
  }

  function insertRows(tableName, rows) {
    return request(tableName, {
      method: "POST",
      body: Array.isArray(rows) ? rows : [rows],
      prefer: "return=representation",
    });
  }

  function updateRows(tableName, filters, values) {
    const query = new URLSearchParams();
    Object.entries(filters || {}).forEach(([key, value]) => {
      query.set(key, `eq.${value}`);
    });
    return request(`${tableName}?${query.toString()}`, {
      method: "PATCH",
      body: values,
      prefer: "return=representation",
    });
  }

  function providerKey(provider) {
    const value = `${provider || ""}`.trim().toLowerCase();
    if (value.includes("\uce74\uce74\uc624") || value.includes("kakao")) return "kakao";
    if (value.includes("\ub124\uc774\ubc84") || value.includes("naver")) return "naver";
    if (value.includes("\uc560\ud50c") || value.includes("apple")) return "apple";
    if (value.includes("\uc774\uba54\uc77c") || value.includes("email")) return "email";
    return value || "kakao";
  }

  function providerSlug(provider) {
    const key = providerKey(provider);
    const overrides = loadConfig().authProviderOverrides || {};
    if (key === "kakao") {
      return overrides[key] && overrides[key] !== "kakao" ? overrides[key] : "custom:kakao";
    }
    if (overrides[key]) return overrides[key];
    if (key === "naver") return "custom:naver";
    return overrides[key] || key;
  }

  async function signInWithOAuth(provider, options = {}) {
    if (!readiness().ready) {
      throw new Error("Supabase publishable config is missing. Demo login is still active.");
    }
    const key = providerKey(provider);
    const slug = providerSlug(provider);
    ensureNativePersistentAuthSession();
    const pkce = await createOAuthPkcePair(key);
    const redirectTo = options.redirectTo || (isNativeApp()
      ? nativeOAuthBridgeRedirect()
      : `${window.location.origin}${window.location.pathname}${window.location.search}`);
    saveProvider(provider || slug);
    const query = new URLSearchParams({
      provider: slug,
      redirect_to: redirectTo,
      code_challenge: pkce.challenge,
      code_challenge_method: "S256",
    });
    // Keep normal Naver sign-in on account reauthentication. When a previously
    // denied profile field is required, callers can explicitly request the
    // provider's separate permission reprompt flow.
    if (key === "naver") {
      query.set("auth_type", options.authType === "reprompt" ? "reprompt" : "reauthenticate");
    }
    const authorizeUrl = authUrl(`authorize?${query.toString()}`);
    const browserPlugin = window.Capacitor?.Plugins?.Browser;
    if (isNativeApp() && browserPlugin?.open) {
      clearNativeOAuthCancelTimer();
      nativeOAuthInFlightProvider = provider || slug;
      startNativeOAuthObservation(nativeOAuthInFlightProvider, authorizeUrl);
      try {
        await browserPlugin.open({
          url: authorizeUrl,
          presentationStyle: "popover",
        });
        recordNativeOAuthObservation("browser_opened", { provider: nativeOAuthInFlightProvider, url: authorizeUrl });
      } catch (error) {
        clearNativeOAuthLoadTimer();
        nativeOAuthInFlightProvider = "";
        clearOAuthStorageValue();
        emitClientError("oauth_browser_open", error, { provider });
        throw error;
      }
      return;
    }
    window.location.href = authorizeUrl;
  }

  async function signInWithPassword(email, password) {
    if (!readiness().ready) {
      throw new Error("Supabase publishable config is missing. Email login is unavailable.");
    }
    const normalizedEmail = `${email || ""}`.trim().toLowerCase();
    if (!normalizedEmail || !password) throw new Error("email_credentials_required");
    const config = loadConfig();
    const response = await fetch(authUrl("token?grant_type=password"), {
      method: "POST",
      headers: {
        apikey: config.supabasePublishableKey,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ email: normalizedEmail, password }),
    });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok) {
      const error = new Error(payload?.msg || payload?.message || payload?.error_description || "email_login_failed");
      error.code = payload?.error_code || payload?.code || "email_login_failed";
      error.status = response.status;
      emitClientError("password_login", error, { provider: "email" });
      throw error;
    }
    return saveSession({ ...payload, provider: "\uc774\uba54\uc77c" });
  }

  async function signUpWithPassword(email, password, options = {}) {
    if (!readiness().ready) throw new Error("Supabase publishable config is missing. Email signup is unavailable.");
    const normalizedEmail = `${email || ""}`.trim().toLowerCase();
    if (!normalizedEmail || !password) throw new Error("email_credentials_required");
    const config = loadConfig();
    const redirectTo = emailAuthRedirect(options);
    const query = new URLSearchParams({ redirect_to: redirectTo });
    saveProvider("이메일");
    const response = await fetch(authUrl(`signup?${query.toString()}`), {
      method: "POST",
      headers: { apikey: config.supabasePublishableKey, "Content-Type": "application/json" },
      body: JSON.stringify({ email: normalizedEmail, password }),
    });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok) {
      const error = new Error(payload?.msg || payload?.message || "email_signup_failed");
      error.code = payload?.error_code || payload?.code || "email_signup_failed";
      error.status = response.status;
      emitClientError("password_signup", error, { provider: "email" });
      throw error;
    }
    if (payload?.access_token) saveSession({ ...payload, provider: "이메일" });
    return payload;
  }

  async function sendPasswordResetEmail(email, options = {}) {
    if (!readiness().ready) throw new Error("Supabase publishable config is missing. Password reset is unavailable.");
    const normalizedEmail = `${email || ""}`.trim().toLowerCase();
    if (!normalizedEmail) throw new Error("email_required");
    const config = loadConfig();
    const redirectTo = emailAuthRedirect(options);
    const query = new URLSearchParams({ redirect_to: redirectTo });
    saveProvider("이메일");
    const response = await fetch(authUrl(`recover?${query.toString()}`), {
      method: "POST",
      headers: { apikey: config.supabasePublishableKey, "Content-Type": "application/json" },
      body: JSON.stringify({ email: normalizedEmail }),
    });
    if (!response.ok) throw new Error("password_reset_failed");
    return true;
  }

  async function updatePassword(password) {
    if (!readiness().ready) throw new Error("Supabase publishable config is missing. Password update is unavailable.");
    if (!password) throw new Error("password_required");
    const config = loadConfig();
    const session = await ensureSession();
    if (!session?.access_token) throw new Error("password_recovery_session_required");
    const response = await fetch(authUrl("user"), {
      method: "PUT",
      headers: {
        apikey: config.supabasePublishableKey,
        Authorization: `Bearer ${session.access_token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ password }),
    });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok) {
      const error = new Error(payload?.msg || payload?.message || "password_update_failed");
      error.code = payload?.error_code || payload?.code || "password_update_failed";
      error.status = response.status;
      emitClientError("password_update", error, { provider: "email" });
      throw error;
    }
    return payload;
  }

  async function getAuthUser(options = {}) {
    const session = await ensureSession();
    if (!session?.access_token) return null;
    if (!isOnline()) {
      const id = sessionSubject(session);
      return id ? { id } : null;
    }
    let response;
    try {
      response = await fetch(authUrl("user"), {
        method: "GET",
        headers: authHeaders({}, session),
      });
    } catch (error) {
      if (!transientNetworkError(error)) throw error;
      const id = sessionSubject(session);
      return id ? { id } : null;
    }
    if (!response.ok) {
      const rawText = await response.text().catch(() => "");
      const requestError = responseRequestError(response, rawText, "Supabase auth user failed");
      if (response.status === 401) {
        try {
          const refreshed = await refreshRejectedRequestSession(
            requestError,
            session,
            options._authRetryAttempted === true,
          );
          if (refreshed) return getAuthUser({ ...options, _authRetryAttempted: true });
        } catch (error) {
          if (error?.code === "admin_session_expired") return null;
          throw error;
        }
      }
      if (response.status === 400) {
        removeStoredSession();
        return null;
      }
      throw requestError;
    }
    return response.json();
  }

  async function getAuthSettings() {
    if (!readiness().ready) {
      throw new Error("Supabase publishable config is missing. Auth settings cannot be checked.");
    }
    const response = await fetch(authUrl("settings"), {
      method: "GET",
      headers: authHeaders(),
    });
    if (!response.ok) {
      const rawText = await response.text().catch(() => "");
      throw responseRequestError(response, rawText, "Supabase auth settings failed");
    }
    return response.json();
  }

  async function requestPhoneChangeVerification(phone) {
    if (!readiness().ready) throw new Error("Supabase publishable config is missing. Phone verification is unavailable.");
    const normalizedPhone = `${phone || ""}`.trim();
    if (!/^\+[1-9][0-9]{7,14}$/u.test(normalizedPhone)) throw new Error("phone_invalid");
    const session = await ensureSession();
    if (!session?.access_token) throw new Error("login_required");
    const response = await fetch(authUrl("user"), {
      method: "PUT",
      headers: authHeaders({}, session),
      body: JSON.stringify({ phone: normalizedPhone }),
    });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok) {
      const error = new Error(payload?.msg || payload?.message || payload?.error_description || "phone_verification_request_failed");
      error.code = payload?.error_code || payload?.code || "phone_verification_request_failed";
      error.status = response.status;
      emitClientError("phone_verification_request", error);
      throw error;
    }
    return payload;
  }

  async function verifyPhoneChange(phone, token) {
    if (!readiness().ready) throw new Error("Supabase publishable config is missing. Phone verification is unavailable.");
    const normalizedPhone = `${phone || ""}`.trim();
    const normalizedToken = `${token || ""}`.replace(/\D/gu, "");
    if (!/^\+[1-9][0-9]{7,14}$/u.test(normalizedPhone)) throw new Error("phone_invalid");
    if (!/^[0-9]{6}$/u.test(normalizedToken)) throw new Error("phone_otp_invalid");
    const session = await ensureSession();
    if (!session?.access_token) throw new Error("login_required");
    const response = await fetch(authUrl("verify"), {
      method: "POST",
      headers: authHeaders({}, session),
      body: JSON.stringify({ type: "phone_change", phone: normalizedPhone, token: normalizedToken }),
    });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok) {
      const error = new Error(payload?.msg || payload?.message || payload?.error_description || "phone_otp_verification_failed");
      error.code = payload?.error_code || payload?.code || "phone_otp_verification_failed";
      error.status = response.status;
      emitClientError("phone_verification_confirm", error);
      throw error;
    }
    const provider = session.provider || storedProvider() || "Supabase";
    if (payload?.access_token) saveSession({ ...payload, provider });
    return payload;
  }

  async function bootstrapCurrentProfile(options = {}) {
    const session = getSession();
    if (!session?.access_token) return null;
    return invokeFunction("tennisnote-profile-bootstrap", {
      body: {
        providerHint: providerSlug(session.provider || options.providerHint || ""),
      },
    });
  }

  function deleteRows(tableName, filters) {
    const query = new URLSearchParams();
    Object.entries(filters || {}).forEach(([key, value]) => {
      query.set(key, `eq.${value}`);
    });
    return request(`${tableName}?${query.toString()}`, {
      method: "DELETE",
      prefer: "return=representation",
    });
  }

  function rpc(functionName, parameters = {}, options = {}) {
    return request(`rpc/${functionName}`, {
      method: "POST",
      body: parameters,
      prefer: "return=representation",
      timeoutMs: options.timeoutMs,
      requireCurrentSession: options.requireCurrentSession,
      retryAuth: options.retryAuth,
    });
  }

  async function uploadObject(bucketName, objectPath, file, options = {}) {
    if (!isOnline()) throw offlineError();
    if (options.resumable === true || Number(file?.size || 0) > resumableUploadThresholdBytes) {
      return uploadObjectResumable(bucketName, objectPath, file, options);
    }
    const session = await ensureSession();
    if (!readiness().ready || !session?.access_token) throw new Error("Login is required for private upload.");
    const response = await fetch(storageObjectUrl(bucketName, objectPath), {
      method: "POST",
      headers: authHeaders({
        "Content-Type": file?.type || "application/octet-stream",
        "x-upsert": "false",
      }, session),
      body: file,
    });
    if (!response.ok) throw new Error(await response.text() || `Storage upload failed: ${response.status}`);
    return response.json().catch(() => ({ path: objectPath }));
  }

  async function createSignedObjectUrl(bucketName, objectPath, expiresIn = 21600) {
    if (!isOnline()) throw offlineError();
    const session = await ensureSession();
    if (!readiness().ready || !session?.access_token) throw new Error("Login is required for private streaming.");
    const config = loadConfig();
    const encodedPath = `${objectPath || ""}`.split("/").map(encodeURIComponent).join("/");
    const response = await fetch(`${config.supabaseUrl.replace(/\/$/, "")}/storage/v1/object/sign/${encodeURIComponent(bucketName)}/${encodedPath}`, {
      method: "POST",
      headers: authHeaders({}, session),
      body: JSON.stringify({ expiresIn: Math.max(60, Math.min(Number(expiresIn) || 21600, 86400)) }),
    });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(payload?.message || `Storage signing failed: ${response.status}`);
    const signedPath = payload.signedURL || payload.signedUrl || "";
    if (!signedPath) throw new Error("Storage signed URL missing.");
    if (/^https?:\/\//i.test(signedPath)) return signedPath;
    const base = config.supabaseUrl.replace(/\/$/, "");
    if (signedPath.startsWith("/storage/v1/")) return `${base}${signedPath}`;
    return `${base}/storage/v1/${signedPath.replace(/^\//, "")}`;
  }

  async function downloadObject(bucketName, objectPath) {
    if (!isOnline()) throw offlineError();
    const session = await ensureSession();
    if (!readiness().ready || !session?.access_token) throw new Error("Login is required for private download.");
    const response = await fetch(storageObjectUrl(bucketName, objectPath), {
      method: "GET",
      headers: authHeaders({ "Content-Type": "application/octet-stream" }, session),
    });
    if (!response.ok) throw new Error(await response.text() || `Storage download failed: ${response.status}`);
    return response.blob();
  }

  async function deleteObject(bucketName, objectPath) {
    if (!isOnline()) throw offlineError();
    const session = await ensureSession();
    if (!readiness().ready || !session?.access_token) throw new Error("Login is required for private deletion.");
    const headers = authHeaders({}, session);
    // 본문 없는 DELETE에 JSON 헤더를 보내면 Storage가 빈 JSON 오류로 거부한다.
    delete headers["Content-Type"];
    const response = await fetch(storageObjectUrl(bucketName, objectPath), {
      method: "DELETE",
      headers,
    });
    if (!response.ok) throw new Error(await response.text() || `Storage deletion failed: ${response.status}`);
    return true;
  }

  async function performSelectCurrentProfile() {
    await flushOAuthProviderCredentialCapture();
    const session = getSession();
    const user = await getAuthUser();
    if (!user?.id) return { user, profile: null };
    const profileSelect = "id,name,nickname,phone,birth_year,neighborhood,gender,role,member_kind,profile_photo_url,dominant_hand,backhand_style,tennis_started_on,self_ntrp,coach_ntrp,tennis_goal,play_style_memo,ntrp_survey,ntrp_requested_at,profile_completed_at,privacy_consent_version,privacy_consented_at,status,updated_at";
    let identityContext = null;
    const identityFailure = (code, status) => {
      emitClientError("profile_mapping", Object.assign(new Error(code), { code, status }));
      return {
        user,
        profile: null,
        coachRole: null,
        identityContext,
        profileBootstrapError: {
          code,
          expectedProvider: "",
          status,
        },
      };
    };
    try {
      identityContext = await rpc("tn_current_identity_context", {});
    } catch (error) {
      const text = `${error?.payload?.message || ""} ${error?.message || ""}`;
      if (!/tn_current_identity_context|PGRST202|42883|schema cache/i.test(text)) throw error;
    }

    if (identityContext?.status === "ambiguous") {
      return identityFailure("auth_profile_mapping_ambiguous", 409);
    }
    if (identityContext && !["ok", "unlinked"].includes(identityContext.status)) {
      return identityFailure("auth_profile_identity_context_invalid", 503);
    }

    const resolvedProfileId = identityContext?.status === "ok"
      ? String(identityContext.actorUserId || "")
      : "";
    let rows = [];
    if (resolvedProfileId) {
      rows = await selectRows("tn_users", {
        select: profileSelect,
        filters: { id: resolvedProfileId },
        limit: 1,
      });
      if (!rows?.length) return identityFailure("auth_profile_mapping_stale", 409);
    } else if (!identityContext) {
      rows = await selectRows("tn_users", {
        select: profileSelect,
        filters: { auth_user_id: user.id },
        order: "id.asc",
        limit: 2,
      });
      if (rows.length > 1) return identityFailure("auth_profile_mapping_ambiguous", 409);
    }

    if (!rows?.length && !identityContext) {
      try {
        const links = await selectRows("tn_user_auth_links", {
          select: "id,user_id,is_primary,linked_at",
          filters: { auth_user_id: user.id },
          order: "is_primary.desc,linked_at.asc,id.asc",
          limit: 2,
        });
        const linkedProfileIds = [...new Set((links || []).map((link) => String(link.user_id || "")).filter(Boolean))];
        if (linkedProfileIds.length > 1) return identityFailure("auth_profile_mapping_ambiguous", 409);
        if (links?.[0]?.user_id) {
          rows = await selectRows("tn_users", {
            select: profileSelect,
            filters: { id: links[0].user_id },
            limit: 1,
          });
        }
      } catch (error) {
        rows = [];
      }
    }

    let profileBootstrapError = null;
    const needsProfileReconciliation = !rows?.length
      || (rows?.[0]?.role === "member" && rows?.[0]?.member_kind === "journal_only");
    if (needsProfileReconciliation && session?.access_token) {
      try {
        const result = await bootstrapCurrentProfile({ providerHint: session.provider });
        if (result?.profile?.id) {
          // Older bootstrap responses omit the optimistic revision. Read the
          // exact mapped self row instead of inventing a timestamp or borrowing
          // another profile's revision after an identity reconciliation.
          rows = result.profile.updated_at ? [result.profile] : await selectRows("tn_users", {
            select: profileSelect, filters: { id: result.profile.id }, limit: 2,
          });
          if (rows.length !== 1 || rows[0].id !== result.profile.id || !rows[0].updated_at) {
            return identityFailure("profile_revision_unconfirmed", 409);
          }
        }
      } catch (error) {
        emitClientError("profile_bootstrap", error);
        profileBootstrapError = {
          code: error?.payload?.code || error?.message || "profile_bootstrap_failed",
          expectedProvider: error?.payload?.expectedProvider || "",
          status: Number(error?.status || 0),
        };
        if (!rows?.length) rows = [];
      }
    }

    const profile = rows?.[0] || null;
    let coachRole = null;
    if (profile?.id) {
      try {
        const coachRows = await selectRows("tn_coach_roles", {
          select: "id,user_id,branch_id,display_name,status,employment_status,archived_at,deleted_at",
          filters: { user_id: profile.id, status: "approved" },
          limit: 1,
        });
        const candidate = coachRows?.[0] || null;
        coachRole = candidate
          && (candidate.employment_status || "active") === "active"
          && !candidate.archived_at
          && !candidate.deleted_at
          ? candidate
          : null;
      } catch (error) {
        coachRole = null;
      }
    }

    return { user, profile, coachRole, profileBootstrapError, identityContext };
  }

  function selectCurrentProfile() {
    if (!currentProfilePromise) {
      currentProfilePromise = performSelectCurrentProfile().finally(() => {
        currentProfilePromise = null;
      });
    }
    return currentProfilePromise;
  }

  async function signOut() {
    // Consumers clear protected DOM/player copies before the potentially slow remote logout.
    window.dispatchEvent(new Event("tennisnote:auth-session-cleared"));
    const session = getSession();
    const identity = sessionSubject(session);
    if (session?.access_token && readiness().ready) {
      try {
        await fetch(authUrl("logout"), {
          method: "POST",
          headers: authHeaders(),
        });
      } catch (error) {
        // Local session cleanup below is still the important browser-side step.
      }
    }
    removeStoredSession();
    authSessionStores().forEach((storage) => {
      try {
        storage.removeItem(`${authStorageKey}-provider`);
      } catch (error) {
        // Keep clearing the other storage area.
      }
    });
    if (identity) await clearOfflineResponses(identity);
  }

  recordAuthSessionStartup();

  window.TennisNoteDataClient = {
    storageKey,
    authStorageKey,
    authPersistenceKey,
    loadConfig,
    readiness,
    getSession,
    sessionPersistence,
    setSessionPersistence,
    refreshSession,
    ensureSession,
    consumeOAuthRedirect,
    flushOAuthProviderCredentialCapture,
    getNativeOAuthObservations: () => nativeOAuthObservations.map((item) => ({ ...item })),
    signInWithOAuth,
    signInWithPassword,
    sendPasswordResetEmail,
    signUpWithPassword,
    updatePassword,
    requestPhoneChangeVerification,
    verifyPhoneChange,
    providerSlug,
    getAuthUser,
    getAuthSettings,
    bootstrapCurrentProfile,
    selectCurrentProfile,
    signOut,
    isOnline,
    isOfflineError,
    isTransientConnectionError,
    clearOfflineResponses,
    countRows,
    selectRows,
    selectAllRows,
    insertRows,
    updateRows,
    deleteRows,
    rpc,
    uploadObject,
    createSignedObjectUrl,
    downloadObject,
    deleteObject,
    invokeFunction,
  };
  installNativeOAuthListener();
})();

