// 로그인·로그아웃과 신원 정보를 서버와 주고받는 함수들.
//
// 서버(Supabase)에 붙는다. 권한은 여기가 아니라 RLS 정책이 책임진다.
// app.js 에서 본문 그대로 옮겨왔고 전역 함수 선언이라 호출부는 예전과 같다.

function installOAuthReturnStatusReset() {
  const reset = () => {
    window.setTimeout(() => {
      const status = $("#memberEmailLoginStatus");
      if (
        document.hidden
        || !status?.textContent.includes("로그인 화면을 여는 중")
        || !$("#appScreen")?.hidden
        || window.location.hash.includes("access_token=")
        || window.TennisNoteDataClient?.getSession?.()?.access_token
      ) return;
      const provider = oauthLoginInFlightProvider || "간편";
      finishOAuthLogin();
      setEmailAuthStatus(`${provider} 로그인이 취소되었습니다. 다시 로그인 수단을 선택해 주세요.`);
    }, 500);
  };
  window.addEventListener("pageshow", reset);
  window.addEventListener("focus", reset);
  document.addEventListener("visibilitychange", () => {
    if (!document.hidden) reset();
  });
}

function hasLiveMemberSession() {
  const client = window.TennisNoteDataClient;
  return Boolean(client?.readiness?.().ready && client.getSession?.()?.access_token);
}

function markTicketSyncLoginNeeded() {
  const client = window.TennisNoteDataClient;
  if (client?.readiness?.().ready) {
    if (hasLiveMemberSession()) {
      state.ticketSyncStatus = {
        tone: "alert",
        text: "서버 회원 연결 확인 필요 · 관리자 승인/회원권 확인",
      };
      return;
    }
    state.ticketSyncStatus = {
      tone: "wait",
      text: "서버 로그인 필요 · 간편 로그인 후 실제 회원권 확인",
    };
    return;
  }
  state.ticketSyncStatus = { tone: "alert", text: "실사용 데이터 연결 설정이 필요합니다" };
}

async function checkNicknameAvailability(inputId, statusId) {
  const nickname = normalizeIdentityText($(`#${inputId}`)?.value || "");
  if (nickname.length < 2 || nickname.length > 20) {
    setNicknameStatus(statusId, "닉네임은 2~20자로 입력해 주세요.", "unavailable");
    return false;
  }
  const client = window.TennisNoteDataClient;
  if (!hasLiveMemberSession() || !client?.rpc) {
    setNicknameStatus(statusId, "실사용 로그인 후 중복을 확인할 수 있습니다.", "unavailable");
    return false;
  }
  setNicknameStatus(statusId, "중복 여부를 확인하고 있습니다.");
  try {
    const rawResult = await client.rpc("tn_check_nickname_available", { target_nickname: nickname });
    const result = Array.isArray(rawResult) ? rawResult[0] : rawResult;
    if (result?.available) {
      setNicknameStatus(statusId, "사용할 수 있는 닉네임입니다.", "available");
      return true;
    }
    setNicknameStatus(statusId, identityErrorMessage(result?.reason || "nickname_already_taken"), "unavailable");
    return false;
  } catch (error) {
    setNicknameStatus(statusId, identityErrorMessage(error), "unavailable");
    return false;
  }
}

async function loadIdentityConsentPreferences() {
  const client = window.TennisNoteDataClient;
  if (!hasLiveMemberSession() || !client?.rpc) return {};
  const rawResult = await retryTransientNetwork(() => client.rpc("tn_my_consent_preferences"));
  const result = Array.isArray(rawResult) ? rawResult[0] : rawResult;
  applyConsentPreferences(result || {});
  return result || {};
}

async function persistConsentPreferences({ marketingPush, marketingSms, marketingEmail }) {
  const client = window.TennisNoteDataClient;
  if (!hasLiveMemberSession() || !client?.rpc) {
    applyConsentPreferences({
      termsVersion: identityTermsVersion,
      termsConsentedAt: new Date().toISOString(),
      privacyVersion: identityPrivacyVersion,
      privacyConsentedAt: new Date().toISOString(),
      marketingPush,
      marketingSms,
      marketingEmail,
    });
    return { ok: true, offlinePreview: true };
  }
  const rawResult = await retryTransientNetwork(() => client.rpc("tn_save_my_consent_preferences", {
    target_terms_version: identityTermsVersion,
    target_privacy_version: identityPrivacyVersion,
    target_terms_consent: true,
    target_privacy_consent: true,
    target_marketing_push: marketingPush === true,
    target_marketing_sms: marketingSms === true,
    target_marketing_email: marketingEmail === true,
  }));
  const result = Array.isArray(rawResult) ? rawResult[0] : rawResult;
  if (!result?.ok) throw new Error("consent_update_not_confirmed");
  applyConsentPreferences(result);
  return result;
}

async function refreshIdentityPhoneVerification(surface = "signup") {
  if (!signupSmsEnabled) return "";
  const client = window.TennisNoteDataClient;
  if (!hasLiveMemberSession() || !client?.getAuthUser) return "";
  const owner = phoneVerificationOwner();
  const inputPhone = normalizeIdentityPhone(phoneVerificationControls(surface).input?.value || "");
  const user = await client.getAuthUser();
  if (!phoneVerificationOwnerCurrent(owner) || (owner.authId && user?.id && user.id !== owner.authId)) return "";
  const verifiedPhone = verifiedPhoneFromAuthUser(user || {}, surface === "profile");
  if (verifiedPhone && ((!inputPhone && surface === "signup") || inputPhone === verifiedPhone)
    && normalizeIdentityPhone(phoneVerificationControls(surface).input?.value || "") === inputPhone) {
    markIdentityPhoneVerified(verifiedPhone, "provider", surface);
  }
  return verifiedPhone;
}

async function requireVerifiedIdentityPhone(phone, surface = "signup") {
  const normalizedPhone = normalizeIdentityPhone(phone);
  const verification = phoneVerificationState(surface);
  if (verification.status === "verified" && verification.phone === normalizedPhone && phoneVerificationOwnerCurrent(verification.owner)) return true;
  const verifiedPhone = await refreshIdentityPhoneVerification(surface);
  if (verifiedPhone === normalizedPhone) return true;
  throw new Error("phone_verification_required");
}

// 메모리에서만 재시도 키를 유지한다. 개인정보를 별도 저장소에 기록하지 않는다.
let signupProfileOperation = { fingerprint: "", key: "" };

async function persistIdentityProfile({ realName, nickname, phone, birthYear, neighborhood, gender, profileEditor = false, profileStyle = null }) {
  const normalizedRealName = normalizeIdentityText(realName);
  const normalizedNickname = normalizeIdentityText(nickname);
  const normalizedPhone = normalizeIdentityPhone(phone);
  const normalizedBirthYear = Number(birthYear) || 0;
  const normalizedNeighborhood = normalizeIdentityText(neighborhood);
  const normalizedGender = String(gender || "");
  if (!normalizedRealName || normalizedRealName.length > 40) throw new Error("real_name_invalid");
  if (normalizedNickname.length < 2 || normalizedNickname.length > 20) throw new Error("nickname_invalid");
  if (!/^01[0-9]{8,9}$/u.test(normalizedPhone) && !(profileEditor && normalizedPhone === profilePhoneExpectedPhone)) throw new Error("phone_invalid");
  if (!profileEditor && (normalizedBirthYear < 1900 || normalizedBirthYear > new Date().getFullYear())) throw new Error("birth_year_invalid");
  if (!profileEditor && !["female", "male", "other", "prefer_not"].includes(normalizedGender)) throw new Error("gender_invalid");
  const client = window.TennisNoteDataClient;
  if (profileEditor && (!hasLiveMemberSession() || !client?.rpc)) throw new Error("login_required");
  if (hasLiveMemberSession() && client?.rpc) {
    if (profileEditor) {
      const owner = profilePhoneEditorOwner;
      if (!owner?.profileId || !owner.authId || !phoneVerificationRequestCurrent(owner, normalizedPhone, "profile")) throw new Error("profile_phone_context_changed");
      if (normalizedPhone !== profilePhoneExpectedPhone) await requireVerifiedIdentityPhone(normalizedPhone, "profile");
      if (!phoneVerificationRequestCurrent(owner, normalizedPhone, "profile")) throw new Error("profile_phone_context_changed");
      const targetProfile = { name: normalizedRealName, nickname: normalizedNickname, phone: normalizedPhone };
      if (profileStyle !== null) {
        const saved = await updateMemberProfileOnServer(profileStyle, targetProfile);
        if (!saved.ok) throw saved.error;
        if (saved.phoneVerified === true) markIdentityPhoneVerified(normalizedPhone, "server", "profile");
        return saved;
      }
      const fingerprint = JSON.stringify([owner.authId, owner.profileId, profilePhoneExpectedPhone, targetProfile]);
      if (profilePhoneSaveOperation.fingerprint !== fingerprint) profilePhoneSaveOperation = { fingerprint, key: crypto.randomUUID() };
      const resultRaw = await client.rpc("tn_save_my_verified_profile_phone", {
        target_profile_id: owner.profileId, target_profile: targetProfile,
        target_expected_phone: profilePhoneExpectedPhone, target_operation_key: profilePhoneSaveOperation.key,
      });
      if (!phoneVerificationOwnerCurrent(owner)) throw new Error("profile_phone_context_changed");
      const result = Array.isArray(resultRaw) ? resultRaw[0] : resultRaw;
      if (!result?.ok || result.profile?.id !== owner.profileId
        || normalizeIdentityPhone(result.profile?.phone || "") !== normalizedPhone
        || (normalizedPhone !== profilePhoneExpectedPhone && result.phoneVerified !== true)) {
        throw new Error("profile_phone_readback_unconfirmed");
      }
      applySavedIdentity(result.profile, { preserveCompletion: true });
      if (result.phoneVerified === true) markIdentityPhoneVerified(normalizedPhone, "server", "profile");
      else setIdentityPhoneStatus("저장된 번호를 그대로 유지했습니다. 새 번호로 바꾸려면 인증해 주세요.", "", "profile");
      return result;
    }
    await requireVerifiedIdentityPhone(normalizedPhone);
    const targetProfile = {
      name: normalizedRealName, nickname: normalizedNickname, phoneCandidate: normalizedPhone,
      birthYear: normalizedBirthYear, neighborhood: normalizedNeighborhood,
      gender: normalizedGender, privacyVersion: identityPrivacyVersion,
    };
    // Memory-only draft/key: a lost response retries the same operation. Raw
    // contact is never written to console, URL, analytics or a new storage key.
    const fingerprint = JSON.stringify(targetProfile);
    if (signupProfileOperation.fingerprint !== fingerprint) {
      signupProfileOperation = { fingerprint, key: crypto.randomUUID() };
    }
    const signupAuthUserId = String(state.member?.authUserId || "");
    const rawResult = await retryTransientNetwork(() => client.rpc("tn_save_my_signup_profile", {
      target_profile: targetProfile,
      target_operation_key: signupProfileOperation.key,
    }));
    const result = Array.isArray(rawResult) ? rawResult[0] : rawResult;
    if (!result?.ok || !result?.profile) throw new Error("identity_profile_update_not_confirmed");
    if (result.linkStatus === "linked") {
      const restored = await applySupabaseMemberSession(false, {
        expectedProfileId: result.profile.id,
        expectedAuthUserId: signupAuthUserId,
        requireSignupReadback: true,
      });
      if (!restored) throw new Error("signup_link_readback_unconfirmed");
    } else applySavedIdentity(result.profile);
    return result;
  }

  const profile = {
    name: normalizedRealName,
    nickname: normalizedNickname,
    phone: normalizedPhone,
    birth_year: normalizedBirthYear,
    neighborhood: normalizedNeighborhood,
    gender: normalizedGender,
    profile_completed_at: new Date().toISOString(),
    privacy_consent_version: identityPrivacyVersion,
    privacy_consented_at: new Date().toISOString(),
  };
  applySavedIdentity(profile);
  return { ok: true, profile, linkStatus: "offline_preview" };
}

