:root {
  --ink: #182230;
  --muted: #667085;
  --line: #d0d5dd;
  --paper: #ffffff;
  --wash: #eef4f1;
  --green: #157a5b;
  --blue: #2456a6;
  --yellow: #fee500;
  --naver: #03c75a;
  --amber: #b54708;
  --soft-green: #e7f6ef;
  --soft-blue: #edf4ff;
  --soft-amber: #fff4df;
  --booking-bg: #f7fafc;
  --booking-panel: #fbfcfe;
  --booking-shadow: 0 10px 24px rgba(24, 34, 48, 0.08);
}

.member-refund-request-form {
  display: grid;
  gap: 14px;
  padding-bottom: calc(92px + env(safe-area-inset-bottom));
}

.member-refund-request-form > label:not(.member-refund-fallback) {
  display: grid;
  gap: 7px;
  font-weight: 700;
}

.member-refund-request-form textarea {
  width: 100%;
  min-height: 92px;
  box-sizing: border-box;
  resize: vertical;
  font-size: max(16px, 1rem);
}

.member-refund-preview,
.member-refund-status-card,
.member-refund-loading {
  display: grid;
  gap: 10px;
  margin: 0;
  padding: 14px;
  border: 1px solid var(--line, #dbe6e0);
  border-radius: 14px;
  background: var(--surface, #fff);
  overflow-wrap: anywhere;
}

.member-refund-preview > div,
.member-refund-status-card {
  align-items: start;
}

.member-refund-preview > div {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}

.member-refund-preview dl,
.member-refund-preview dl > div {
  display: grid;
  gap: 6px;
  margin: 0;
}

.member-refund-preview dl > div {
  grid-template-columns: minmax(0, 1fr) auto;
}

.member-refund-preview dt,
.member-refund-preview dd,
.member-refund-preview p,
.member-refund-status-card p,
.member-refund-status-card small {
  margin: 0;
}

.member-refund-fallback {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  font-size: 14px;
  line-height: 1.5;
}

.member-refund-policy-link {
  color: var(--accent, #117a55);
  font-weight: 700;
}

.member-refund-request-sheet .sheet-actions {
  grid-template-columns: minmax(88px, auto) minmax(0, 1fr);
}

.member-refund-request-sheet .sheet-actions button {
  min-height: 44px;
}

.member-refund-status-card .is-danger,
.member-refund-loading.is-danger {
  color: var(--danger, #b42318);
}

@media (max-height: 520px) and (orientation: landscape) {
  .member-refund-request-form {
    padding-bottom: calc(76px + env(safe-area-inset-bottom));
  }
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
  min-height: 100vh;
  background: #e8efed;
  color: var(--ink);
  font-size: 16px;
  line-height: 1.45;
  font-family:
    Inter, Pretendard, "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont,
    sans-serif;
}

.brand-splash {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  overflow: hidden;
  background: #ffffff;
  opacity: 1;
  transition: opacity 220ms ease, visibility 220ms ease;
}

.brand-splash.is-hidden {
  visibility: hidden;
  pointer-events: none;
  opacity: 0;
}

.brand-splash[hidden] {
  display: none !important;
}

.brand-splash img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.brand-splash span {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
}

.brand-splash-fallback {
  position: absolute;
  left: 50%;
  bottom: max(28px, env(safe-area-inset-bottom));
  width: min(420px, calc(100% - 32px));
  padding: 18px;
  border: 1px solid #cbdad5;
  border-radius: 8px;
  background: rgb(255 255 255 / 96%);
  box-shadow: 0 8px 24px rgb(18 49 45 / 14%);
  text-align: center;
}

.brand-splash-fallback p {
  margin: 6px 0 14px;
  color: #516763;
}

.brand-splash-fallback button {
  min-height: 44px;
  padding: 0 18px;
  border: 0;
  border-radius: 6px;
  background: #0f766e;
  color: #ffffff;
  font-weight: 800;
}

.brand-splash.is-failed img {
  opacity: 0.18;
}

button,
a,
select {
  font: inherit;
}

button {
  cursor: pointer;
}

.app-shell {
  position: relative;
  width: min(980px, 100%);
  min-height: 100vh;
  margin: 0 auto;
  overflow-x: hidden;
  background: var(--wash);
}

.login-screen[hidden],
.app-screen[hidden] {
  display: none !important;
}

.login-screen {
  min-height: 100vh;
  display: grid;
  align-content: center;
  gap: 18px;
  padding: 28px;
}

.brand p,
.topbar p {
  margin: 0 0 6px;
  color: var(--green);
  font-size: 13px;
  font-weight: 900;
}

.brand h1,
.topbar h1,
.section-title h2 {
  margin: 0;
}

.brand h1 {
  font-size: 32px;
}

.login-brand-guidance {
  display: block;
  margin-top: 8px;
  color: var(--muted);
  font-size: 14px;
  font-weight: 700;
  line-height: 1.5;
}

.brand span,
.section-title span,
.login-card p,
.summary-grid small,
.cell small,
.cell span,
.request-card span {
  color: var(--muted);
}

.login-card,
.summary-grid article,
.form-card,
.request-card,
.history-card {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--paper);
  box-shadow: 0 8px 18px rgba(24, 34, 48, 0.05);
}

.login-card {
  display: grid;
  gap: 12px;
  padding: 20px;
}

.session-restoring {
  min-height: 210px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 10px;
  text-align: center;
}

.session-restoring[hidden] { display: none !important; }
.session-restoring small { color: var(--muted); }
.session-restoring-spinner {
  width: 30px;
  height: 30px;
  border: 3px solid #d8e7e2;
  border-top-color: var(--primary);
  border-radius: 50%;
  animation: session-restoring-spin 0.8s linear infinite;
}
.member-session-restoring .login-card > :not(.session-restoring) { display: none !important; }
@keyframes session-restoring-spin { to { transform: rotate(360deg); } }

.login-card h2 {
  margin: 0 0 4px;
}

.onboarding-entry-intro {
  display: grid;
  gap: 5px;
  border: 1px solid rgba(15, 132, 91, 0.26);
  border-radius: 10px;
  padding: 13px 14px;
  background: linear-gradient(115deg, #ecfdf5, #ffffff 76%);
}

.onboarding-entry-intro[hidden] {
  display: none !important;
}

.onboarding-entry-intro span {
  color: var(--green);
  font-size: 12px;
  font-weight: 900;
}

.onboarding-entry-intro strong {
  color: var(--ink);
  font-size: 17px;
  line-height: 1.35;
}

.onboarding-entry-intro small {
  color: var(--muted);
  font-size: 12px;
  font-weight: 750;
  line-height: 1.45;
}

.public-product-preview {
  display: grid;
  gap: 12px;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  padding: 14px 0;
}

.public-product-preview-heading {
  display: grid;
  gap: 5px;
}

.public-product-preview-heading > div {
  display: grid;
  gap: 3px;
}

.public-product-preview-heading span {
  color: var(--green);
  font-size: 12px;
  font-weight: 900;
}

.public-product-preview-heading strong {
  color: var(--ink);
  font-size: 17px;
  line-height: 1.35;
}

.public-product-preview-heading small,
.public-product-preview-note {
  color: var(--muted);
  font-size: 12px;
  font-weight: 750;
  line-height: 1.45;
}

.public-onboarding-existing-login {
  justify-self: center;
  border: 0;
  padding: 4px 6px;
  color: var(--muted);
  background: transparent;
  font: inherit;
  font-size: 13px;
  font-weight: 800;
  line-height: 1.45;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.public-onboarding-existing-login strong {
  color: var(--green);
}

.public-onboarding-existing-login[hidden] {
  display: none !important;
}

.public-product-preview-list {
  display: grid;
  gap: 10px;
}

.public-onboarding-choice-grid,
.public-onboarding-coach-grid,
.public-onboarding-frequency-grid,
.public-onboarding-slot-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.public-onboarding-choice-grid > button,
.public-onboarding-coach-grid > button,
.public-onboarding-frequency-grid > button,
.public-onboarding-slot-grid > button {
  display: grid;
  gap: 4px;
  min-width: 0;
  min-height: 76px;
  align-content: center;
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 12px;
  color: var(--ink);
  background: white;
  font: inherit;
  text-align: left;
}

.public-onboarding-choice-grid > button:hover,
.public-onboarding-coach-grid > button:hover,
.public-onboarding-frequency-grid > button:hover,
.public-onboarding-slot-grid > button:hover,
.public-onboarding-slot-grid > button.is-selected {
  border-color: var(--green);
  background: var(--mint);
}

.public-onboarding-choice-grid span,
.public-onboarding-summary span,
.public-onboarding-selection-count {
  color: var(--green);
  font-size: 12px;
  font-weight: 900;
}

.public-onboarding-choice-grid strong,
.public-onboarding-coach-grid strong,
.public-onboarding-frequency-grid strong,
.public-onboarding-slot-grid strong,
.public-onboarding-summary strong {
  font-size: 14px;
  line-height: 1.35;
}

.public-onboarding-choice-grid small,
.public-onboarding-coach-grid small,
.public-onboarding-frequency-grid small,
.public-onboarding-summary small {
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
  line-height: 1.35;
}

.public-onboarding-coach-grid > button:disabled {
  opacity: 0.52;
  background: var(--soft);
}

.public-onboarding-slot-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.public-onboarding-slot-grid > button {
  min-height: 58px;
  padding: 9px;
  text-align: center;
}

.public-onboarding-slot-grid span {
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
}

.public-onboarding-back {
  justify-self: start;
  border: 0;
  padding: 3px 0;
  background: transparent;
  color: var(--green);
  font: inherit;
  font-size: 13px;
  font-weight: 900;
}

.public-onboarding-loading,
.public-onboarding-empty,
.public-onboarding-summary {
  display: grid;
  gap: 7px;
  border-radius: 14px;
  padding: 16px;
  background: var(--soft);
  color: var(--muted);
  font-size: 13px;
  font-weight: 800;
  line-height: 1.5;
}

.public-onboarding-empty button {
  justify-self: start;
}

.public-onboarding-summary {
  background: var(--mint);
  color: var(--ink);
}

.public-onboarding-login-actions {
  display: grid;
  gap: 10px;
}

.public-onboarding-login-actions h2 {
  margin: 0;
  color: var(--ink);
  font-size: 17px;
  line-height: 1.35;
}

.recent-login-badge {
  justify-self: start;
  border: 1px solid #cfe1d9;
  border-radius: 999px;
  padding: 4px 8px;
  color: #356555;
  background: #f2faf6;
  font-size: 11px;
  font-weight: 800;
  line-height: 1.35;
}

.recent-login-badge[hidden] {
  display: none !important;
}

.public-onboarding-login-actions[hidden] {
  display: none !important;
}

.public-onboarding-existing-note {
  margin: 0;
  border-radius: 12px;
  padding: 11px 12px;
  color: var(--green);
  background: var(--mint);
  font-size: 12px;
  font-weight: 850;
  line-height: 1.45;
}

.public-onboarding-existing-note[hidden] {
  display: none !important;
}

.provider,
.primary-button,
.small-button,
.upload-button,
.tab {
  min-height: 44px;
  border: 0;
  border-radius: 8px;
  font-weight: 900;
}

.provider.kakao {
  background: var(--yellow);
  color: #191919;
}

.provider.naver {
  background: var(--naver);
  color: white;
}

.provider.apple {
  min-width: 140px;
  padding: 0;
  background: #111111;
  background-image: url("https://appleid.cdn-apple.com/appleid/button?height=44&width=220&color=black&border_radius=8&locale=ko_KR&type=continue&scale=2");
  background-repeat: no-repeat;
  background-position: center;
  background-size: auto 44px;
  color: transparent;
}

.provider.apple [data-apple-login-label] {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.provider:disabled,
.provider.is-preparing {
  cursor: not-allowed;
  opacity: 0.64;
}

.provider[aria-disabled="true"] {
  cursor: not-allowed;
  opacity: 0.64;
}

.provider-availability-note {
  margin: 6px 2px 2px;
  color: var(--muted);
  font-size: 0.875rem;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.provider.is-preparing {
  border: 1px dashed rgba(25, 25, 25, 0.2);
}

.email-login-panel {
  border-top: 1px solid var(--line);
  padding-top: 10px;
}

.email-login-panel summary {
  cursor: pointer;
  color: var(--muted);
  font-size: 14px;
  font-weight: 800;
}

.email-auth-tabs {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
  margin-top: 12px;
  padding: 4px;
  border-radius: 10px;
  background: var(--wash);
}

.email-auth-tab {
  min-height: 40px;
  border: 0;
  border-radius: 8px;
  color: var(--muted);
  background: transparent;
  font-weight: 850;
}

.email-auth-tab.is-active {
  color: var(--green);
  background: white;
  box-shadow: 0 1px 4px rgba(24, 34, 48, 0.1);
}

.email-login-form {
  display: grid;
  gap: 10px;
  margin-top: 12px;
}

.email-login-form label {
  display: grid;
  gap: 6px;
  color: var(--ink);
  font-size: 13px;
  font-weight: 800;
}

.email-login-form input {
  width: 100%;
  min-height: 44px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 0 12px;
  color: var(--ink);
  background: white;
}

.email-login-form label small,
.email-auth-note {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  font-weight: 650;
  line-height: 1.5;
}

.email-auth-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.email-auth-link {
  min-height: 40px;
  border: 0;
  padding: 0 4px;
  color: var(--blue);
  background: transparent;
  font-size: 13px;
  font-weight: 800;
}

.email-login-form .email-auth-consent {
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr);
  align-items: start;
  gap: 8px;
  font-weight: 700;
  line-height: 1.5;
}

.email-login-form .email-auth-consent input {
  width: 20px;
  min-height: 20px;
  margin: 1px 0 0;
  padding: 0;
}

.email-auth-consent a {
  color: var(--blue);
}

.login-form-status {
  min-height: 20px;
  margin: 10px 0 0;
  font-size: 13px;
  font-weight: 750;
}

.login-form-status[data-tone="done"] {
  color: var(--green);
}

.login-form-status[data-tone="alert"] {
  color: #b42318;
}

.app-screen {
  min-height: 100vh;
  padding: 20px;
  animation: screenIn 180ms ease-out;
}

.member-pending-approval #appScreen > :not(.topbar):not(#pendingApprovalGate) {
  display: none !important;
}

.member-pending-approval #coachModeButton {
  display: none !important;
}

.pending-approval-gate[hidden] {
  display: none !important;
}

.pending-approval-gate {
  display: grid;
  min-height: calc(100vh - 112px);
  place-items: center;
}

.pending-approval-card {
  display: grid;
  width: min(100%, 560px);
  gap: 16px;
  border: 1px solid rgba(21, 122, 91, 0.18);
  border-radius: 8px;
  padding: 24px;
  background: white;
  box-shadow: 0 18px 50px rgba(15, 23, 42, 0.1);
}

.pending-approval-card h2,
.pending-approval-card p {
  margin: 0;
}

.pending-approval-card h2 {
  color: var(--ink);
  font-size: 24px;
}

.pending-approval-card p:not(.eyebrow) {
  color: var(--muted);
  line-height: 1.65;
}

.pending-approval-steps {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.pending-approval-steps span {
  min-height: 42px;
  border-radius: 8px;
  padding: 10px;
  background: var(--soft-green);
  color: var(--green);
  font-size: 13px;
  font-weight: 900;
  text-align: center;
}

.pending-approval-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

@keyframes screenIn {
  from {
    opacity: 0;
    transform: translateX(18px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.topbar {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
  margin-bottom: 16px;
}

.member-heading {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.member-heading-copy {
  min-width: 0;
}

.member-heading-copy p,
.member-heading-copy h1 {
