  font-weight: 900;
}

.journal-tools-disclosure[open] summary {
  border-bottom: 1px solid var(--line);
}

.journal-tools-disclosure .journal-calendar-tools {
  padding: 10px;
}

.journal-calendar {
  display: grid;
  gap: 6px;
}

.calendar-weekdays,
.calendar-days {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 6px;
}

.calendar-weekdays b {
  display: grid;
  min-height: 26px;
  place-items: center;
  color: var(--muted);
  font-size: 12px;
}

.calendar-empty {
  min-height: 54px;
}

.journal-day {
  display: grid;
  gap: 2px;
  min-height: 54px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 6px;
  text-align: left;
  background: #f8fafc;
}

.journal-day strong {
  color: var(--ink);
  font-size: 14px;
}

.journal-day span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 900;
}

.journal-day.has-lesson {
  background: var(--soft-blue);
}

.journal-day.has-record {
  border-color: #8ac7ad;
  background: var(--soft-green);
}

.journal-day.is-selected {
  border-color: #2563eb;
  box-shadow: inset 0 0 0 2px rgba(37, 99, 235, 0.16);
}

.journal-day.matches-search {
  outline: 2px solid rgba(37, 99, 235, 0.2);
}

.journal-calendar.is-week-view .journal-day {
  min-height: 68px;
  align-content: start;
}

.journal-calendar.is-week-view .journal-day strong {
  white-space: nowrap;
}

.journal-calendar.is-week-view .journal-day span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.journal-selected-panel {
  display: grid;
  gap: 10px;
  border-top: 1px solid var(--line);
  padding-top: 12px;
}

.journal-selected-heading {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
}

.journal-selected-heading div,
.journal-selected-list,
.journal-selected-card,
.journal-selected-meta {
  display: grid;
  gap: 6px;
}

.journal-selected-heading strong {
  color: var(--ink);
}

.journal-selected-list {
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}

.journal-selected-card {
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
  background: #f8fafc;
}

.journal-selected-card.lesson {
  background: var(--soft-blue);
}

.journal-selected-card.practice {
  background: var(--soft-green);
}

.journal-selected-card-head {
  display: grid;
  gap: 4px;
}

.journal-selected-card-head span {
  color: var(--accent);
  font-size: 12px;
}

.journal-selected-card-head small,
.journal-selected-meta,
.journal-selected-card p {
  color: var(--muted);
  line-height: 1.5;
}

.journal-selected-card p {
  margin: 0;
}

.journal-selected-card-action {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
}

.journal-selected-card-action > span {
  min-width: 0;
  overflow: hidden;
  color: var(--muted);
  font-size: 12px;
  font-weight: 750;
  text-overflow: ellipsis;
  white-space: nowrap;
}

label {
  display: grid;
  gap: 6px;
  color: var(--muted);
  font-size: 13px;
  font-weight: 900;
}

select {
  width: 100%;
  min-height: 42px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 0 10px;
  background: white;
  color: var(--ink);
}

textarea {
  width: 100%;
  min-height: 90px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px;
  resize: vertical;
  color: var(--ink);
  font: inherit;
}

.primary-button {
  color: white;
  background: var(--green);
}

.request-list,
.history-list {
  display: grid;
  gap: 8px;
}

.ticket-overview {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 12px;
}

.member-alert-list {
  display: grid;
  gap: 8px;
  margin: 0 0 12px;
}

.member-alert-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
  background: white;
}

.member-alert-card.alert {
  border-color: #f3b8aa;
  background: #fff0ee;
}

.member-alert-card.wait {
  border-color: #f3c98b;
  background: var(--soft-amber);
}

.member-alert-card div {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.member-alert-card strong,
.member-alert-card span,
.member-alert-card small {
  min-width: 0;
  overflow-wrap: anywhere;
}

.member-alert-card span,
.member-alert-card small {
  color: var(--muted);
  line-height: 1.45;
}

.member-alert-card b {
  border-radius: 999px;
  padding: 7px 10px;
  color: #8a1f16;
  background: rgba(255, 255, 255, 0.74);
  font-size: 12px;
  white-space: nowrap;
}

.renewal-policy-panel,
.flow-guide {
  display: grid;
  gap: 10px;
  margin-bottom: 12px;
}

.renewal-policy-panel {
  grid-template-columns: minmax(0, 1.2fr) minmax(260px, 0.8fr);
}

.flow-guide {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.member-enrollment-status {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 4px 12px;
  align-items: center;
  border: 1px solid #b9d7ce;
  border-radius: 8px;
  padding: 13px 14px;
  background: #eef8f4;
}

.member-enrollment-status > span {
  grid-row: 1 / span 2;
  border-radius: 999px;
  padding: 6px 9px;
  color: var(--green);
  background: white;
  font-size: 11px;
  font-weight: 950;
  white-space: nowrap;
}

.member-enrollment-status strong,
.member-enrollment-status p {
  min-width: 0;
}

.member-enrollment-status p {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.45;
}

.member-enrollment-status.wait {
  border-color: #f0c781;
  background: var(--soft-amber);
}

.member-enrollment-status.journal {
  border-color: #bfd3eb;
  background: var(--soft-blue);
}

.renewal-card,
.flow-card {
  display: grid;
  gap: 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 14px;
  background: white;
}

.renewal-card.alert {
  border-color: #f3b8aa;
  background: #fff0ee;
}

.renewal-card span,
.flow-card span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 900;
}

.renewal-card strong,
.flow-card strong {
  color: var(--ink);
  line-height: 1.35;
}

.renewal-card p,
.flow-card p {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  font-weight: 750;
  line-height: 1.55;
}

.flow-card div {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.flow-card div span {
  border-radius: 999px;
  padding: 5px 8px;
  background: var(--soft-blue);
  color: var(--blue);
}

.ticket-card {
  display: grid;
  gap: 6px;
  min-height: 112px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 14px;
  background: white;
}

.ticket-card.primary {
  border-color: #34a77a;
  background: #dff7ec;
}

.ticket-card.alert {
  border-color: #f3b8aa;
  background: #fff0ee;
}

.ticket-card.wait {
  border-color: #f3c98b;
  background: var(--soft-amber);
}

.ticket-action-card {
  grid-column: 1 / -1;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  min-height: auto;
}

.ticket-action-card div {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.ticket-action-buttons {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.ticket-action-buttons .primary-button,
.ticket-action-buttons .small-button {
  align-self: center;
  white-space: nowrap;
}

.ticket-action-buttons .primary-button:disabled,
.ticket-action-buttons .small-button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.ticket-check-status {
  width: fit-content;
  border-radius: 999px;
  padding: 5px 8px;
  background: white;
}

.ticket-check-status.done {
  color: var(--green);
}

.ticket-check-status.alert {
  color: var(--danger);
}

.ticket-card span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 900;
}

.ticket-card strong {
  color: var(--ink);
  font-size: 22px;
}

.ticket-card small {
  color: var(--muted);
  font-weight: 800;
}

.lesson-status-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
  background: white;
}

.lesson-status-card.done {
  background: var(--soft-green);
}

.lesson-status-card.wait {
  background: var(--soft-amber);
}

.lesson-status-card div:first-child {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.lesson-status-card strong,
.lesson-status-card span,
.lesson-status-card small {
  min-width: 0;
  overflow-wrap: anywhere;
}

.lesson-status-card span,
.lesson-status-card small {
  color: var(--muted);
  font-size: 13px;
  font-weight: 800;
}

.lesson-status-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.notion-link {
  display: inline-grid;
  min-height: 34px;
  align-items: center;
  text-decoration: none;
}

.request-card,
.history-card {
  display: grid;
  gap: 4px;
  padding: 12px;
}

.compact-log {
  gap: 7px;
}

.summary-log {
  width: 100%;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  border: 1px solid var(--line);
  color: inherit;
  cursor: pointer;
  font: inherit;
  text-align: left;
}

.summary-log:hover,
.curriculum-compact-card:hover {
  border-color: rgba(37, 99, 235, 0.34);
  transform: translateY(-1px);
}

.summary-log-main {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.summary-log-main strong,
.summary-log-main small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.summary-log-status {
  display: inline-grid;
  min-height: 30px;
  align-items: center;
  border-radius: 999px;
  padding: 0 10px;
  background: rgba(255, 255, 255, 0.66);
  color: var(--ink);
  font-size: 12px;
  font-weight: 900;
  white-space: nowrap;
}

.compact-log .small-button {
  justify-self: start;
  min-height: 34px;
}

.request-card b {
  color: var(--amber);
  font-size: 13px;
}

.history-card.done {
  background: var(--soft-green);
}

.history-card.wait {
  background: var(--soft-amber);
}

.history-card.alert {
  border-color: #f3b8aa;
  background: #fff0ee;
}

.history-card strong,
.history-card b {
  font-size: 14px;
}

.history-card small {
  color: var(--muted);
  line-height: 1.5;
}

.list-pager {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 10px;
  flex-wrap: wrap;
}

.list-pager span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 900;
}

.page-number-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.page-number {
  display: inline-grid;
  min-width: 34px;
  min-height: 34px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: white;
  color: var(--muted);
  font-weight: 950;
  cursor: pointer;
}

.page-number.is-current {
  border-color: rgba(21, 122, 91, 0.42);
  background: var(--green);
  color: white;
}

.pass-history-card {
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px 12px;
}

.pass-history-card div {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.pass-history-card b {
  justify-self: end;
  border-radius: 999px;
  padding: 6px 10px;
  background: rgba(255, 255, 255, 0.72);
  color: var(--green);
  font-size: 12px;
  white-space: nowrap;
}

.pass-history-card > small {
  grid-column: 1 / -1;
}

.form-help {
  margin: -4px 0 12px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.5;
}

.journal-detail-card {
  display: grid;
  gap: 10px;
}

.journal-detail-card p {
  margin: 0 0 6px;
  color: var(--muted);
  line-height: 1.6;
}

.journal-detail-card strong {
  color: var(--ink);
}

/* Simplified membership purchase: five primary tabs and one-page checkout. */
.tabbar {
  grid-template-columns: repeat(5, minmax(0, 1fr));
}

.membership-product-browser,
.membership-purchase-flow {
  display: grid;
  gap: 14px;
  margin-bottom: 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 16px;
  background: #ffffff;
  box-shadow: 0 8px 22px rgba(18, 35, 31, 0.055);
}

.membership-product-browser[hidden],
.membership-purchase-flow[hidden],
.membership-current-disclosure[hidden],
.membership-help-disclosure[hidden] {
  display: none !important;
}

.membership-current-disclosure > summary small {
  margin-left: auto;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  text-align: right;
}

.membership-current-disclosure > .current-ticket-panel,
.membership-current-disclosure > .membership-details {
  margin: 12px;
}

.membership-current-disclosure > .current-ticket-panel {
  margin-bottom: 0;
}

.membership-current-disclosure:not([open]) > :not(summary),
.membership-current-disclosure .membership-details:not([open]) > :not(summary) {
  display: none !important;
}

@media (max-width: 560px) {
  .membership-current-disclosure > summary small {
    display: none;
  }
}

.membership-browser-heading,
.membership-purchase-head,
.product-group-heading,
.purchase-product-options > div:first-child,
.purchase-selected-summary,
.purchase-order-summary > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.membership-browser-heading > div,
.membership-purchase-head > div,
.purchase-step-intro,
.purchase-selected-summary,
.purchase-order-summary > div,
.purchase-complete-card {
  display: grid;
  gap: 4px;
}

.membership-browser-heading strong,
.membership-purchase-head h3,
.purchase-step-intro strong,
.purchase-product-options strong,
.purchase-selected-summary strong,
.purchase-order-summary strong,
.purchase-choice-section h4 {
  margin: 0;
  color: var(--ink);
}

.membership-browser-heading span,
.purchase-step-intro span,
.purchase-product-options span,
.purchase-selected-summary span,
.purchase-order-summary span,
.purchase-policy-note,
.purchase-complete-card p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  font-weight: 750;
  line-height: 1.5;
}

.membership-product-presets-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.membership-preset-chip {
  position: relative;
  display: grid;
  min-height: 76px;
  align-content: center;
  justify-items: start;
  gap: 4px;
  text-align: left;
}

.membership-preset-chip strong,
.membership-preset-chip small,
.membership-preset-chip b {
  pointer-events: none;
}

.membership-preset-chip strong {
  color: inherit;
  font-size: 13px;
}

.membership-preset-chip small {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.35;
}

.membership-preset-chip b {
  position: absolute;
  top: 6px;
  right: 7px;
  color: var(--green);
  font-size: 10px;
}

.product-group-heading span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
}

.membership-other-tickets {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #ffffff;
}

.membership-other-tickets > summary {
  min-height: 48px;
  padding: 0 14px;
  color: var(--ink);
  font-size: 13px;
  font-weight: 900;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.membership-other-tickets > summary::after {
  content: "+";
  color: var(--green);
  font-size: 18px;
}

.membership-other-tickets[open] > summary::after {
  content: "−";
}

.membership-other-tickets > div {
  display: grid;
  gap: 10px;
  border-top: 1px solid var(--line);
  padding: 10px;
}

.membership-ticket-unit.is-compact .membership-primary-card {
  padding: 12px;
  box-shadow: none;
}

.membership-ticket-unit.is-compact .membership-primary-card > strong {
  font-size: 17px;
}

.membership-ticket-unit.is-compact .membership-remaining-row b {
  font-size: 23px;
}

.membership-action-row.has-ticket {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.membership-action-row.has-ticket > .primary-button,
.membership-action-row.has-ticket > .membership-secondary-action,
.membership-action-row.is-empty > .primary-button,
.membership-action-row.is-empty > .membership-secondary-action {
  grid-column: 1 / -1;
}

.membership-action-row.is-empty {
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
}

.membership-purchase-progress {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.membership-purchase-progress li {
  display: grid;
  min-width: 0;
  justify-items: center;
  gap: 4px;
  color: #8b9892;
  font-size: 11px;
  font-weight: 850;
}

.membership-purchase-progress li::before {
  width: 100%;
  height: 3px;
  border-radius: 999px;
  background: #e4ebe7;
  content: "";
}

.membership-purchase-progress li.is-current,
.membership-purchase-progress li.is-done {
  color: var(--green);
}

.membership-purchase-progress li.is-current::before,
.membership-purchase-progress li.is-done::before {
  background: var(--green);
}

.membership-purchase-progress li span {
  display: grid;
  width: 24px;
  height: 24px;
  place-items: center;
  border-radius: 999px;
  color: #69756f;
  background: #edf2ef;
}

.membership-purchase-progress li.is-current span,
.membership-purchase-progress li.is-done span {
  color: #ffffff;
  background: var(--green);
}

.membership-purchase-step,
.purchase-product-options,
.purchase-choice-section {
  display: grid;
  gap: 10px;
}

.purchase-family-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.purchase-single-section,
.purchase-purpose-section {
  display: grid;
  gap: 10px;
  border-top: 1px solid var(--line);
  padding-top: 14px;
}

.purchase-single-section > h4 {
  margin: 0;
  color: var(--ink);
  font-size: 15px;
}

.purchase-renewal-ticket-field {
  display: grid;
  gap: 6px;
}

.purchase-renewal-ticket-field > span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 850;
}

.purchase-renewal-ticket-field select {
  min-height: 46px;
  border: 1px solid var(--line);
  border-radius: 9px;
  padding: 0 10px;
  background: #fff;
  font: inherit;
  font-weight: 800;
}

.purchase-family-option,
.purchase-product-option,
.purchase-choice {
  min-height: 48px;
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 10px;
  color: var(--ink);
  background: #ffffff;
  text-align: left;
}

.purchase-family-option {
  position: relative;
  display: grid;
  min-height: 86px;
  align-content: center;
  gap: 4px;
}

.purchase-family-option strong,
.purchase-family-option small,
.purchase-family-option b,
.purchase-product-option > *,
.purchase-choice > * {
  pointer-events: none;
}

.purchase-family-option small,
.purchase-product-option small,
.purchase-choice small,
.purchase-keep-summary small {
  color: var(--muted);
  font-size: 11px;
  font-weight: 750;
  line-height: 1.4;
}

.purchase-family-option b {
  position: absolute;
  top: 7px;
  right: 8px;
  color: var(--green);
  font-size: 10px;
}

.purchase-family-option.is-selected,
.purchase-product-option.is-selected,
.purchase-choice.is-selected {
  border-color: var(--green);
  background: var(--soft-green);
  box-shadow: inset 0 0 0 1px var(--green);
}

.purchase-product-option {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 5px 10px;
  align-items: center;
}

.purchase-product-option > span,
.purchase-product-option > small {
  grid-column: 1 / -1;
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
}

.purchase-product-option > strong {
  font-size: 15px;
}

.purchase-product-option > b,
.purchase-selected-summary b,
.purchase-order-summary b {
  color: var(--green);
  font-size: 17px;
}

.purchase-selected-summary,
.purchase-order-summary,
.purchase-keep-summary,
.purchase-policy-note {
  border: 1px solid #cfe3da;
  border-radius: 10px;
  padding: 12px;
  background: #f5fbf8;
}

.purchase-choice-grid,
.purchase-purpose-toggle,
.purchase-coach-grid,
.purchase-day-grid,
.purchase-time-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.purchase-day-grid {
  grid-template-columns: repeat(5, minmax(0, 1fr));
}

.purchase-time-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.purchase-choice {
  display: grid;
  align-content: center;
  gap: 3px;
}

/* P2: simple product filters and a full weekly timetable picker. */
.purchase-simple-filters {
  display: grid;
  gap: 12px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--paper);
}

.purchase-simple-filters > div {
  display: grid;
  gap: 7px;
}

.purchase-simple-filters span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
}

.purchase-simple-filters [role="group"] {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.purchase-simple-filters button {
  min-height: 40px;
  padding: 8px 14px;
  border: 1px solid var(--line);
  border-radius: 12px;
  color: var(--ink);
  background: var(--paper);
  font-weight: 800;
}

.purchase-simple-filters button.is-selected {
  border-color: var(--green);
  color: var(--green);
  background: var(--soft-green);
  box-shadow: inset 0 0 0 1px var(--green);
}

.purchase-simple-filters button:disabled,
.purchase-family-option:disabled {
  cursor: not-allowed;
  opacity: 0.48;
  box-shadow: none;
}

.purchase-show-all-products {
  width: 100%;
  color: var(--green);
}

.purchase-schedule-picker-launch {
  display: grid;
  gap: 10px;
}

.purchase-schedule-picker-launch > .primary-button {
  width: 100%;
  min-height: 48px;
}

.purchase-schedule-sheet {
  --tn-sheet-max-width: 980px;
  --tn-sheet-max-height: 920px;
}

.purchase-schedule-sheet-card {
  height: min(var(--tn-sheet-viewport-height, 94dvh), 920px);
  max-height: min(var(--tn-sheet-viewport-height, 94dvh), 920px);
}

.purchase-schedule-sheet-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 0 18px 12px;
}

.purchase-schedule-sheet-head h3,
.purchase-schedule-sheet-head p {
  margin: 0;
}

.purchase-schedule-sheet-head span {
  color: var(--green);
  font-size: 12px;
  font-weight: 900;
}

.purchase-schedule-sheet-scroll {
  padding: 0 18px 18px;
}

.purchase-schedule-weekbar {
  position: sticky;
  z-index: 8;
  top: 0;
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr) 40px auto;
  align-items: center;
  gap: 8px;
  padding: 10px 0;
  background: var(--wash);
}

.purchase-schedule-weekbar button {
  min-height: 38px;
  border: 1px solid var(--line);
  border-radius: 11px;
  color: var(--ink);
  background: var(--paper);
  font-weight: 900;
}

.purchase-schedule-weekbar button:disabled {
  opacity: 0.4;
}

.purchase-schedule-weekbar button.is-selected {
  border-color: var(--green);
  color: var(--green);
  background: var(--soft-green);
}

.purchase-schedule-weekbar strong {
  overflow: hidden;
  text-align: center;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.purchase-schedule-grid {
  overflow-x: auto;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: var(--paper);
  overscroll-behavior-x: contain;
}

.purchase-timetable {
  width: max-content;
  min-width: 100%;
}

.purchase-timetable-row {
  display: grid;
  min-width: 100%;
  border-bottom: 1px solid var(--line);
}

.purchase-timetable-row:last-child {
  border-bottom: 0;
}

.purchase-timetable-row.is-header {
  position: sticky;
  z-index: 5;
  top: 0;
  background: var(--paper);
}

.purchase-timetable-row.is-header strong,
.purchase-timetable-time,
.purchase-timetable-cell {
  display: grid;
  place-items: center;
  min-height: 48px;
  padding: 6px;
  border: 0;
  border-right: 1px solid var(--line);
  text-align: center;
  font-size: 11px;
}

.purchase-timetable-row.is-header strong {
  gap: 2px;
}

.purchase-timetable-row.is-header small {
  color: var(--muted);
  font-size: 10px;
}

.purchase-timetable-time {
  position: sticky;
  z-index: 4;
  left: 0;
  color: var(--muted);
  background: var(--paper);
  font-weight: 800;
}

.purchase-timetable-row.is-header .purchase-timetable-time {
  z-index: 6;
}

button.purchase-timetable-cell {
  cursor: pointer;
  font-weight: 900;
}

.purchase-timetable-cell.is-available {
  color: var(--green);
  background: var(--soft-green);
}

.purchase-timetable-cell.is-selected {
  color: #fff;
  background: var(--green);
}

.purchase-timetable-cell.is-conflict {
  color: #9a3412;
  background: #fff1e8;
}

.purchase-timetable-cell.is-busy {
  color: var(--muted);
  background: #eef1ef;
}

.purchase-timetable-cell.is-off {
  color: #b8c2bd;
  background: var(--wash);
}

.purchase-schedule-sheet-actions {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(140px, 220px);
  align-items: center;
  gap: 12px;
  padding: 12px 18px max(14px, env(safe-area-inset-bottom));
  border-top: 1px solid var(--line);
  background: var(--paper);
}

.purchase-schedule-sheet-actions .primary-button:disabled,
.purchase-schedule-sheet-actions .primary-button[aria-disabled="true"] {
  border: 1px solid #d0d9d4;
  color: #7a8780;
  background: #e9eeeb;
  box-shadow: none;
  opacity: 1;
}

.purchase-schedule-sheet-actions span {
  overflow: hidden;
  color: var(--ink);
  font-size: 12px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@media (max-width: 600px) {
  .purchase-schedule-sheet-card {
    width: 100%;
    height: var(--tn-sheet-viewport-height, 100dvh);
    max-height: var(--tn-sheet-viewport-height, 100dvh);
    border-radius: 0;
  }

  .purchase-schedule-sheet-scroll {
    padding-right: 10px;
    padding-left: 10px;
  }

  .purchase-schedule-weekbar {
    grid-template-columns: 36px minmax(0, 1fr) 36px auto;
    gap: 5px;
  }

  .purchase-schedule-sheet-actions {
    grid-template-columns: 1fr;
    gap: 8px;
    padding-right: 12px;
    padding-left: 12px;
  }
}

.bank-notification-bridge-card {
  border-color: #b7d8cd;
  background: #f4fbf8;
}

.bank-notification-bridge-card[hidden] {
  display: none;
}

.bank-transfer-instructions {
  display: grid;
  gap: 14px;
}

.bank-transfer-order-summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-radius: 12px;
  padding: 14px;
  background: var(--soft-green);
}

.bank-transfer-order-summary span {
  color: var(--muted);
  font-size: 13px;
  font-weight: 800;
}

.bank-transfer-order-summary strong {
  color: var(--green);
  font-size: 20px;
}

.bank-transfer-instructions dl {
  display: grid;
  gap: 1px;
  overflow: hidden;
  margin: 0;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--line);
}

.bank-transfer-instructions dl > div {
  display: grid;
  grid-template-columns: 88px minmax(0, 1fr);
  gap: 12px;
  padding: 12px 14px;
  background: #fff;
}

.bank-transfer-instructions dt {
  color: var(--muted);
  font-size: 13px;
  font-weight: 800;
}

.bank-transfer-instructions dd {
  margin: 0;
  color: var(--ink);
  font-weight: 900;
  text-align: right;
  overflow-wrap: anywhere;
}

.bank-transfer-instructions > p,
.bank-transfer-instructions > small {
  margin: 0;
  color: var(--muted);
  line-height: 1.55;
}

.discount-coupon-wallet-list {
  display: grid;
  gap: 10px;
}

.discount-coupon-wallet-card {
  display: grid;
  gap: 7px;
  border: 1px solid var(--line);
  border-left: 5px solid #98a2b3;
  border-radius: 12px;
  padding: 14px;
  background: #fff;
}

.discount-coupon-wallet-card.done {
  border-left-color: var(--green);
  background: #f6fffb;
}

.discount-coupon-wallet-card.wait {
  border-left-color: #e9a23b;
  background: #fffaf0;
}

.discount-coupon-wallet-card > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.discount-coupon-wallet-card > div span,
.discount-coupon-wallet-card small {
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
}

.discount-coupon-wallet-card b {
  color: var(--green);
  font-size: 20px;
}

.discount-coupon-wallet-card.muted {
  opacity: 0.68;
}

.purchase-coupon-select {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 12px 14px;
  background: #fff;
}

.purchase-coupon-select > span {
  color: var(--muted);
  font-size: 13px;
  font-weight: 900;
}

.purchase-coupon-select select {
  width: 100%;
  min-width: 0;
}

.purchase-coupon-note,
.purchase-discount-result {
  margin: 0;
  border-radius: 10px;
  padding: 10px 12px;
  background: #f5f7f6;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.5;
}

.purchase-discount-result {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  color: var(--green);
}

.purchase-renewal-summary,
.purchase-selected-coach {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border: 1px solid #cfe3da;
  border-radius: 10px;
  padding: 12px;
  background: #f5fbf8;
}

.purchase-renewal-summary > div,
.purchase-selected-coach > div {
  display: grid;
  min-width: 0;
  gap: 3px;
}

.purchase-renewal-summary span,
.purchase-selected-coach span {
  color: var(--green);
  font-size: 10px;
  font-weight: 900;
}

.purchase-renewal-summary strong,
.purchase-selected-coach strong {
  overflow: hidden;
  color: var(--ink);
  font-size: 14px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.purchase-renewal-summary small,
.purchase-selected-coach small {
  color: var(--muted);
  font-size: 11px;
  font-weight: 750;
}

.purchase-renewal-summary > button,
.purchase-selected-coach > button {
  flex: 0 0 auto;
  min-height: 40px;
}

.purchase-coach-first {
  margin: 0;
  text-align: center;
}

.purchase-keep-summary {
  display: grid;
  gap: 6px;
}

.purchase-keep-summary > span {
  color: var(--green);
  font-size: 11px;
  font-weight: 900;
}

.purchase-renewal-choice,
.purchase-slot-groups,
.purchase-slot-group {
  display: grid;
  gap: 10px;
}

.purchase-schedule-count {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  border-radius: 9px;
  padding: 9px 11px;
  color: var(--muted);
  background: #f5f7f6;
  font-size: 11px;
}

.purchase-schedule-count strong {
  flex: 0 0 auto;
  color: var(--green);
  font-size: 13px;
}

.purchase-selected-schedule-list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.purchase-selected-schedule-list span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 1px solid #cfe3da;
  border-radius: 999px;
  padding: 6px 9px;
  color: var(--ink);
  background: #f5fbf8;
  font-size: 11px;
  font-weight: 800;
}

.purchase-selected-schedule-list b {
  display: inline-grid;
  width: 18px;
  height: 18px;
  place-items: center;
  border-radius: 50%;
  color: #fff;
  background: var(--green);
  font-size: 10px;
}

.purchase-coach-filter-grid,
.purchase-date-filter-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.purchase-coach-filter,
.purchase-date-filter {
  display: grid;
  min-height: 64px;
  align-content: center;
  gap: 4px;
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 9px 10px;
  color: var(--ink);
  background: #ffffff;
  text-align: left;
}

.purchase-coach-filter strong,
.purchase-date-filter strong {
  font-size: 13px;
}

.purchase-coach-filter small,
.purchase-date-filter small {
  color: var(--muted);
  font-size: 10px;
  font-weight: 750;
}

.purchase-coach-filter.is-selected,
.purchase-date-filter.is-selected {
  border-color: var(--green);
  color: var(--green);
  background: var(--soft-green);
  box-shadow: inset 0 0 0 1px var(--green);
}

.purchase-coach-filter.is-unavailable,
.purchase-coach-filter:disabled {
  cursor: not-allowed;
  opacity: 0.62;
  background: #f3f5f4;
}

.purchase-slot-card-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.purchase-quick-slot-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.purchase-show-more-slots {
  width: 100%;
  min-height: 44px;
}

.purchase-slot-card {
  display: grid;
  min-height: 58px;
  align-content: center;
  gap: 3px;
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 9px;
  color: var(--ink);
  background: #fff;
  text-align: left;
}

.purchase-slot-card span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 750;
}

.purchase-slot-card.is-selected {
  border-color: var(--green);
  color: var(--green);
  background: var(--soft-green);
  box-shadow: inset 0 0 0 1px var(--green);
}

.purchase-slot-group {
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 12px;
  background: #f8faf9;
}

.purchase-slot-group > div:first-child {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.purchase-slot-group > div:first-child strong {
  color: var(--ink);
  font-size: 14px;
}

.purchase-slot-group > div:first-child span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 750;
}

.purchase-time-select-field {
  display: grid;
  gap: 6px;
}

.purchase-time-select-field > span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 850;
}

.purchase-time-select-field select {
  width: 100%;
  min-height: 48px;
  border: 1px solid var(--line);
  border-radius: 9px;
  padding: 0 12px;
  color: var(--ink);
  background: #ffffff;
  font: inherit;
  font-weight: 850;
}

.purchase-time-select-field select:focus {
  border-color: var(--green);
  outline: 2px solid rgba(10, 125, 91, 0.14);
}

.purchase-slot-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 7px;
}

.purchase-slot {
  display: grid;
  min-height: 54px;
  align-content: center;
  justify-items: center;
  gap: 2px;
  border: 1px solid var(--line);
  border-radius: 9px;
  padding: 7px 5px;
  color: var(--ink);
  background: #ffffff;
}

.purchase-slot span {
  color: var(--muted);
  font-size: 10px;
  font-weight: 750;
}

.purchase-slot strong {
  font-size: 14px;
}

.purchase-slot.is-selected {
  border-color: var(--green);
  color: var(--green);
  background: var(--soft-green);
  box-shadow: inset 0 0 0 1px var(--green);
}

.purchase-availability-state {
  margin: 0;
  border: 1px dashed var(--line);
  border-radius: 10px;
  padding: 18px 12px;
  color: var(--muted);
  background: #f8faf9;
  font-size: 12px;
  font-weight: 800;
  text-align: center;
}

.purchase-availability-state.is-error {
  border-color: #e8c7c1;
  color: #9b3f34;
  background: #fff8f7;
}

.purchase-step-actions {
  display: grid;
  grid-template-columns: minmax(0, 0.45fr) minmax(0, 1fr);
  gap: 8px;
  padding-top: 4px;
}

.purchase-step-actions button {
  min-height: 48px;
}

.purchase-pay-action {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.purchase-pay-action .primary-button {
  width: 100%;
}

.purchase-pay-action .primary-button:disabled {
  color: #66766f;
  background: #d6dfdb;
  box-shadow: none;
  cursor: not-allowed;
  opacity: 1;
}

.purchase-pay-action small {
  color: var(--muted);
  font-size: 10px;
  font-weight: 750;
  line-height: 1.35;
  text-align: center;
}

.purchase-complete-card {
  justify-items: center;
  border: 1px solid #9acbb9;
  border-radius: 12px;
  padding: 24px 16px;
  background: var(--soft-green);
  text-align: center;
}

.purchase-complete-card > span {
  display: grid;
  width: 52px;
  height: 52px;
  place-items: center;
  border-radius: 999px;
  color: #ffffff;
  background: var(--green);
  font-size: 28px;
  font-weight: 900;
}

.purchase-complete-card > div {
  display: grid;
  width: min(100%, 440px);
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-top: 8px;
}

.membership-pending-records {
  margin: 0;
  box-shadow: none;
}

@media (max-width: 720px) {
  .tabbar {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }

  .membership-product-browser,
  .membership-purchase-flow {
    padding: 12px;
  }

  .membership-browser-heading {
    display: grid;
  }

  .membership-browser-heading > button {
    width: 100%;
    min-height: 46px;
  }

  .membership-product-presets-grid,
  .purchase-family-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .membership-product-presets-grid > :last-child {
    grid-column: 1 / -1;
  }

  .purchase-coach-grid,
  .purchase-time-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .purchase-slot-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .purchase-coach-filter-grid,
  .purchase-date-filter-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .purchase-slot-card-grid,
  .purchase-quick-slot-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .purchase-day-grid {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }

  .purchase-day-grid .purchase-choice {
    min-height: 46px;
    padding-inline: 3px;
    text-align: center;
  }

  .purchase-step-actions {
    position: sticky;
    bottom: calc(var(--tn-bottom-nav-height) + max(14px, env(safe-area-inset-bottom)));
    z-index: 5;
    margin: 4px -4px -4px;
    padding: 8px 4px 4px;
    background: rgba(255, 255, 255, 0.96);
  }

}

@media (max-width: 420px) {
  .membership-purchase-progress li b {
    font-size: 10px;
  }

  .purchase-family-option,
  .membership-preset-chip {
    min-height: 78px;
  }

  .purchase-product-option {
    grid-template-columns: 1fr;
  }

  .purchase-slot-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .purchase-product-option > span,
  .purchase-product-option > small {
    grid-column: auto;
  }

  .membership-action-row.has-ticket,
  .membership-action-row.is-empty,
  .purchase-complete-card > div {
    grid-template-columns: 1fr;
  }

  .membership-action-row.has-ticket > .primary-button,
  .membership-action-row.has-ticket > .membership-secondary-action,
  .membership-action-row.is-empty > .primary-button,
  .membership-action-row.is-empty > .membership-secondary-action {
