}

.journal-lesson-result {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  border: 1px solid #d8e9e2;
  border-radius: 10px;
  padding: 10px 12px;
  background: #f2faf7;
}

.journal-lesson-result span {
  color: var(--ink);
  font-size: 13px;
  font-weight: 900;
}

.journal-lesson-result strong {
  border-radius: 999px;
  padding: 4px 8px;
  color: var(--green);
  background: white;
  font-size: 12px;
  overflow-wrap: anywhere;
  text-align: right;
}

.journal-lesson-result small {
  grid-column: 1 / -1;
  color: var(--muted);
  font-size: 12px;
  text-align: right;
}

.journal-feedback-block {
  display: grid;
  gap: 6px;
  border: 1px solid var(--line);
  border-left: 4px solid #8aa79d;
  border-radius: 7px;
  padding: 12px;
  background: #f8faf9;
}

.journal-feedback-block.coach-note {
  border-left-color: var(--green);
  background: #eef8f4;
}

.journal-feedback-block.next-note {
  border-left-color: #2f6fb5;
  background: #f1f6fb;
}

.journal-feedback-block p {
  color: var(--ink);
  font-size: 15px;
  line-height: 1.65;
  white-space: pre-wrap;
}

.journal-entry-list {
  display: grid;
  gap: 8px;
}

.journal-entry-button {
  display: grid;
  gap: 4px;
  min-height: 72px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px;
  text-align: left;
  background: white;
}

.journal-entry-button strong {
  color: var(--green);
}

.journal-entry-button span,
.journal-entry-button small {
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
}

.split-panel {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(260px, 0.8fr);
  gap: 12px;
}

.split-panel h3 {
  margin: 0 0 8px;
}

.curriculum-card {
  display: grid;
  gap: 8px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 0;
  background: var(--soft-blue);
}

.curriculum-compact-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 4px 10px;
  align-items: center;
  width: 100%;
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 12px;
  background: transparent;
  color: inherit;
  cursor: pointer;
  font: inherit;
  text-align: left;
}

.curriculum-compact-card span,
.curriculum-compact-card small {
  color: var(--muted);
  font-size: 12px;
  font-weight: 900;
}

.curriculum-compact-card strong,
.curriculum-compact-card small {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.curriculum-compact-card b {
  grid-row: 1 / span 3;
  grid-column: 2;
  display: inline-grid;
  min-height: 30px;
  align-items: center;
  border-radius: 999px;
  padding: 0 10px;
  background: white;
  color: var(--blue);
  font-size: 12px;
  white-space: nowrap;
}

.curriculum-main-card {
  margin-bottom: 12px;
}

.curriculum-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  border: 1px solid rgba(21, 122, 91, 0.22);
  border-radius: 8px;
  padding: 14px;
  background: white;
}

.curriculum-hero div {
  display: grid;
  gap: 5px;
  min-width: 0;
}

.curriculum-hero span {
  color: var(--green);
  font-size: 12px;
  font-weight: 950;
}

.curriculum-hero strong {
  color: var(--ink);
  font-size: 18px;
  line-height: 1.35;
}

.curriculum-hero p {
  margin: 0;
  color: var(--muted);
  line-height: 1.55;
}

.curriculum-hero-actions {
  display: grid;
  gap: 8px;
  justify-items: end;
}

.curriculum-summary {
  display: grid;
  gap: 6px;
}

.curriculum-summary > span,
.curriculum-stage span,
.journal-curriculum-card > span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 900;
}

.curriculum-summary strong,
.curriculum-stage strong,
.journal-curriculum-card strong {
  color: var(--ink);
  line-height: 1.35;
}

.curriculum-card span,
.curriculum-card p {
  margin: 0;
  color: var(--muted);
  line-height: 1.6;
}

.curriculum-stage-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.curriculum-stage {
  display: grid;
  gap: 5px;
  min-height: 112px;
  border: 1px solid rgba(37, 87, 167, 0.18);
  border-radius: 8px;
  padding: 10px;
  background: white;
}

.curriculum-stage.current {
  border-color: rgba(21, 122, 91, 0.28);
  background: var(--soft-green);
}

.curriculum-stage.next {
  border-color: rgba(37, 87, 167, 0.28);
}

.curriculum-stage.review {
  background: #fff8eb;
}

.curriculum-stage small {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
}

.curriculum-full-list {
  display: grid;
  gap: 12px;
}

.curriculum-progress-board {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.curriculum-progress-board article {
  display: grid;
  gap: 5px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
  background: white;
}

.curriculum-progress-board article.is-active {
  border-color: rgba(21, 122, 91, 0.28);
  background: var(--soft-green);
  box-shadow: inset 4px 0 0 var(--green);
}

.curriculum-progress-board article.is-waiting {
  background: #f8fafc;
}

.curriculum-progress-board span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 950;
}

.curriculum-progress-board strong {
  color: var(--ink);
  font-size: 18px;
}

.curriculum-progress-board small {
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
  line-height: 1.4;
}

.member-curriculum-toolbar {
  display: grid;
  gap: 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
  background: white;
}

.member-curriculum-search-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
}

.member-curriculum-search-row input {
  width: 100%;
  min-height: 42px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 0 12px;
  color: var(--ink);
  background: #f8fafc;
  font: inherit;
}

.member-curriculum-search-row b {
  color: var(--muted);
  font-size: 12px;
  white-space: nowrap;
}

.curriculum-filter-row {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.curriculum-filter {
  min-height: 34px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 0 11px;
  color: var(--muted);
  background: #f8fafc;
  font-weight: 900;
}

.curriculum-filter.is-active {
  border-color: var(--green);
  color: white;
  background: var(--green);
}

#memberCurriculumLibrary {
  display: grid;
  gap: 9px;
}

.curriculum-category {
  display: grid;
  gap: 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 14px;
  background: white;
}

.curriculum-category-heading {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
}

.curriculum-track > summary {
  cursor: pointer;
  list-style: none;
}

.curriculum-track > summary::-webkit-details-marker {
  display: none;
}

.curriculum-track > summary::after {
  content: "+";
  display: grid;
  width: 26px;
  height: 26px;
  grid-column: 2;
  grid-row: 1;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  color: var(--muted);
  background: white;
}

.curriculum-track[open] > summary::after {
  content: "−";
}

.curriculum-track .curriculum-category-heading b {
  margin-right: 34px;
}

.curriculum-track-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  border-top: 1px solid var(--line);
  padding-top: 10px;
}

.curriculum-track-actions span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 850;
}

.curriculum-category-heading div {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.curriculum-category-heading strong {
  color: var(--ink);
  font-size: 18px;
}

.curriculum-category-heading span {
  color: var(--muted);
  font-size: 13px;
  font-weight: 800;
  line-height: 1.45;
}

.curriculum-category-heading b {
  border-radius: 999px;
  padding: 6px 10px;
  color: var(--green);
  background: var(--soft-green);
  font-size: 12px;
  white-space: nowrap;
}

.curriculum-step-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.curriculum-step {
  display: grid;
  gap: 8px;
  border: 1px solid rgba(37, 87, 167, 0.16);
  border-radius: 8px;
  padding: 12px;
  background: #f8fafc;
}

.curriculum-step.is-current {
  border-color: rgba(21, 122, 91, 0.34);
  background: var(--soft-green);
  box-shadow: inset 4px 0 0 var(--green);
}

.curriculum-step div {
  display: grid;
  gap: 3px;
}

.curriculum-step span {
  color: var(--blue);
  font-size: 12px;
  font-weight: 950;
}

.curriculum-step strong {
  color: var(--ink);
  line-height: 1.35;
}

.curriculum-step p {
  display: grid;
  grid-template-columns: 64px minmax(0, 1fr);
  gap: 8px;
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
  line-height: 1.45;
}

.curriculum-step p b {
  color: var(--ink);
}

.curriculum-step .small-button {
  justify-self: start;
  min-height: 34px;
}

.curriculum-resource-links,
.curriculum-video-item {
  display: grid;
  gap: 8px;
  min-width: 0;
}

.curriculum-video-frame {
  width: 100%;
  aspect-ratio: 16 / 9;
  border: 0;
  border-radius: 8px;
  background: #000;
}

.curriculum-video-fallback {
  width: fit-content;
  color: var(--blue);
  font-size: 12px;
  font-weight: 850;
}

.curriculum-environment-note {
  border-left: 3px solid var(--amber);
  padding-left: 8px;
  color: #8a5a12;
  font-size: 11px;
  font-weight: 850;
  line-height: 1.45;
}

.curriculum-empty {
  border: 1px dashed var(--line);
  border-radius: 8px;
  padding: 18px;
  background: white;
  text-align: center;
}

.journal-curriculum-card {
  display: grid;
  gap: 7px;
  margin-top: 4px;
  border: 1px solid rgba(37, 87, 167, 0.18);
  border-radius: 8px;
  padding: 12px;
  background: var(--soft-blue);
}

.empty-text {
  margin: 0;
  color: var(--muted);
}

@media (max-width: 720px) {
  .app-screen {
    padding: 14px;
  }

  .view > .section-title > span,
  .view > .section-title > div > span,
  .journal-calendar-head > div:first-child > span {
    display: none;
  }

  .summary-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
    margin-bottom: 10px;
  }

  .home-view .summary-grid[data-card-count="1"],
  .home-view .summary-grid[data-card-count="2"] {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .home-view .summary-grid[data-card-count="1"] article,
  .home-view .summary-grid[data-card-count="2"] article:not(.primary) {
    grid-column: 1 / -1;
  }

  .summary-grid article {
    gap: 5px;
    min-height: 116px;
    padding: 12px;
  }

  .home-view .summary-grid .summary-card.primary {
    grid-column: 1 / -1;
    grid-template-areas:
      "label action"
      "value action"
      "detail action";
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    min-height: 118px;
  }

  .home-view .summary-card.primary > span {
    grid-area: label;
  }

  .home-view .summary-card.primary > strong {
    grid-area: value;
  }

  .home-view .summary-card.primary > small {
    grid-area: detail;
  }

  .home-view .summary-card.primary > button {
    grid-area: action;
    align-self: center;
  }

  .home-onboarding {
    grid-template-columns: minmax(0, 1fr);
    padding: 14px;
  }

  .home-onboarding .primary-button {
    width: 100%;
  }

  .home-onboarding .home-onboarding-actions {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    width: 100%;
  }

  .home-onboarding-actions .small-button,
  .home-onboarding-actions .primary-button {
    width: 100%;
    min-width: 0;
  }

  .summary-grid span {
    font-size: 12px;
  }

  .summary-grid strong {
    font-size: 22px;
    line-height: 1.15;
  }

  .summary-grid small {
    font-size: 12px;
    line-height: 1.35;
  }

  .today-action-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .profile-form-grid,
  .ntrp-panel,
  .ntrp-reference-grid,
  .ntrp-quick-guide,
  .profile-summary,
  .split-panel {
    grid-template-columns: 1fr;
  }

  .journal-calendar-head,
  .journal-calendar-tools,
  .journal-selected-heading {
    grid-template-columns: 1fr;
  }

  .journal-calendar-controls {
    justify-content: space-between;
  }

  .calendar-empty,
  .journal-day {
    min-height: 46px;
  }

  .journal-day {
    align-content: start;
    padding: 5px;
  }

  .journal-day strong {
    font-size: 13px;
  }

  .journal-day span {
    font-size: 9px;
  }

  .flow-guide,
  .renewal-policy-panel,
  .curriculum-progress-board,
  .curriculum-step-list,
  .curriculum-hero,
  .curriculum-category-heading {
    grid-template-columns: 1fr;
  }

  .slot-list {
    grid-template-columns: 1fr;
  }

  .brand h1 {
    font-size: 26px;
  }

  .tabbar {
    display: flex;
    overflow-x: auto;
    gap: 7px;
    margin-right: -14px;
    padding-right: 14px;
    scrollbar-width: none;
  }

  .tabbar::-webkit-scrollbar {
    display: none;
  }

  .tabbar .tab {
    flex: 0 0 auto;
    min-height: 38px;
    padding: 0 13px;
    white-space: nowrap;
  }
}

.eyebrow {
  margin: 0 0 6px;
  color: var(--green);
  font-size: 12px;
  font-weight: 900;
  text-transform: uppercase;
}

.channel-button {
  display: inline-grid;
  min-height: 44px;
  align-items: center;
  border-radius: 8px;
  padding: 0 14px;
  background: var(--yellow);
  color: #191919;
  font-weight: 900;
  text-decoration: none;
}

.notice-dialog[hidden] {
  display: none;
}

.notice-dialog,
.change-request-modal {
  position: fixed;
  inset: 0;
  z-index: 20;
  display: grid;
  place-items: center;
  padding: 20px;
}

.notice-dialog {
  --notice-inset-top: max(20px, env(safe-area-inset-top));
  --notice-inset-right: max(20px, env(safe-area-inset-right));
  --notice-inset-bottom: max(20px, env(safe-area-inset-bottom));
  --notice-inset-left: max(20px, env(safe-area-inset-left));
  z-index: 1000;
  isolation: isolate;
  padding: var(--notice-inset-top) var(--notice-inset-right) var(--notice-inset-bottom) var(--notice-inset-left);
  overscroll-behavior: contain;
}

.notice-backdrop,
.modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(24, 34, 48, 0.38);
}

.notice-card,
.change-modal-card {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 12px;
  width: min(420px, 100%);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 18px;
  background: white;
  box-shadow: 0 18px 42px rgba(24, 34, 48, 0.18);
}

.notice-card {
  grid-template-rows: minmax(0, 1fr) auto;
  gap: 0;
  max-height: calc(100dvh - var(--notice-inset-top) - var(--notice-inset-bottom));
  padding: 0;
  overflow: hidden;
}

.notice-scroll-region {
  display: grid;
  gap: 12px;
  min-height: 0;
  padding: 18px;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
}

.change-request-modal[hidden] {
  display: none;
}

.change-modal-card {
  width: min(520px, 100%);
  max-height: min(92vh, 760px);
  overflow: auto;
}

.identity-setup-modal {
  z-index: 60;
}

.identity-setup-card {
  width: min(460px, 100%);
}

.identity-setup-card > p {
  margin: 0;
  color: var(--muted);
  line-height: 1.55;
}

.identity-setup-form {
  display: grid;
  gap: 12px;
}

.identity-setup-form label > span {
  color: var(--ink);
}

.identity-demographics-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.identity-setup-form small {
  color: var(--muted);
  font-weight: 500;
}

.identity-phone-verification {
  display: grid;
  gap: 10px;
  margin-top: -6px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #f8fbfa;
}

.identity-phone-actions,
.identity-phone-code-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 10px;
}

.identity-phone-actions small {
  line-height: 1.45;
}

.identity-phone-actions small.is-verified {
  color: var(--green);
  font-weight: 800;
}

.identity-phone-actions small.is-error {
  color: #b42318;
  font-weight: 700;
}

.identity-phone-code-row label {
  margin: 0;
}

/* The profile OTP surface also works in a desktop-width/native landscape
   viewport; do not rely only on the foundation's mobile media query. */
#profileEditorSheet :is(#profilePhoneInput, #profilePhoneCode) {
  min-height: 44px;
  font-size: 16px;
}

/* OTP input is the flexible column; its confirmation must not collapse in
   the two-column profile form on tablet/desktop or native landscape. */
#profilePhoneCodeRow {
  grid-template-columns: minmax(0, 1fr) auto;
}

#profilePhoneVerifyButton {
  min-width: 64px;
  min-height: 44px;
  font-size: 16px;
  white-space: nowrap;
}

@media (max-width: 420px) {
  .identity-demographics-grid {
    grid-template-columns: 1fr;
  }

  .identity-phone-actions,
  .identity-phone-code-row {
    grid-template-columns: 1fr;
  }
}

.identity-setup-form .consent-row {
  grid-template-columns: 20px minmax(0, 1fr);
  align-items: start;
  gap: 8px;
  border-top: 1px solid var(--line);
  padding-top: 12px;
  line-height: 1.5;
}

.identity-setup-form .consent-row input {
  width: 18px;
  height: 18px;
  margin: 1px 0 0;
}

.identity-setup-form .consent-row a {
  color: var(--blue);
  text-decoration: underline;
  text-underline-offset: 2px;
}

.identity-consent-list {
  display: grid;
  gap: 10px;
}

.identity-marketing-consents {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin: 0;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px;
}

.identity-marketing-consents legend {
  padding: 0 4px;
  color: var(--ink);
  font-size: 13px;
  font-weight: 800;
}

.identity-marketing-consents label {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 6px;
  color: var(--ink);
  font-size: 13px;
  font-weight: 700;
}

.identity-marketing-consents input {
  flex: 0 0 auto;
  width: 18px;
  height: 18px;
  margin: 0;
}

body.identity-setup-required {
  overflow: hidden;
}

.member-enrollment-modal-card {
  width: min(680px, 100%);
}

.member-enrollment-product {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 3px 10px;
  align-items: center;
  border-left: 4px solid var(--green);
  padding: 10px 12px;
  background: var(--soft-green);
}

.member-enrollment-product > span {
  grid-row: 1 / span 2;
  color: var(--green);
  font-size: 11px;
  font-weight: 950;
}

.member-enrollment-product small {
