  color: #00883e;
  background: #f2fff7;
}

.payment-method-option[data-select-payment-method="tosspay"].is-selected {
  border-color: #1b64da;
  color: #0f4fb9;
  background: #f1f6ff;
}

.payment-method-option[data-select-payment-method="kakaopay"].is-selected {
  border-color: #e2c900;
  color: #2f2810;
  background: #fffbe0;
}

.payment-method-option:disabled {
  color: #8a929c;
