  font-size: 13px;
}

.purchase-payment-summary {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 12px;
  width: 100%;
  min-height: 68px;
  border: 1px solid rgba(15, 118, 110, 0.22);
  border-radius: 12px;
  padding: 12px 14px;
  color: var(--ink);
  background: white;
  text-align: left;
}

.purchase-payment-summary span {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.purchase-payment-summary small {
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
}

.purchase-payment-summary strong,
.purchase-payment-summary b {
  font-size: 15px;
}

.purchase-payment-summary em {
  color: var(--green);
  font-size: 12px;
  font-style: normal;
  font-weight: 900;
}

.purchase-payment-summary:focus-visible {
  outline: 3px solid rgba(15, 118, 110, 0.25);
  outline-offset: 2px;
}

.purchase-payment-method-sheet .sheet-card {
