}

.purchase-schedule-sheet-coaches {
  display: grid;
  gap: 8px;
  margin-bottom: 12px;
}

.payment-method-sheet-options {
  display: grid;
  gap: 16px;
  padding: 8px 16px calc(18px + env(safe-area-inset-bottom));
}

.payment-method-group {
  display: grid;
  gap: 8px;
}

.payment-method-group + .payment-method-group {
