  color: var(--ink);
  font-size: 15px;
  font-weight: 900;
}

.payment-method-group-options {
  display: grid;
  gap: 8px;
}

.payment-method-sheet-options .payment-method-option {
  grid-template-columns: 20px minmax(0, 1fr) auto;
  align-items: center;
  column-gap: 12px;
  width: 100%;
  min-height: 70px;
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 12px 14px;
  text-align: left;
}

.payment-method-choice-marker {
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  border: 1.5px solid #8a929c;
  border-radius: 50%;
}

.payment-method-option.is-selected .payment-method-choice-marker::after {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: currentColor;
  content: "";
}

.payment-method-option-copy {
  display: grid;
  min-width: 0;
  gap: 3px;
}

.payment-method-sheet-options .payment-method-option strong {
  font-size: 15px;
}

.payment-method-sheet-options .payment-method-option small {
  font-size: 11px;
}

.payment-method-option-price {
  color: currentColor;
  font-size: 15px;
  white-space: nowrap;
}

.product-group {
  display: grid;
  gap: 8px;
}

.product-group h3 {
  margin: 0;
  font-size: 17px;
}

.product-group-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.product-card {
  display: grid;
  gap: 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
  background: white;
  align-content: start;
}

.product-card-summary {
  display: grid;
  gap: 4px;
}

.product-card-title {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 8px;
  align-items: center;
}

.product-card i {
  width: fit-content;
  border-radius: 999px;
  padding: 4px 8px;
  color: var(--blue);
  background: var(--soft-blue);
  font-size: 11px;
  font-style: normal;
  font-weight: 950;
}

.product-card span {
  color: var(--muted);
  line-height: 1.5;
}

.product-card > b {
  color: var(--green);
  font-size: 20px;
}

.product-meta-pills {
  display: flex !important;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 4px;
}

.product-meta-pills span {
  border-radius: 999px;
  padding: 5px 8px;
  background: var(--soft-green);
  color: var(--green);
  font-size: 11px;
  font-weight: 950;
  line-height: 1;
}

.product-price-panel {
  display: grid !important;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  border: 1px solid rgba(21, 122, 91, 0.14);
  border-radius: 8px;
  padding: 10px;
  background: var(--soft-green);
}

.product-price-panel.consult {
  grid-template-columns: 1fr;
  background: var(--soft-amber);
  border-color: rgba(160, 105, 38, 0.18);
}

.product-price-panel div {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.product-price-panel span,
.product-price-panel small {
  color: var(--muted);
  font-size: 11px;
  font-weight: 900;
  line-height: 1.3;
}

.product-price-panel strong {
  color: var(--green);
  font-size: 18px;
  font-weight: 950;
  line-height: 1.2;
}

.product-price-panel b {
  color: var(--ink);
  font-size: 18px;
  font-weight: 950;
  line-height: 1.2;
}

.product-price-panel.one-day-offer {
  grid-template-columns: minmax(0, 0.8fr) minmax(0, 1.2fr);
}

.product-price-panel.one-day-offer > small {
