.product-price-panel.one-day-offer b {
  font-size: 12px;
  line-height: 1.35;
}

.product-price-panel.one-day-offer.is-eligible {
  border-color: rgba(21, 122, 91, 0.42);
  background: #e8f8f1;
}

.product-card-details {
  border-top: 1px solid var(--line);
}

.product-card-details > summary {
  display: flex;
  min-height: 38px;
  align-items: center;
  color: var(--muted);
  cursor: pointer;
  font-size: 12px;
  font-weight: 900;
  list-style: none;
}

.product-card-details > summary::-webkit-details-marker {
  display: none;
}

.product-card-details > summary::after {
  content: "+";
  margin-left: auto;
  color: var(--green);
  font-size: 16px;
}

.product-card-details[open] > summary::after {
  content: "−";
}

.product-card-details > div {
  display: grid;
  gap: 6px;
  padding-bottom: 8px;
}

.product-card-details p,
.product-card-details small {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  font-weight: 750;
  line-height: 1.45;
}

.product-flow-text {
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
  line-height: 1.5;
}

.form-card h3 {
  margin: 0;
}

@media (max-width: 720px) {
  .tabbar,
  .product-grid,
  .product-group-grid,
  .ticket-overview,
  .member-alert-card,
  .notice-actions {
    grid-template-columns: 1fr;
  }

  .product-price-panel {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .topbar {
    align-items: stretch;
  }

  .ntrp-official-summary {
    grid-template-columns: 1fr;
  }

  .profile-card {
    grid-template-columns: 72px minmax(0, 1fr);
    align-items: center;
    justify-items: stretch;
  }

  .profile-avatar.large {
    width: 72px;
    height: 72px;
    font-size: 26px;
  }

  .profile-info strong {
    font-size: 18px;
  }

  .lesson-status-card {
    grid-template-columns: 1fr;
  }

  .pass-history-card {
    grid-template-columns: 1fr;
  }

  .pass-history-card b {
    justify-self: start;
  }

  .member-alert-card b {
    justify-self: start;
  }

  .lesson-status-actions {
    justify-content: flex-start;
  }

  .curriculum-stage-grid {
    grid-template-columns: 1fr;
  }
