  color: var(--muted);
  text-align: center;
  font-size: 13px;
  font-weight: 800;
}

.legal-links a:hover,
.app-legal-links a:hover {
  color: var(--green);
}

.app-legal-links {
  margin-top: 18px;
  padding: 18px 0 4px;
}

#appScreen > .app-legal-links {
  display: none;
}

body[data-active-member-view="profileView"] #appScreen > .app-legal-links {
  display: flex;
}

.release-version {
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
  line-height: 1.35;
}

.member-heading-copy .release-version {
  display: block;
  margin-top: 2px;
}

.app-legal-links .release-version {
  flex-basis: 100%;
}

.coach-feedback,
.next-lesson-note {
  margin: 4px 0 0;
  color: var(--blue);
  font-weight: 800;
}
.product-card em {
  display: block;
  margin-top: 6px;
  color: var(--blue);
  font-size: 12px;
  font-style: normal;
  font-weight: 900;
  line-height: 1.5;
}

.group-account-panel:empty {
  display: none;
}

.member-group-account-card {
  display: grid;
  gap: 12px;
  margin: 12px 0 18px;
  padding: 14px;
  border: 1px solid var(--line);
  border-left: 4px solid var(--green);
  border-radius: 8px;
  background: var(--paper);
}

.member-group-account-heading,
.member-group-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
}

.member-group-account-heading > div,
.member-group-payment-status {
  display: grid;
  gap: 3px;
}

.member-group-account-heading span,
.member-group-account-heading small,
.member-group-payment-status span,
.member-group-payment-status small,
.member-group-people span,
.member-group-people small {
  color: var(--muted);
  font-size: 12px;
}

.member-group-account-heading b {
  color: var(--green);
  font-size: 12px;
}

.member-group-people {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.member-group-people > div {
  display: grid;
  gap: 4px;
  min-width: 0;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--booking-panel);
}

.member-group-actions {
  justify-content: flex-start;
}

@media (max-width: 560px) {
  .member-group-people {
    grid-template-columns: 1fr;
  }
}

/* Android phone ergonomics: keep primary navigation reachable and text legible. */
input[type="text"],
input[type="date"],
input[type="search"],
input[type="number"],
input[type="tel"],
input[type="email"] {
  width: 100%;
  min-height: 44px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 9px 10px;
  color: var(--ink);
  background: white;
  font: inherit;
}

/* iOS Safari auto-zooms focused form controls below 16px. Keep this scoped to
   the member email-auth panel so other member, coach, and admin forms retain
   their existing typography. */
.email-login-panel .email-login-form :is(
  input[type="text"],
  input[type="email"],
  input[type="password"],
  input[type="tel"],
  input[type="number"],
  select,
  textarea
) {
  min-height: 44px;
  font-size: 16px;
}

.title-action,
.curriculum-step .small-button,
.pagination button,
.journal-calendar-controls .small-button,
.member-schedule-filter,
.week-switcher button {
  min-height: 44px;
}

.member-schedule-filter {
  min-width: 44px;
}

select {
  min-height: 44px;
}

.page-number,
.notion-link,
.legal-links a,
.app-legal-links a {
  min-height: 44px;
}

.page-number {
  min-width: 44px;
}

.legal-links a,
.app-legal-links a {
  display: inline-flex;
  align-items: center;
}

.ntrp-question label {
  grid-template-columns: 20px minmax(0, 1fr);
  min-height: 44px;
  align-items: center;
  padding: 4px 0;
}

.ntrp-question input[type="radio"] {
  width: 20px;
  height: 20px;
}

.member-duration-schedule {
  min-width: 0;
}

.member-time-rail,
.member-day-column {
  grid-template-rows: repeat(var(--slot-count, 17), 44px);
}

.member-day-column {
  grid-template-columns: repeat(var(--coach-count, 3), minmax(64px, 1fr));
}

.member-slot-bg span,
.member-slot-bg small {
  overflow: visible;
  text-overflow: clip;
  white-space: normal;
  word-break: keep-all;
}

@media (max-width: 720px) {
  .member-time-rail,
  .member-day-column {
    grid-template-rows: repeat(var(--slot-count, 17), 44px);
  }

  .member-slot-bg.available {
    padding: 2px;
    font-size: 10px;
  }

  .member-slot-bg.available span {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .app-screen {
    padding: 14px 14px calc(92px + env(safe-area-inset-bottom));
  }

  .tabbar {
    position: fixed;
    z-index: 50;
    left: 50%;
    bottom: max(10px, env(safe-area-inset-bottom));
    width: min(calc(100% - 28px), 680px);
    display: grid;
    transform: translateX(-50%);
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: 3px;
    margin: 0;
    border: 1px solid rgba(208, 213, 221, 0.9);
    border-radius: 14px;
    padding: 5px;
    background: rgba(255, 255, 255, 0.96);
    box-shadow: 0 10px 28px rgba(24, 34, 48, 0.16);
    backdrop-filter: blur(12px);
  }

  .tabbar .tab {
    flex: 1 1 0;
    min-width: 0;
    min-height: 50px;
    padding: 5px 2px;
    font-size: 10px;
    line-height: 1.15;
    white-space: normal;
    word-break: keep-all;
  }

  .topbar {
    display: flex;
    align-items: stretch;
  }

  .calendar-weekdays,
  .calendar-days {
    gap: 2px;
  }

  .journal-day {
    min-width: 0;
    min-height: 58px;
    padding: 5px 4px;
  }

  .summary-grid .small-button,
  .today-card .primary-button,
  .today-card .small-button {
    min-height: 40px;
    padding: 0 10px;
    font-size: 13px;
  }

  .journal-calendar-card {
    padding: 6px;
  }

  .journal-day span {
    font-size: 10px;
    line-height: 1.15;
    overflow-wrap: anywhere;
  }

  .notice-dialog,
  .change-request-modal {
    align-items: end;
    padding: 12px;
  }

  .notice-dialog {
    --notice-inset-top: max(12px, env(safe-area-inset-top));
    --notice-inset-right: max(12px, env(safe-area-inset-right));
    --notice-inset-bottom: max(12px, env(safe-area-inset-bottom));
    --notice-inset-left: max(12px, env(safe-area-inset-left));
    padding: var(--notice-inset-top) var(--notice-inset-right) var(--notice-inset-bottom) var(--notice-inset-left);
  }

  .notice-card,
  .change-modal-card {
    width: 100%;
    max-height: calc(100dvh - 24px);
    border-radius: 16px 16px 10px 10px;
    padding: 16px;
  }

  .notice-card {
    max-height: calc(100dvh - var(--notice-inset-top) - var(--notice-inset-bottom));
    padding: 0;
  }

  .notice-scroll-region {
    padding: 16px;
  }

  .member-enrollment-grid {
    grid-template-columns: 1fr;
  }

  .member-enrollment-status {
    grid-template-columns: 1fr;
  }

  .member-enrollment-status > span {
    grid-row: auto;
    width: fit-content;
  }

  .modal-actions,
  .notice-actions {
    grid-template-columns: 1fr 1fr;
  }

  .notice-action:not([hidden]) {
    grid-column: 1 / -1;
  }
}

body.sheet-open {
  overflow: hidden;
  overscroll-behavior: none;
}

body.notice-open {
  overflow: hidden;
  overscroll-behavior: none;
}

.journal-primary-actions {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
  margin-bottom: 12px;
  border: 1px solid #b9d7ce;
  border-radius: 8px;
  padding: 14px;
  background: #f2fbf7;
}

.journal-primary-actions > div {
  display: grid;
  gap: 4px;
}

.journal-primary-actions strong {
  color: var(--green);
  font-size: 16px;
}

.journal-primary-actions span {
  color: var(--muted);
  font-size: 13px;
  font-weight: 750;
  line-height: 1.45;
}

.journal-primary-actions .primary-button {
  min-width: 100px;
}

.journal-curriculum-preview {
  margin-bottom: 12px;
}

.app-bottom-sheet[hidden] {
  display: none !important;
}

.app-bottom-sheet {
  position: fixed;
  z-index: 140;
  top: var(--tn-visual-viewport-offset-top, 0px);
  right: 0;
  bottom: auto;
  left: 0;
  height: var(--tn-visual-viewport-height, 100dvh);
  display: grid;
  align-items: end;
  justify-items: center;
  overflow: hidden;
  overscroll-behavior: none;
  touch-action: pan-y;
  max-width: 100vw;
}

.sheet-backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  min-height: 100%;
  border: 0;
  border-radius: 0;
  background: rgba(24, 34, 48, 0.48);
  touch-action: none;
}

.sheet-card {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  width: min(100%, 680px);
  max-width: 100vw;
  height: min(var(--tn-sheet-viewport-height, 86dvh), 760px);
  max-height: min(var(--tn-sheet-viewport-height, 86dvh), 760px);
  overflow: hidden;
  overscroll-behavior: contain;
  touch-action: pan-y;
  border: 1px solid rgba(208, 213, 221, 0.9);
  border-bottom: 0;
  border-radius: 20px 20px 0 0;
  background: var(--wash);
  box-shadow: 0 -18px 48px rgba(24, 34, 48, 0.22);
}

.sheet-handle {
  width: 42px;
  height: 4px;
  margin: 8px auto 0;
  border-radius: 999px;
  background: #b8c1c7;
}

.sheet-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: start;
  padding: 12px 16px 14px;
  border-bottom: 1px solid var(--line);
  background: white;
}

.sheet-head > div {
  display: grid;
  gap: 3px;
}

.sheet-head h3,
.sheet-head p {
  margin: 0;
}

.sheet-head h3 {
  color: var(--ink);
  font-size: 20px;
}

.sheet-head span {
  color: var(--muted);
  font-size: 13px;
  font-weight: 750;
}

.sheet-scroll {
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior-y: contain;
  -webkit-overflow-scrolling: touch;
  touch-action: pan-y;
  padding: 14px 14px calc(20px + env(safe-area-inset-bottom));
}

.sheet-actions {
  display: grid;
  padding: 10px 14px max(10px, env(safe-area-inset-bottom));
  border-top: 1px solid var(--line);
  background: white;
}

#journalComposerSheet .sheet-card {
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  height: min(
    86dvh,
    var(--tn-sheet-viewport-height, 86dvh),
    760px
  );
  max-height: min(
    86dvh,
    var(--tn-sheet-viewport-height, 86dvh),
    760px
  );
}

.journal-composer-actions .primary-button {
  width: 100%;
}

.lesson-detail-sheet-card {
  grid-template-rows: auto auto auto;
  width: min(100%, 520px);
  height: auto;
  max-height: min(78dvh, 620px);
}

.lesson-detail-sheet-scroll {
  display: grid;
  gap: 14px;
  max-height: calc(78dvh - 96px);
}

.lesson-detail-facts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1px;
  overflow: hidden;
  margin: 0;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--line);
}

.lesson-detail-facts > div {
  display: grid;
  gap: 4px;
  min-width: 0;
  padding: 13px 14px;
  background: white;
}

.lesson-detail-facts dt {
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
}

.lesson-detail-facts dd {
  min-width: 0;
  margin: 0;
  overflow-wrap: anywhere;
  color: var(--ink);
  font-size: 15px;
  font-weight: 850;
}

.lesson-detail-message {
  margin: 0;
  padding: 12px 14px;
  border-radius: 8px;
  background: #eef8f3;
  color: #365a4d;
  font-size: 13px;
  font-weight: 750;
  line-height: 1.5;
}

.lesson-detail-actions {
  display: grid;
  gap: 8px;
}

.lesson-detail-actions > button {
  width: 100%;
  min-height: 48px;
}

.lesson-detail-absence-action {
  border-color: #d59a32;
  background: #fff8e8;
  color: #7a4d00;
}

.same-day-absence-sheet .sheet-card {
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  width: min(100%, 520px);
  height: auto;
  max-height: min(78dvh, 620px);
}

.same-day-absence-sheet-scroll,
.same-day-absence-reason-field {
  display: grid;
  gap: 10px;
}

.same-day-absence-policy-summary {
  margin: 0;
  padding: 14px;
  border: 1px solid #efd49e;
  border-radius: 10px;
  background: #fff8e8;
  color: #6d4600;
  font-size: 14px;
  font-weight: 800;
  line-height: 1.55;
}

.same-day-absence-reason-field > span {
  color: var(--ink);
  font-size: 14px;
  font-weight: 850;
}

.same-day-absence-reason-field small {
  color: var(--muted);
  font-size: 12px;
}

.same-day-absence-reason-field textarea {
  width: 100%;
  min-height: 96px;
  resize: vertical;
  font-size: 16px;
  line-height: 1.5;
}

.same-day-absence-sheet .sheet-actions {
  grid-template-columns: minmax(0, 0.8fr) minmax(0, 1.2fr);
  gap: 8px;
}

.same-day-absence-sheet .sheet-actions > button {
  min-height: 48px;
}

@media (max-width: 480px) {
  .lesson-detail-facts {
    grid-template-columns: 1fr;
  }
}

.journal-composer-form,
.profile-editor-form {
  margin: 0;
}

.profile-editor-photo-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.membership-overview {
  display: grid;
  gap: 10px;
  margin-bottom: 12px;
}

.membership-primary-card {
  display: grid;
  gap: 10px;
  border: 1px solid #9acbb9;
  border-radius: 8px;
  padding: 16px;
  background: linear-gradient(135deg, #f4fcf8, #ffffff 72%);
  box-shadow: 0 10px 22px rgba(24, 34, 48, 0.06);
}

.membership-ticket-unit {
  display: grid;
  gap: 8px;
}

.membership-empty-ticket {
  display: grid;
  gap: 6px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 16px;
  background: white;
}

.membership-empty-ticket span,
.membership-multiple-note {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  font-weight: 750;
  line-height: 1.45;
}

.membership-previous-ticket small,
.membership-previous-ticket p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  font-weight: 750;
  line-height: 1.45;
}

.membership-previous-ticket > span {
  color: var(--green);
  font-size: 12px;
  font-weight: 900;
}

.membership-primary-card.is-low {
  border-color: #efc77b;
  background: #fffaf0;
}

.membership-primary-card.is-pending {
  border-color: #e7c48c;
  background: var(--soft-amber);
}

.membership-primary-head,
.membership-remaining-row,
.membership-action-row {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: center;
}

.membership-primary-head span,
.membership-primary-head small,
.membership-period {
  color: var(--muted);
  font-size: 13px;
  font-weight: 850;
}

.membership-primary-card > strong {
  color: var(--ink);
  font-size: 22px;
  line-height: 1.25;
}

.membership-remaining-row > span {
  color: var(--muted);
  font-size: 14px;
  font-weight: 800;
}

.membership-remaining-row b {
  color: var(--green);
  font-size: 30px;
  line-height: 1;
}

.membership-remaining-row em {
  margin-left: 2px;
  font-size: 16px;
  font-style: normal;
}

.membership-progress {
  height: 8px;
  overflow: hidden;
  border-radius: 999px;
  background: #e6ece9;
}

.membership-progress span {
  display: block;
  height: 100%;
  min-width: 0;
  border-radius: inherit;
  background: var(--green);
  transition: width 180ms ease-out;
}

.membership-action-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
}

.membership-action-row button {
  width: 100%;
}

.membership-more-actions {
  grid-column: 1 / -1;
  width: 100%;
}

.membership-more-actions > summary {
  display: grid;
  min-height: 42px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #fff;
  color: var(--muted);
  cursor: pointer;
  font-size: 13px;
  font-weight: 850;
  list-style: none;
}

.membership-more-actions > summary::-webkit-details-marker {
  display: none;
}

.membership-more-actions > div {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-top: 8px;
}

.membership-pending-actions {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 10px;
}

.membership-pending-actions button {
  width: 100%;
}

.membership-pending-actions .danger-button {
  grid-column: 1 / -1;
}

.membership-status-note {
  width: 100%;
  min-height: 42px;
  border: 1px solid #cad6d1;
  border-radius: 8px;
  color: var(--ink);
  background: white;
  font-weight: 850;
}

.membership-details {
  margin-bottom: 10px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: white;
}

.membership-details summary {
  display: flex;
  min-height: 54px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 0 14px;
  color: var(--ink);
  cursor: pointer;
  font-weight: 900;
  list-style: none;
}

.membership-details summary::-webkit-details-marker {
  display: none;
}

.membership-details summary::after {
  content: "›";
  color: #98a2b3;
  font-size: 26px;
  font-weight: 400;
  transition: transform 160ms ease;
}

.membership-details[open] summary {
  border-bottom: 1px solid #edf0f2;
}

.membership-details[open] summary::after {
  transform: rotate(90deg);
}

.membership-details > .history-list,
.membership-details > .list-pager,
.membership-details-body {
  margin: 12px;
}

.membership-details-body {
  display: grid;
  gap: 12px;
}

.profile-summary-menu {
  margin-bottom: 12px;
}

@media (max-width: 560px) {
  .journal-primary-actions {
    grid-template-columns: 1fr;
  }

  .journal-primary-actions .primary-button {
    width: 100%;
  }

  .sheet-card {
    height: min(var(--tn-sheet-viewport-height, 86dvh), 760px);
    max-height: min(var(--tn-sheet-viewport-height, 86dvh), 760px);
  }

  .membership-primary-card {
    padding: 14px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .app-screen,
  .view.is-active {
    animation: none;
  }

  .brand-splash {
    transition: none;
  }
}

@media (max-width: 380px) {
  .app-screen,
  .login-screen {
    padding-left: 10px;
    padding-right: 10px;
  }

  .tab {
    font-size: 10px;
  }

  .modal-actions,
  .notice-actions {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 720px) {
  input,
  select,
  textarea {
    font-size: 16px;
  }
}

/* Tennis Note athletic visual system: presentation only, no member flow changes. */
:root {
  --ink: #12231f;
  --muted: #66766f;
  --line: #d8e2dd;
  --paper: #ffffff;
  --wash: #f3f7f4;
  --green: #087255;
  --blue: #1d6fa5;
  --amber: #a76011;
  --soft-green: #e7f5ee;
  --soft-blue: #edf6fb;
  --soft-amber: #fff5e6;
}

body {
  background: #eaf0ed;
  font-family: "Pretendard Variable", Pretendard, Inter, "Segoe UI", system-ui, -apple-system, sans-serif;
}

.app-shell {
  background: var(--wash);
}

.member-topbar {
  position: relative;
  min-height: 68px;
  margin-bottom: 12px;
  border: 1px solid #dbe6e0;
  border-radius: 8px;
  padding: 11px 14px;
  overflow: hidden;
  background: #ffffff;
  box-shadow: 0 5px 14px rgba(18, 35, 31, 0.05);
}

.member-topbar::after {
  position: absolute;
  right: 10px;
  bottom: -18px;
  width: 84px;
  height: 84px;
  content: "";
  opacity: 0.09;
  background: url("./assets/brand/app-icon-192.png") center / contain no-repeat;
