.change-request-modal.is-inline-confirmation .change-slot-heading,
.change-request-modal.is-inline-confirmation .slot-list {
  display: none !important;
}

.change-request-modal.is-inline-confirmation .schedule-request-card {
  gap: 12px;
}

.change-request-modal.is-inline-confirmation .policy-note {
  margin: 0;
  border-left: 4px solid #13795b;
  padding: 10px 12px;
  background: #f3faf7;
}

