* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
  min-height: 100vh;
  background: #e8efed;
  color: var(--ink);
  font-size: 16px;
  line-height: 1.45;
  font-family:
    Inter, Pretendard, "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont,
    sans-serif;
}

.brand-splash {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  overflow: hidden;
  background: #ffffff;
  opacity: 1;
  transition: opacity 220ms ease, visibility 220ms ease;
}

.brand-splash.is-hidden {
  visibility: hidden;
  pointer-events: none;
  opacity: 0;
}

.brand-splash[hidden] {
  display: none !important;
}

.brand-splash img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.brand-splash span {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
}

.brand-splash-fallback {
  position: absolute;
  left: 50%;
  bottom: max(28px, env(safe-area-inset-bottom));
  width: min(420px, calc(100% - 32px));
  padding: 18px;
  border: 1px solid #cbdad5;
  border-radius: 8px;
  background: rgb(255 255 255 / 96%);
  box-shadow: 0 8px 24px rgb(18 49 45 / 14%);
  text-align: center;
}

.brand-splash-fallback p {
  margin: 6px 0 14px;
  color: #516763;
}

.brand-splash-fallback button {
  min-height: 44px;
  padding: 0 18px;
  border: 0;
  border-radius: 6px;
  background: #0f766e;
  color: #ffffff;
  font-weight: 800;
}

.brand-splash.is-failed img {
  opacity: 0.18;
}

button,
a,
select {
  font: inherit;
}

button {
  cursor: pointer;
}

.app-shell {
  position: relative;
  width: min(980px, 100%);
  min-height: 100vh;
  margin: 0 auto;
  overflow-x: hidden;
  background: var(--wash);
}

.login-screen[hidden],
.app-screen[hidden] {
  display: none !important;
}

.login-screen {
  min-height: 100vh;
  display: grid;
  align-content: center;
  gap: 18px;
  padding: 28px;
}

.brand p,
.topbar p {
  margin: 0 0 6px;
  color: var(--green);
  font-size: 13px;
  font-weight: 900;
}

.brand h1,
.topbar h1,
.section-title h2 {
  margin: 0;
}

.brand h1 {
  font-size: 32px;
}

.login-brand-guidance {
  display: block;
  margin-top: 8px;
  color: var(--muted);
  font-size: 14px;
  font-weight: 700;
  line-height: 1.5;
}

.brand span,
.section-title span,
.login-card p,
.summary-grid small,
.cell small,
.cell span,
.request-card span {
  color: var(--muted);
}

.login-card,
.summary-grid article,
.form-card,
.request-card,
.history-card {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--paper);
  box-shadow: 0 8px 18px rgba(24, 34, 48, 0.05);
}

.login-card {
  display: grid;
  gap: 12px;
  padding: 20px;
}

.session-restoring {
  min-height: 210px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 10px;
  text-align: center;
}

.session-restoring[hidden] { display: none !important; }
.session-restoring small { color: var(--muted); }
.session-restoring-spinner {
  width: 30px;
  height: 30px;
  border: 3px solid #d8e7e2;
  border-top-color: var(--primary);
  border-radius: 50%;
  animation: session-restoring-spin 0.8s linear infinite;
}
.member-session-restoring .login-card > :not(.session-restoring) { display: none !important; }
@keyframes session-restoring-spin { to { transform: rotate(360deg); } }

.login-card h2 {
  margin: 0 0 4px;
}

.onboarding-entry-intro {
  display: grid;
  gap: 5px;
  border: 1px solid rgba(15, 132, 91, 0.26);
  border-radius: 10px;
  padding: 13px 14px;
  background: linear-gradient(115deg, #ecfdf5, #ffffff 76%);
}

.onboarding-entry-intro[hidden] {
  display: none !important;
}

.onboarding-entry-intro span {
  color: var(--green);
  font-size: 12px;
  font-weight: 900;
}

.onboarding-entry-intro strong {
  color: var(--ink);
  font-size: 17px;
  line-height: 1.35;
}

.onboarding-entry-intro small {
  color: var(--muted);
  font-size: 12px;
  font-weight: 750;
  line-height: 1.45;
}

.public-product-preview {
  display: grid;
  gap: 12px;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  padding: 14px 0;
}

.public-product-preview-heading {
  display: grid;
  gap: 5px;
}

.public-product-preview-heading > div {
  display: grid;
  gap: 3px;
}

.public-product-preview-heading span {
  color: var(--green);
  font-size: 12px;
  font-weight: 900;
}

.public-product-preview-heading strong {
  color: var(--ink);
  font-size: 17px;
  line-height: 1.35;
}

.public-product-preview-heading small,
.public-product-preview-note {
  color: var(--muted);
  font-size: 12px;
  font-weight: 750;
  line-height: 1.45;
}

.public-onboarding-existing-login {
  justify-self: center;
  border: 0;
  padding: 4px 6px;
  color: var(--muted);
  background: transparent;
  font: inherit;
  font-size: 13px;
  font-weight: 800;
  line-height: 1.45;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.public-onboarding-existing-login strong {
  color: var(--green);
}

.public-onboarding-existing-login[hidden] {
  display: none !important;
}

.public-product-preview-list {
  display: grid;
  gap: 10px;
}

.public-onboarding-choice-grid,
.public-onboarding-coach-grid,
.public-onboarding-frequency-grid,
.public-onboarding-slot-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.public-onboarding-choice-grid > button,
.public-onboarding-coach-grid > button,
.public-onboarding-frequency-grid > button,
.public-onboarding-slot-grid > button {
  display: grid;
  gap: 4px;
  min-width: 0;
  min-height: 76px;
  align-content: center;
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 12px;
  color: var(--ink);
  background: white;
  font: inherit;
  text-align: left;
}

.public-onboarding-choice-grid > button:hover,
.public-onboarding-coach-grid > button:hover,
.public-onboarding-frequency-grid > button:hover,
.public-onboarding-slot-grid > button:hover,
.public-onboarding-slot-grid > button.is-selected {
  border-color: var(--green);
  background: var(--mint);
}

.public-onboarding-choice-grid span,
.public-onboarding-summary span,
.public-onboarding-selection-count {
  color: var(--green);
  font-size: 12px;
  font-weight: 900;
}

.public-onboarding-choice-grid strong,
.public-onboarding-coach-grid strong,
.public-onboarding-frequency-grid strong,
.public-onboarding-slot-grid strong,
.public-onboarding-summary strong {
  font-size: 14px;
  line-height: 1.35;
}

.public-onboarding-choice-grid small,
.public-onboarding-coach-grid small,
.public-onboarding-frequency-grid small,
.public-onboarding-summary small {
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
  line-height: 1.35;
}

.public-onboarding-coach-grid > button:disabled {
  opacity: 0.52;
  background: var(--soft);
}

.public-onboarding-slot-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.public-onboarding-slot-grid > button {
  min-height: 58px;
  padding: 9px;
  text-align: center;
}

.public-onboarding-slot-grid span {
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
}

.public-onboarding-back {
  justify-self: start;
  border: 0;
  padding: 3px 0;
  background: transparent;
  color: var(--green);
  font: inherit;
  font-size: 13px;
  font-weight: 900;
}

.public-onboarding-loading,
.public-onboarding-empty,
.public-onboarding-summary {
  display: grid;
  gap: 7px;
  border-radius: 14px;
  padding: 16px;
  background: var(--soft);
  color: var(--muted);
  font-size: 13px;
  font-weight: 800;
  line-height: 1.5;
}

.public-onboarding-empty button {
  justify-self: start;
}

.public-onboarding-summary {
  background: var(--mint);
  color: var(--ink);
}

.public-onboarding-login-actions {
  display: grid;
  gap: 10px;
}

.public-onboarding-login-actions h2 {
  margin: 0;
  color: var(--ink);
  font-size: 17px;
  line-height: 1.35;
}

.recent-login-badge {
  justify-self: start;
  border: 1px solid #cfe1d9;
  border-radius: 999px;
  padding: 4px 8px;
  color: #356555;
  background: #f2faf6;
  font-size: 11px;
  font-weight: 800;
  line-height: 1.35;
}

.recent-login-badge[hidden] {
  display: none !important;
}

.public-onboarding-login-actions[hidden] {
  display: none !important;
}

