}

.ntrp-quick-guide article {
  display: grid;
  gap: 3px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 8px;
  background: white;
}

.ntrp-quick-guide strong {
  color: var(--blue);
  font-size: 18px;
}

.ntrp-quick-guide span {
  font-size: 12px;
  font-weight: 950;
}

.ntrp-quick-guide small {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.35;
}

.ntrp-question {
  display: grid;
  gap: 7px;
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px;
  margin: 0;
  background: white;
}

.ntrp-question legend {
  padding: 0 4px;
  font-weight: 950;
}

.ntrp-question label {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 8px;
  align-items: start;
}

.ntrp-question span {
  color: var(--ink);
  font-size: 13px;
  line-height: 1.4;
}

.profile-summary article {
  display: grid;
  gap: 4px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
  background: #f8fafc;
}

.profile-summary span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 900;
}

.profile-summary strong {
  font-size: 14px;
  line-height: 1.35;
}

.schedule-request-card {
  margin-top: 12px;
}

.schedule-request-card h3 {
  margin: 0;
}

.policy-note {
  margin: 0;
  border-radius: 8px;
  padding: 10px;
  color: var(--amber);
  background: var(--soft-amber);
  font-size: 13px;
  font-weight: 900;
  line-height: 1.5;
}

.journal-fields {
  display: grid;
  gap: 12px;
}

.journal-fields[hidden] {
  display: none;
}

.inline-guide {
  margin: -2px 0 12px;
  color: var(--muted);
  font-size: 13px;
  font-weight: 800;
  line-height: 1.5;
}

.slot-list {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  max-height: 210px;
  margin-bottom: 12px;
  overflow: auto;
  padding-right: 2px;
}

.slot-card {
  display: grid;
  gap: 4px;
  min-height: 82px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px;
  text-align: left;
  background: white;
}

.slot-card.is-selected {
  border-color: var(--green);
  background: var(--soft-green);
}

.slot-card.auto-change {
  border-color: #8ac7ad;
}

.slot-card.needs-approval {
  border-color: #f3c98b;
  background: var(--soft-amber);
}

.slot-card strong {
  color: var(--ink);
}

.slot-card span,
.slot-card small {
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
}

.list-heading {
  margin: 14px 0 8px;
}

.journal-calendar-card {
  display: grid;
  gap: 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 14px;
  margin-bottom: 12px;
  background: white;
}

.journal-calendar-card h3,
.journal-calendar-card span {
  margin: 0;
}

.journal-calendar-card span {
  color: var(--muted);
  font-size: 13px;
  font-weight: 800;
}

.journal-calendar-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
}

.journal-calendar-toolbar {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
}

.journal-calendar-controls {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) 44px auto;
  gap: 8px;
  align-items: center;
}

.journal-calendar-controls strong {
  text-align: center;
}

.journal-month-picker-trigger {
  min-width: 0;
  width: 100%;
  padding-inline: 8px;
  border: 1px solid var(--line);
  color: var(--ink);
  background: var(--paper);
}

.journal-month-picker-trigger strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.journal-month-arrow {
  width: 44px;
  min-width: 44px;
  padding: 0;
  font-size: 18px;
}

.journal-today-button {
  min-width: 52px;
  min-height: 44px;
  padding-inline: 10px;
}

.journal-calendar-view-switch {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 2px;
  width: 116px;
  padding: 2px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #f1f5f9;
}

.journal-calendar-view-switch .small-button {
  min-width: 0;
  min-height: 44px;
  padding-inline: 8px;
  border-color: transparent;
  background: transparent;
}

.journal-calendar-view-switch .small-button.is-active {
  border-color: #8ac7ad;
  color: var(--green);
  background: var(--soft-green);
}

.journal-month-picker-sheet .sheet-card {
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  width: min(100%, 440px);
  height: auto;
  max-height: min(var(--tn-sheet-viewport-height, 86dvh), 520px);
}

.journal-month-picker-form {
  margin-bottom: 0;
}

.journal-month-picker-grid,
.journal-month-picker-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.journal-month-picker-grid label {
  min-width: 0;
}

.journal-month-picker-grid select {
  width: 100%;
}

.journal-month-picker-status {
  min-height: 22px;
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  font-weight: 800;
}

.journal-month-picker-status[data-tone="error"] {
  color: #b42318;
}

.journal-month-picker-actions > button {
  width: 100%;
}

.journal-calendar-tools {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(150px, 0.35fr);
  gap: 8px;
}

.journal-tools-disclosure {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #f8fafc;
}

.journal-tools-disclosure summary {
  min-height: 42px;
  padding: 10px 12px;
  color: var(--blue);
  cursor: pointer;
  font-size: 13px;
  font-weight: 900;
}

.journal-tools-disclosure[open] summary {
  border-bottom: 1px solid var(--line);
}

.journal-tools-disclosure .journal-calendar-tools {
  padding: 10px;
}

.journal-calendar {
  display: grid;
  gap: 6px;
}

.calendar-weekdays,
.calendar-days {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 6px;
}

.calendar-weekdays b {
  display: grid;
  min-height: 26px;
  place-items: center;
  color: var(--muted);
  font-size: 12px;
}

.calendar-empty {
  min-height: 54px;
}

.journal-day {
  display: grid;
  gap: 2px;
  min-height: 54px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 6px;
  text-align: left;
  background: #f8fafc;
}

.journal-day strong {
  color: var(--ink);
  font-size: 14px;
}

.journal-day span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 900;
}

.journal-day.has-lesson {
  background: var(--soft-blue);
}

.journal-day.has-record {
  border-color: #8ac7ad;
  background: var(--soft-green);
}

.journal-day.is-selected {
  border-color: #2563eb;
  box-shadow: inset 0 0 0 2px rgba(37, 99, 235, 0.16);
}

.journal-day.matches-search {
  outline: 2px solid rgba(37, 99, 235, 0.2);
}

.journal-calendar.is-week-view .journal-day {
  min-height: 68px;
  align-content: start;
}

.journal-calendar.is-week-view .journal-day strong {
  white-space: nowrap;
}

.journal-calendar.is-week-view .journal-day span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.journal-selected-panel {
  display: grid;
  gap: 10px;
  border-top: 1px solid var(--line);
  padding-top: 12px;
}

.journal-selected-heading {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
}

.journal-selected-heading div,
.journal-selected-list,
.journal-selected-card,
.journal-selected-meta {
  display: grid;
  gap: 6px;
}

.journal-selected-heading strong {
  color: var(--ink);
}

.journal-selected-list {
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}

.journal-selected-card {
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
  background: #f8fafc;
}

.journal-selected-card.lesson {
  background: var(--soft-blue);
}

.journal-selected-card.practice {
  background: var(--soft-green);
}

.journal-selected-card-head {
  display: grid;
  gap: 4px;
}

.journal-selected-card-head span {
  color: var(--accent);
  font-size: 12px;
}

.journal-selected-card-head small,
.journal-selected-meta,
.journal-selected-card p {
  color: var(--muted);
  line-height: 1.5;
}

.journal-selected-card p {
  margin: 0;
}

.journal-selected-card-action {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
}

.journal-selected-card-action > span {
  min-width: 0;
  overflow: hidden;
  color: var(--muted);
  font-size: 12px;
  font-weight: 750;
  text-overflow: ellipsis;
  white-space: nowrap;
}

label {
  display: grid;
  gap: 6px;
  color: var(--muted);
  font-size: 13px;
  font-weight: 900;
}

select {
  width: 100%;
  min-height: 42px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 0 10px;
  background: white;
  color: var(--ink);
}

textarea {
  width: 100%;
  min-height: 90px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px;
  resize: vertical;
  color: var(--ink);
  font: inherit;
}

.primary-button {
  color: white;
  background: var(--green);
}

.request-list,
.history-list {
  display: grid;
  gap: 8px;
}

.ticket-overview {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 12px;
}

.member-alert-list {
  display: grid;
  gap: 8px;
  margin: 0 0 12px;
}

.member-alert-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
  background: white;
}

.member-alert-card.alert {
  border-color: #f3b8aa;
  background: #fff0ee;
}

.member-alert-card.wait {
  border-color: #f3c98b;
  background: var(--soft-amber);
}

.member-alert-card div {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.member-alert-card strong,
.member-alert-card span,
.member-alert-card small {
  min-width: 0;
  overflow-wrap: anywhere;
}

.member-alert-card span,
.member-alert-card small {
  color: var(--muted);
  line-height: 1.45;
}

.member-alert-card b {
  border-radius: 999px;
  padding: 7px 10px;
  color: #8a1f16;
  background: rgba(255, 255, 255, 0.74);
  font-size: 12px;
  white-space: nowrap;
}

.renewal-policy-panel,
.flow-guide {
  display: grid;
  gap: 10px;
  margin-bottom: 12px;
}

.renewal-policy-panel {
  grid-template-columns: minmax(0, 1.2fr) minmax(260px, 0.8fr);
}

.flow-guide {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.member-enrollment-status {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 4px 12px;
  align-items: center;
  border: 1px solid #b9d7ce;
  border-radius: 8px;
  padding: 13px 14px;
  background: #eef8f4;
}

.member-enrollment-status > span {
  grid-row: 1 / span 2;
  border-radius: 999px;
  padding: 6px 9px;
  color: var(--green);
  background: white;
  font-size: 11px;
  font-weight: 950;
  white-space: nowrap;
}

.member-enrollment-status strong,
.member-enrollment-status p {
  min-width: 0;
}

.member-enrollment-status p {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.45;
}

.member-enrollment-status.wait {
  border-color: #f0c781;
  background: var(--soft-amber);
}

.member-enrollment-status.journal {
  border-color: #bfd3eb;
  background: var(--soft-blue);
}

.renewal-card,
.flow-card {
  display: grid;
  gap: 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 14px;
  background: white;
}

.renewal-card.alert {
  border-color: #f3b8aa;
  background: #fff0ee;
}

.renewal-card span,
.flow-card span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 900;
}

.renewal-card strong,
.flow-card strong {
  color: var(--ink);
  line-height: 1.35;
}

.renewal-card p,
.flow-card p {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  font-weight: 750;
  line-height: 1.55;
}

.flow-card div {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.flow-card div span {
  border-radius: 999px;
  padding: 5px 8px;
  background: var(--soft-blue);
  color: var(--blue);
}

.ticket-card {
  display: grid;
  gap: 6px;
  min-height: 112px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 14px;
  background: white;
}

.ticket-card.primary {
  border-color: #34a77a;
  background: #dff7ec;
}

.ticket-card.alert {
  border-color: #f3b8aa;
  background: #fff0ee;
}

.ticket-card.wait {
  border-color: #f3c98b;
  background: var(--soft-amber);
}

.ticket-action-card {
  grid-column: 1 / -1;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  min-height: auto;
}

.ticket-action-card div {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.ticket-action-buttons {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.ticket-action-buttons .primary-button,
.ticket-action-buttons .small-button {
  align-self: center;
  white-space: nowrap;
}

.ticket-action-buttons .primary-button:disabled,
.ticket-action-buttons .small-button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.ticket-check-status {
  width: fit-content;
  border-radius: 999px;
  padding: 5px 8px;
  background: white;
}

.ticket-check-status.done {
  color: var(--green);
}

.ticket-check-status.alert {
  color: var(--danger);
}

.ticket-card span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 900;
}

.ticket-card strong {
  color: var(--ink);
  font-size: 22px;
}

.ticket-card small {
  color: var(--muted);
  font-weight: 800;
}

.lesson-status-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
  background: white;
}

.lesson-status-card.done {
  background: var(--soft-green);
}

.lesson-status-card.wait {
  background: var(--soft-amber);
}

.lesson-status-card div:first-child {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.lesson-status-card strong,
.lesson-status-card span,
.lesson-status-card small {
  min-width: 0;
  overflow-wrap: anywhere;
}

.lesson-status-card span,
.lesson-status-card small {
  color: var(--muted);
  font-size: 13px;
  font-weight: 800;
}

.lesson-status-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.notion-link {
  display: inline-grid;
  min-height: 34px;
  align-items: center;
  text-decoration: none;
}

.request-card,
.history-card {
  display: grid;
  gap: 4px;
  padding: 12px;
}

.compact-log {
  gap: 7px;
}

.summary-log {
  width: 100%;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  border: 1px solid var(--line);
  color: inherit;
  cursor: pointer;
  font: inherit;
  text-align: left;
}

.summary-log:hover,
.curriculum-compact-card:hover {
  border-color: rgba(37, 99, 235, 0.34);
  transform: translateY(-1px);
}

.summary-log-main {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.summary-log-main strong,
.summary-log-main small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.summary-log-status {
  display: inline-grid;
  min-height: 30px;
  align-items: center;
  border-radius: 999px;
  padding: 0 10px;
  background: rgba(255, 255, 255, 0.66);
  color: var(--ink);
  font-size: 12px;
  font-weight: 900;
  white-space: nowrap;
}

.compact-log .small-button {
  justify-self: start;
  min-height: 34px;
}

.request-card b {
  color: var(--amber);
  font-size: 13px;
}

.history-card.done {
  background: var(--soft-green);
}

.history-card.wait {
  background: var(--soft-amber);
}

.history-card.alert {
  border-color: #f3b8aa;
  background: #fff0ee;
}

.history-card strong,
.history-card b {
  font-size: 14px;
}

.history-card small {
  color: var(--muted);
  line-height: 1.5;
}

.list-pager {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 10px;
  flex-wrap: wrap;
}

.list-pager span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 900;
}

.page-number-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.page-number {
  display: inline-grid;
  min-width: 34px;
  min-height: 34px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: white;
  color: var(--muted);
  font-weight: 950;
  cursor: pointer;
}

.page-number.is-current {
  border-color: rgba(21, 122, 91, 0.42);
  background: var(--green);
  color: white;
}

.pass-history-card {
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px 12px;
}

.pass-history-card div {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.pass-history-card b {
  justify-self: end;
  border-radius: 999px;
  padding: 6px 10px;
  background: rgba(255, 255, 255, 0.72);
  color: var(--green);
  font-size: 12px;
  white-space: nowrap;
}

.pass-history-card > small {
  grid-column: 1 / -1;
}

.form-help {
  margin: -4px 0 12px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.5;
}

.journal-detail-card {
  display: grid;
  gap: 10px;
}

.journal-detail-card p {
  margin: 0 0 6px;
  color: var(--muted);
  line-height: 1.6;
}

.journal-detail-card strong {
  color: var(--ink);
}

/* Simplified membership purchase: five primary tabs and one-page checkout. */
.tabbar {
  grid-template-columns: repeat(5, minmax(0, 1fr));
}

.membership-product-browser,
.membership-purchase-flow {
  display: grid;
  gap: 14px;
  margin-bottom: 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 16px;
  background: #ffffff;
  box-shadow: 0 8px 22px rgba(18, 35, 31, 0.055);
}

.membership-product-browser[hidden],
.membership-purchase-flow[hidden],
.membership-current-disclosure[hidden],
.membership-help-disclosure[hidden] {
  display: none !important;
}

.membership-current-disclosure > summary small {
  margin-left: auto;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  text-align: right;
}

.membership-current-disclosure > .current-ticket-panel,
.membership-current-disclosure > .membership-details {
  margin: 12px;
}

.membership-current-disclosure > .current-ticket-panel {
  margin-bottom: 0;
}

.membership-current-disclosure:not([open]) > :not(summary),
.membership-current-disclosure .membership-details:not([open]) > :not(summary) {
  display: none !important;
}

@media (max-width: 560px) {
  .membership-current-disclosure > summary small {
    display: none;
  }
}

.membership-browser-heading,
.membership-purchase-head,
.product-group-heading,
.purchase-product-options > div:first-child,
.purchase-selected-summary,
.purchase-order-summary > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.membership-browser-heading > div,
.membership-purchase-head > div,
.purchase-step-intro,
.purchase-selected-summary,
.purchase-order-summary > div,
.purchase-complete-card {
