  background: white;
}

.membership-empty-ticket span,
.membership-multiple-note {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  font-weight: 750;
  line-height: 1.45;
}

.membership-previous-ticket small,
.membership-previous-ticket p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  font-weight: 750;
  line-height: 1.45;
}

.membership-previous-ticket > span {
  color: var(--green);
  font-size: 12px;
  font-weight: 900;
}

.membership-primary-card.is-low {
  border-color: #efc77b;
  background: #fffaf0;
}

.membership-primary-card.is-pending {
  border-color: #e7c48c;
  background: var(--soft-amber);
}

.membership-primary-head,
.membership-remaining-row,
.membership-action-row {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: center;
}

.membership-primary-head span,
.membership-primary-head small,
.membership-period {
  color: var(--muted);
  font-size: 13px;
  font-weight: 850;
}

.membership-primary-card > strong {
  color: var(--ink);
  font-size: 22px;
  line-height: 1.25;
}

.membership-remaining-row > span {
  color: var(--muted);
  font-size: 14px;
  font-weight: 800;
}

.membership-remaining-row b {
  color: var(--green);
  font-size: 30px;
  line-height: 1;
}

.membership-remaining-row em {
  margin-left: 2px;
  font-size: 16px;
  font-style: normal;
}

.membership-progress {
  height: 8px;
  overflow: hidden;
  border-radius: 999px;
  background: #e6ece9;
}

.membership-progress span {
  display: block;
  height: 100%;
  min-width: 0;
  border-radius: inherit;
  background: var(--green);
  transition: width 180ms ease-out;
}

.membership-action-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
}

.membership-action-row button {
  width: 100%;
}

.membership-more-actions {
  grid-column: 1 / -1;
  width: 100%;
}

.membership-more-actions > summary {
  display: grid;
  min-height: 42px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #fff;
  color: var(--muted);
  cursor: pointer;
  font-size: 13px;
  font-weight: 850;
  list-style: none;
}

.membership-more-actions > summary::-webkit-details-marker {
  display: none;
}

.membership-more-actions > div {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-top: 8px;
}

.membership-pending-actions {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 10px;
}

.membership-pending-actions button {
  width: 100%;
}

.membership-pending-actions .danger-button {
  grid-column: 1 / -1;
}

.membership-status-note {
  width: 100%;
  min-height: 42px;
  border: 1px solid #cad6d1;
  border-radius: 8px;
  color: var(--ink);
  background: white;
  font-weight: 850;
}

.membership-details {
  margin-bottom: 10px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: white;
}

.membership-details summary {
  display: flex;
  min-height: 54px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 0 14px;
  color: var(--ink);
  cursor: pointer;
  font-weight: 900;
  list-style: none;
}

.membership-details summary::-webkit-details-marker {
  display: none;
}

.membership-details summary::after {
  content: "›";
  color: #98a2b3;
  font-size: 26px;
  font-weight: 400;
  transition: transform 160ms ease;
}

.membership-details[open] summary {
  border-bottom: 1px solid #edf0f2;
}

.membership-details[open] summary::after {
  transform: rotate(90deg);
}

.membership-details > .history-list,
.membership-details > .list-pager,
.membership-details-body {
  margin: 12px;
}

.membership-details-body {
  display: grid;
  gap: 12px;
}

.profile-summary-menu {
  margin-bottom: 12px;
}

@media (max-width: 560px) {
  .journal-primary-actions {
    grid-template-columns: 1fr;
  }

  .journal-primary-actions .primary-button {
    width: 100%;
  }

  .sheet-card {
    height: min(var(--tn-sheet-viewport-height, 86dvh), 760px);
    max-height: min(var(--tn-sheet-viewport-height, 86dvh), 760px);
  }

  .membership-primary-card {
    padding: 14px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .app-screen,
  .view.is-active {
    animation: none;
  }

  .brand-splash {
    transition: none;
  }
}

@media (max-width: 380px) {
  .app-screen,
  .login-screen {
    padding-left: 10px;
    padding-right: 10px;
  }

  .tab {
    font-size: 10px;
  }

  .modal-actions,
  .notice-actions {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 720px) {
  input,
  select,
  textarea {
    font-size: 16px;
  }
}

/* Tennis Note athletic visual system: presentation only, no member flow changes. */
:root {
  --ink: #12231f;
  --muted: #66766f;
  --line: #d8e2dd;
  --paper: #ffffff;
  --wash: #f3f7f4;
  --green: #087255;
  --blue: #1d6fa5;
  --amber: #a76011;
  --soft-green: #e7f5ee;
  --soft-blue: #edf6fb;
  --soft-amber: #fff5e6;
}

body {
  background: #eaf0ed;
  font-family: "Pretendard Variable", Pretendard, Inter, "Segoe UI", system-ui, -apple-system, sans-serif;
}

.app-shell {
  background: var(--wash);
}

.member-topbar {
  position: relative;
  min-height: 68px;
  margin-bottom: 12px;
  border: 1px solid #dbe6e0;
  border-radius: 8px;
  padding: 11px 14px;
  overflow: hidden;
  background: #ffffff;
  box-shadow: 0 5px 14px rgba(18, 35, 31, 0.05);
}

.member-topbar::after {
  position: absolute;
  right: 10px;
  bottom: -18px;
  width: 84px;
  height: 84px;
  content: "";
  opacity: 0.09;
  background: url("./assets/brand/app-icon-192.png") center / contain no-repeat;
  pointer-events: none;
}

.member-heading {
  position: relative;
  z-index: 1;
}

.summary-grid article,
.today-card,
.form-card,
.request-card,
.history-card {
  border-color: #dbe6e0;
  box-shadow: 0 5px 14px rgba(18, 35, 31, 0.045);
}

.summary-grid .summary-card.primary {
  position: relative;
  overflow: hidden;
  border-color: #a8d9c7;
  background: var(--soft-green);
}

.summary-grid .summary-card.primary::after {
  position: absolute;
  right: 12px;
  bottom: 8px;
  width: 62px;
  height: 62px;
  content: "";
  opacity: 0.14;
  background: url("./assets/brand/app-icon-192.png") center / contain no-repeat;
  pointer-events: none;
}

.summary-grid .summary-card.primary > * {
  position: relative;
  z-index: 1;
}

.summary-grid strong {
  color: #075b45;
}

.home-change-button {
  border-color: #0c7658;
  border-radius: 8px;
  background: #087255;
  box-shadow: 0 7px 16px rgba(8, 114, 85, 0.2);
}

.home-change-button strong,
.home-change-button span {
  color: #ffffff;
}

.tabbar {
  gap: 6px;
}

.tab {
  border: 1px solid #dbe6e0;
  background: #ffffff;
}

.tab.is-active {
  border-color: #087255;
  background: #087255;
}

@media (max-width: 720px) {
  .app-screen {
    padding-bottom: calc(88px + env(safe-area-inset-bottom));
  }

  .member-topbar {
    min-height: 64px;
    margin-bottom: 10px;
  }

  .tabbar {
    position: fixed;
    z-index: 50;
    left: 50%;
    bottom: max(8px, env(safe-area-inset-bottom));
    width: min(calc(100% - 20px), 560px);
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    transform: translateX(-50%);
    gap: 3px;
    margin: 0;
    border: 1px solid #dbe6e0;
    border-radius: 8px;
    padding: 4px;
    background: rgba(255, 255, 255, 0.98);
    box-shadow: 0 10px 24px rgba(18, 35, 31, 0.16);
  }

  .tabbar .tab {
    min-width: 0;
    min-height: 48px;
    padding: 4px 2px;
    border-color: transparent;
    font-size: 10px;
    line-height: 1.15;
    white-space: normal;
    word-break: keep-all;
  }
}
.member-schedule-mode {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
  margin: 0 0 12px;
  padding: 4px;
  border: 1px solid #d8e1e8;
  background: #f4f7f8;
}

.member-schedule-mode-button {
  min-height: 42px;
  border: 0;
  background: transparent;
  color: #52616b;
  font-weight: 700;
}

.member-schedule-mode-button.is-active {
  background: #13795b;
  color: #fff;
}

.member-schedule-guide {
  margin: -4px 2px 12px;
  color: #52616b;
  font-size: 13px;
  line-height: 1.45;
}

.member-ticket-summary,
.member-booking-summary {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  gap: 8px 12px;
  margin-bottom: 10px;
  border: 1px solid #b9d7ce;
  border-left: 4px solid var(--green);
  border-radius: 10px;
  padding: 10px 12px;
  background: #f4fbf8;
}

.member-ticket-summary-copy,
.member-booking-summary-main {
  display: grid;
  min-width: 0;
  gap: 2px;
}

.member-ticket-summary-copy > span,
.member-booking-summary-main > span {
  color: var(--green);
  font-size: 11px;
  font-weight: 900;
}

.member-ticket-summary-copy > strong,
.member-booking-summary-main > strong {
  overflow: hidden;
  color: var(--ink);
  font-size: 14px;
  font-weight: 900;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.member-ticket-summary-copy > small,
.member-booking-summary-main > small {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.35;
}

.member-ticket-summary-switch,
.member-booking-source-switch {
  display: grid;
  min-width: 112px;
  gap: 3px;
  color: #155b47;
  font-size: 10px;
  font-weight: 900;
}

.member-ticket-summary-switch select,
.member-booking-source-switch select {
  width: min(190px, 34vw);
  min-height: 36px;
  border: 1px solid #9bc8b7;
  border-radius: 8px;
  padding: 6px 28px 6px 8px;
  color: #155b47;
  font-size: 11px;
  font-weight: 800;
  background: #fff;
}

.member-booking-instruction {
  display: flex;
  grid-column: 1 / -1;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin: 2px 0 0;
  border-top: 1px solid #d7e8e2;
  padding-top: 7px;
}

.member-booking-instruction strong {
  color: #155b47;
  font-size: 12px;
}

.member-booking-instruction span {
  color: #52616b;
  font-size: 11px;
  text-align: right;
}

.member-booking-period {
  white-space: normal;
}

.member-booking-summary.has-period-warning {
  border-color: #e1b157;
  border-left-color: #c48722;
  background: #fff8e7;
}

.member-booking-summary.has-period-warning .member-booking-period {
  color: #8a5a12;
  font-weight: 800;
}

.member-inline-change {
  display: grid;
  grid-template-columns: minmax(240px, 1.15fr) minmax(220px, 1fr) auto;
  align-items: end;
  gap: 10px;
  margin-bottom: 12px;
  border: 1px solid #b9d7ce;
  padding: 12px;
  background: #f3faf7;
}

.member-inline-change label.is-coupon-source select {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

.member-inline-coupon-source {
  display: grid;
  gap: 2px;
  min-width: 0;
  border: 1px solid #9bc8b7;
  border-radius: 7px;
  padding: 9px 10px;
  background: #eef9f5;
}

.member-inline-coupon-source strong,
.member-inline-coupon-source small {
  overflow: hidden;
  min-width: 0;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.member-inline-coupon-source strong {
  color: #174c3a;
  font-size: 13px;
}

.member-inline-coupon-source small {
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
}

.member-inline-coupon-source .member-coupon-period {
  white-space: normal;
  line-height: 1.35;
}

.member-inline-coupon-source.has-period-warning {
  border-color: #e1b157;
  background: #fff8e7;
}

.member-inline-coupon-source.has-period-warning .member-coupon-period {
  color: #8a5a12;
}

.member-coupon-quick-start {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(220px, auto);
  gap: 12px;
  align-items: center;
  margin-bottom: 12px;
  border: 1px solid #b8d9cc;
  border-left: 4px solid var(--green);
  padding: 11px 12px;
  background: #f4fbf8;
}

.member-coupon-quick-start > div {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.member-coupon-quick-start > div:first-child > span {
  color: var(--green);
  font-size: 11px;
  font-weight: 900;
}

.member-coupon-quick-start > div:first-child > strong {
  color: var(--ink);
  font-size: 14px;
}

.member-coupon-quick-start > div:first-child > small {
  color: var(--muted);
  font-size: 11px;
}

.member-coupon-ticket-button {
  display: grid;
  gap: 2px;
  min-width: 0;
  min-height: 46px;
  border: 1px solid #c9d8d3;
  border-radius: 7px;
  padding: 7px 9px;
  color: var(--ink);
  background: #fff;
  text-align: left;
}

.member-coupon-ticket-button span,
.member-coupon-ticket-button small {
  overflow: hidden;
  min-width: 0;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.member-coupon-ticket-button span {
  font-size: 12px;
  font-weight: 900;
}

.member-coupon-ticket-button small {
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
}

.member-coupon-ticket-button.is-active {
  border-color: var(--green);
  box-shadow: inset 3px 0 0 var(--green);
  background: #fff;
}

.member-inline-change label,
.member-inline-change p {
  display: grid;
  min-width: 0;
  gap: 5px;
  margin: 0;
}

.member-inline-change label > span,
.member-inline-change p > strong {
  color: #155b47;
  font-size: 12px;
  font-weight: 800;
}

.member-inline-change select {
  width: 100%;
  min-width: 0;
  min-height: 42px;
}

.member-inline-change p > span {
  color: #52616b;
  font-size: 12px;
  line-height: 1.4;
}

.member-ticket-picker {
  display: grid;
  gap: 8px;
  margin-bottom: 12px;
}

.member-ticket-picker > strong {
  color: #173f35;
  font-size: 13px;
}

.member-ticket-picker > div {
  display: flex;
  gap: 7px;
  overflow-x: auto;
  padding-bottom: 2px;
  scrollbar-width: thin;
}

.member-ticket-picker-button {
  display: grid;
  flex: 0 0 min(260px, 78vw);
  min-width: 0;
  min-height: 52px;
  gap: 3px;
  border: 1px solid #ccd9d5;
  padding: 8px 10px;
  color: #445851;
  text-align: left;
  background: #fff;
}

.member-ticket-picker-button span {
  overflow: hidden;
  font-size: 13px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.member-ticket-picker-button small {
  color: #667a73;
  font-size: 11px;
}

.member-ticket-picker-button.is-active {
  border-color: #13795b;
  color: #0d5b45;
  background: #e9f7f1;
  box-shadow: inset 0 0 0 1px #13795b;
}

.member-booking-shortcuts {
  display: grid;
  gap: 0;
  margin-top: 12px;
  border: 1px solid #d8e1e8;
  padding: 10px 12px;
  background: #fff;
}

.member-booking-shortcuts article {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-width: 0;
  padding: 8px 0;
}

.member-booking-shortcuts article + article {
  border-top: 1px solid #e7ecef;
}

.member-booking-shortcuts article > div {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.member-booking-shortcuts span {
  color: #667780;
  font-size: 12px;
}

.member-assigned-coaches {
  display: grid;
  gap: 8px;
  margin-bottom: 12px;
  border-left: 4px solid var(--green);
  padding: 10px 12px;
  background: var(--soft-green);
}

.member-assigned-coaches > strong {
  color: var(--green);
  font-size: 12px;
}

.member-assigned-coaches > div {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.member-assigned-coaches > div > span {
  display: grid;
  gap: 1px;
  min-width: min(180px, 100%);
  border: 1px solid #cfe2dc;
  border-radius: 6px;
  padding: 7px 9px;
  background: #fff;
}

.member-assigned-coaches b {
  color: var(--ink);
  font-size: 13px;
}

.member-assigned-coaches small,
.member-assigned-coaches.is-empty > span,
.member-assigned-coaches.is-setup > span {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.35;
}

.member-assigned-coaches.is-empty {
  border-left-color: var(--amber);
  background: #fff8e7;
}

.member-assigned-coaches.is-empty > strong,
.member-assigned-coaches.is-setup > strong {
  color: #8a5a12;
}

.member-assigned-coaches.is-setup {
  border-left-color: var(--amber);
  background: #fff8e7;
}

.member-availability-overview,
.member-flex-booking {
  display: grid;
  gap: 10px;
  margin-bottom: 12px;
}

.member-availability-overview {
  border: 1px solid #d8e1e8;
  padding: 12px;
  background: #fff;
}

.member-availability-heading,
.member-availability-heading > div,
.member-availability-day > strong {
  display: flex;
  align-items: center;
}

.member-availability-heading {
  justify-content: space-between;
  gap: 10px;
}

.member-availability-heading > div,
.member-availability-day > strong {
  gap: 7px;
}

.member-availability-heading span,
.member-availability-day small {
  color: #667780;
  font-size: 12px;
}

.member-availability-days,
.member-availability-day,
.member-availability-day > div {
  display: grid;
  gap: 8px;
}

.member-availability-day {
  border-top: 1px solid #edf1f3;
  padding-top: 9px;
}

.member-availability-day > div {
  grid-template-columns: repeat(auto-fit, minmax(118px, 1fr));
}

.member-availability-details > summary {
  cursor: pointer;
  color: #155b47;
  font-size: 13px;
  font-weight: 900;
}

.member-availability-details[open] > summary {
  margin-bottom: 9px;
}

.member-availability-slot {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 7px;
  min-height: 48px;
  border: 1px solid #bfd2f5;
  border-radius: 7px;
  padding: 8px 10px;
  color: #17375f;
  background: #f1f6ff;
  text-align: left;
}

.member-availability-slot span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.member-availability-slot small {
  color: #2f5fae;
  font-weight: 800;
}

.member-availability-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
}

.member-flex-booking {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.member-flex-booking article {
  display: grid;
  align-content: start;
  gap: 10px;
  border: 1px solid #d8e1e8;
  padding: 14px;
  background: #fff;
}

.member-flex-booking article > div {
  display: grid;
  gap: 3px;
}

.member-flex-booking article > div span,
.member-flex-booking p {
  color: #667780;
  font-size: 13px;
}

.member-flex-booking p {
  margin: 0;
}

@media (max-width: 720px) {
  .member-schedule-mode {
    gap: 3px;
    padding: 3px;
  }

  .member-schedule-mode-button {
    min-height: 44px;
    padding: 4px;
    font-size: 12px;
    line-height: 1.2;
    word-break: keep-all;
  }

  .member-flex-booking {
    grid-template-columns: 1fr;
  }

  .member-coupon-quick-start {
    grid-template-columns: 1fr;
  }
}

.member-own-schedule {
  border: 1px solid #d8e1e8;
  background: #fff;
  padding: 14px;
}

.member-own-schedule-head,
.member-own-lesson {
  display: flex;
  align-items: center;
  gap: 12px;
}

.member-own-schedule-head {
